/* Prexis extra curriculum. Merges into PREXIS_CONTENT. */
window.PREXIS_EXTRA = {"courses": [{"id": "web-intermediate", "subject": "Web development", "level": "Intermediate", "title": "Websites you run", "track": "web", "prereq": "web-pages", "rev": "2026-09-30", "unlock": {"after": "web-pages", "mastery": 55, "skill": "HTML & CSS"}, "blurb": "Ship it live, multi page sites, forms, SEO, motion, images, JavaScript, Git.", "units": [{"title": "Go live", "lessons": [{"title": "Put your site online", "keywords": ["ship", "deploy", "hosting", "netlify", "github", "pages", "vercel", "export", "live", "publish", "favicon"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free account on Netlify, GitHub or Vercel, and an email address to sign up. All three have free plans and none needs a card for a static site. Cost: free. This lesson asks for your live address at the end, so it is the first one you finish outside Prexis."}, {"type": "concept", "heading": "A static site is just files", "body": "Hosting is a computer that is always on and hands your files to anyone who asks. Your Workshop site is HTML and CSS with no server code, so any static host can serve it. GitHub Pages, Netlify and Vercel all have free plans with HTTPS built in."}, {"type": "mcq", "prompt": "Which files does a static host need to serve your Workshop site?", "options": ["A database and a server program", "An index.html with your page and styles", "Only the CSS file", "A copy of Prexis itself"], "answer": 1, "explain": "Static hosting serves files as they are. index.html is the file a host sends when someone opens your address."}, {"type": "concept", "heading": "Export my site", "body": "Open the Workshop and press Export my site. Prexis downloads one file, index.html. Your CSS is inlined in a style tag and your title, meta and icon tags move into the head. That single file is a complete website you can upload anywhere."}, {"type": "order", "prompt": "Put your site on Netlify Drop.", "items": ["Press Export my site in the Workshop", "Put index.html alone in a new folder", "Open app.netlify.com/drop and sign in", "Drag the folder onto the page", "Open the URL Netlify gives you"], "explain": "Export, package, upload, verify. The folder matters: Netlify publishes whatever folder you drop, and serves index.html at the root.", "codeItems": false, "orderNote": "Each step needs the one before it."}, {"type": "worked", "heading": "GitHub Pages without a terminal", "problem": "Publish the exported index.html from a GitHub repository using only the website.", "steps": ["Create a free account at github.com, then New repository. Name it yourname.github.io and make it public.", "On the repo page choose Add file, then Upload files. Drop index.html and press Commit changes.", "Open Settings, then Pages. Under Build and deployment pick Deploy from a branch, branch main, folder / (root). Save.", "Wait a minute, then open https://yourname.github.io. On Vercel the same file works: Add New, Project, import the repo, no build command, Deploy."], "takeaway": "Every free host follows the same shape: put index.html at the root, point the host at it, open the URL."}, {"type": "build", "prompt": "Get your page ready to ship: give it a title, a meta description and a favicon. Put them at the top of your HTML; Export moves them into the head for you. The Workshop cannot hold a favicon.ico file, so use an inline icon (a data: URL, as in the example) or a full https link to one. Then deploy it and paste your live URL.", "example": "<title>Casa Verde</title>\n<meta name=\"description\" content=\"Weeknight recipes that actually work.\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22%3E%3Ctext y=%22.9em%22 font-size=%2290%22%3E%F0%9F%8C%BF%3C/text%3E%3C/svg%3E\">", "explain": "A title for the tab, a description for search results, an icon for bookmarks. Your site now exists on the real internet.", "checks": [{"sel": "title", "exists": true, "label": "A title element"}, {"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description with content"}, {"sel": "link[rel~=\"icon\"]", "attr": "href", "label": "A favicon the export carries: an inline data: icon or a full https URL", "match": "^(data:image/|https://)", "hint": "href=\"favicon.ico\" points at a file your export does not include. Use the inline icon from the example, or a full https URL to an icon."}, {"url": "liveUrl", "label": "Your live site address (starts with https://)", "kind": "site"}]}, {"type": "mcq", "prompt": "You uploaded your site but the root URL shows a 404 page. What is the most likely cause?", "options": ["DNS is broken", "The CSS is too long", "The file is not named index.html, or it sits inside a subfolder", "HTTPS is off"], "answer": 2, "explain": "Hosts look for index.html at the root of what you published. A file named mysite.html, or one tucked inside a folder, never gets served at /."}]}, {"title": "Multi page sites and navigation", "keywords": ["pages", "navigation", "nav", "links", "relative", "paths", "aria-current", "multi"], "steps": [{"type": "concept", "heading": "Paths are directions", "body": "href=\"about.html\" means: a file next to this one. href=\"../index.html\" means: up one folder, then index.html. href=\"/\" means: the root of the site. Relative links keep working on any host, any domain, and on your own computer.", "code": "<a href=\"about.html\">About</a>\n<a href=\"../index.html\">Home</a>"}, {"type": "mcq", "prompt": "You are on /blog/post.html. Which href reaches the home page at /index.html?", "options": ["index.html", "../index.html", "./blog/index.html", "post.html"], "answer": 1, "explain": "index.html alone would look inside /blog/. ../ climbs one folder to the root first."}, {"type": "concept", "heading": "Mark where you are", "body": "aria-current=\"page\" on the link to the current page tells screen readers you are here, and gives you a styling hook. Every page has the same nav; only the aria-current link changes."}, {"type": "build", "prompt": "Give your site a shared nav: a nav element with links to index.html, about.html and contact.html, and aria-current=\"page\" on the Home link. The Workshop holds one page; after you export, copy it to make about.html and contact.html and move aria-current in each copy.", "example": "<nav aria-label=\"Main\">\n  <a href=\"index.html\" aria-current=\"page\">Home</a>\n  <a href=\"about.html\">About</a>\n  <a href=\"contact.html\">Contact</a>\n</nav>", "explain": "One nav, copied to every page, with the current page marked. Visitors and screen readers both know where they are.", "checks": [{"sel": "nav a", "count": 3, "label": "A nav with at least 3 links"}, {"sel": "nav a[href$=\"about.html\"]", "exists": true, "label": "A link to about.html"}, {"sel": "nav a[href$=\"contact.html\"]", "exists": true, "label": "A link to contact.html"}, {"sel": "nav [aria-current=\"page\"]", "exists": true, "label": "One link marked aria-current=\"page\""}]}, {"type": "build", "prompt": "Style the current link so sighted visitors see it too: make nav links with aria-current=\"page\" bold (font-weight 600 or more).", "example": "nav [aria-current=\"page\"] {\n  font-weight: 700;\n  text-decoration: underline;\n}", "explain": "The attribute does double duty: meaning for assistive tech, a selector for your CSS.", "checks": [{"cssContains": "[aria-current", "label": "A rule targets [aria-current]"}, {"sel": "nav [aria-current=\"page\"]", "style": "fontWeight", "label": "The current link renders at weight 600 or more", "minPx": 600}]}, {"type": "order", "prompt": "Add a new page without breaking links.", "items": ["Export your current page as the template", "Copy it and rename the copy about.html", "Change the title, h1 and aria-current in the copy", "Add the about.html link to the nav on every page", "Click every nav link on the live site"], "explain": "Copy, change, link, verify. Skipping the last step is how broken links reach visitors.", "codeItems": false, "orderNote": "Each step needs the one before it: you cannot edit a copy before it exists, or test links before they are added."}, {"type": "mcq", "prompt": "Why use relative links like about.html instead of https://mysite.com/about.html for your own pages?", "options": ["Browsers require it", "They keep working on any host, preview URL or domain", "Search engines rank them higher", "They hide your domain name"], "answer": 1, "explain": "Relative links survive moving the site. Absolute links to your own domain break on preview deploys and on your laptop."}]}, {"title": "Forms that work", "keywords": ["forms", "form", "input", "label", "validation", "contact", "email", "netlify", "formspree", "required"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Optional: a free Netlify account (Netlify Forms) or a free Formspree account to receive the messages. Without one the form still validates in the browser; it just has nowhere to send. Cost: free."}, {"type": "concept", "heading": "The parts of a form", "body": "A form wraps inputs. Every input gets a label whose for matches the input's id. type=\"email\" and type=\"tel\" bring up the right phone keyboard. A button with type=\"submit\" sends it.", "code": "<form>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <button type=\"submit\">Send</button>\n</form>"}, {"type": "mcq", "prompt": "Why should every input have a label whose for matches the input's id?", "options": ["It makes the field required", "It sends the label text to the server", "Screen readers announce it, and clicking the label focuses the input", "It styles the input automatically"], "answer": 2, "explain": "The pairing is meaning, not decoration. It also makes small checkboxes easier to hit, since the label becomes part of the target."}, {"type": "concept", "heading": "Validation you get for free", "body": "required, type=\"email\", minlength and pattern make the browser block a bad submit and explain why, with no JavaScript. Style the problem with :user-invalid so errors show after someone has typed, not on page load."}, {"type": "build", "prompt": "Add a contact form: an email input with id=\"email\" that is required, a label for it, a textarea for the message, and a submit button.", "example": "<form>\n  <label for=\"name\">Name</label>\n  <input id=\"name\" name=\"name\" required>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <label for=\"message\">Message</label>\n  <textarea id=\"message\" name=\"message\" minlength=\"10\" required></textarea>\n  <button type=\"submit\">Send</button>\n</form>", "explain": "Labeled, typed and required. The browser now refuses an empty or malformed email before it leaves the page.", "checks": [{"sel": "form", "exists": true, "label": "A form element"}, {"sel": "form input#email[type=\"email\"][required]", "exists": true, "label": "A required email input with id=\"email\""}, {"sel": "form label[for=\"email\"]", "exists": true, "label": "A label whose for is \"email\""}, {"sel": "form textarea", "exists": true, "label": "A textarea for the message"}, {"sel": "form button[type=\"submit\"]", "exists": true, "label": "A submit button"}]}, {"type": "concept", "heading": "Sending without a server", "body": "A static host cannot run code, so a form service receives the submission. Netlify Forms: add data-netlify=\"true\" and a name to the form. Formspree: set action to your Formspree URL. Both want method=\"post\". A honeypot catches bots: a real text field that people cannot see, so only a bot fills it in. Hide it with the hidden attribute on a wrapper or with CSS. Do not use type=\"hidden\": many bots skip those, so they never take the bait."}, {"type": "build", "prompt": "Wire the form up: method=\"post\", either data-netlify=\"true\" or an action URL, and a honeypot: a real text input named bot-field that people cannot see (wrap it in an element with the hidden attribute, or hide it with CSS).", "example": "<form name=\"contact\" method=\"post\" data-netlify=\"true\" netlify-honeypot=\"bot-field\">\n  <p hidden><label>Skip this <input name=\"bot-field\"></label></p>\n  ...\n</form>", "explain": "Posted, routed to a service, and guarded against the laziest bots. Submit it once on the live site to confirm it arrives.", "checks": [{"sel": "form[method=\"post\" i]", "exists": true, "label": "The form uses method=\"post\""}, {"sel": "form[data-netlify], form[action]", "exists": true, "label": "The form has data-netlify or an action"}, {"sel": "form input[name=\"bot-field\"], form input[name=\"_gotcha\"]", "exists": true, "label": "A honeypot input (bot-field or _gotcha)"}, {"sel": "form input[name=\"bot-field\"][type=\"hidden\" i], form input[name=\"_gotcha\"][type=\"hidden\" i]", "none": true, "label": "The honeypot is a real text field, not type=\"hidden\"", "hint": "Bots often skip type=\"hidden\" inputs. Use a normal input and hide it from people instead."}, {"sel": "form input[name=\"bot-field\"], form input[name=\"_gotcha\"]", "invisible": true, "label": "People cannot see the honeypot", "hint": "Wrap it in <p hidden>...</p>, or give it a class your CSS hides with display: none."}]}, {"type": "code", "prompt": "Browsers validate, but your code should too. Write formErrors(fields) that returns an array of the field names that are invalid, in this order: \"name\" if empty after trimming, \"email\" if it lacks an @ or a dot after the @, \"message\" if shorter than 10 characters after trimming.", "starter": "function formErrors(fields) {\n  const errors = [];\n  \n  return errors;\n}", "tests": [{"call": "formErrors({ name: \"Ada\", email: \"ada@example.com\", message: \"Hello there, friend\" })", "expect": []}, {"call": "formErrors({ name: \"  \", email: \"ada@example.com\", message: \"Hello there, friend\" })", "expect": ["name"]}, {"call": "formErrors({ name: \"Ada\", email: \"ada.example.com\", message: \"Hi\" })", "expect": ["email", "message"]}, {"call": "formErrors({ name: \"Ada\", email: \"ada@example\", message: \"Long enough message\" })", "expect": ["email"]}], "solution": "function formErrors(fields) {\n  const errors = [];\n  if (!String(fields.name || \"\").trim()) errors.push(\"name\");\n  const email = String(fields.email || \"\");\n  const at = email.indexOf(\"@\");\n  if (at < 1 || email.indexOf(\".\", at) < 0) errors.push(\"email\");\n  if (String(fields.message || \"\").trim().length < 10) errors.push(\"message\");\n  return errors;\n}", "explain": "Trim before testing, and return every problem at once so the person fixes them in one pass."}]}]}, {"title": "Polish", "lessons": [{"title": "Semantic HTML, SEO, and sharing", "keywords": ["seo", "meta", "description", "open", "graph", "sharing", "semantic", "article", "section", "time", "search"], "steps": [{"type": "concept", "heading": "What search results show", "body": "The title element becomes the blue link. The meta description often becomes the text under it. One clear h1 tells search engines and screen readers what the page is about.", "code": "<title>Casa Verde: weeknight recipes</title>\n<meta name=\"description\" content=\"Thirty-minute dinners that actually work.\">"}, {"type": "mcq", "prompt": "Which tag usually sets the text under your link in a search result?", "options": ["<meta name=\"keywords\">", "<meta name=\"description\">", "<h2>", "<meta charset=\"utf-8\">"], "answer": 1, "explain": "Search engines ignore the keywords tag today. The description is your pitch in the results page."}, {"type": "concept", "heading": "Previews when people share", "body": "Open Graph tags control the card you see when a link is pasted into a chat or social app: og:title, og:description and og:image. The image must be an absolute https URL, ideally 1200 by 630 pixels."}, {"type": "build", "prompt": "Add sharing tags: a meta description, og:title, and an og:image whose content is an absolute https URL.", "example": "<meta name=\"description\" content=\"Weeknight recipes that actually work.\">\n<meta property=\"og:title\" content=\"Casa Verde\">\n<meta property=\"og:description\" content=\"Weeknight recipes that actually work.\">\n<meta property=\"og:image\" content=\"https://example.com/share.png\">", "explain": "Paste your live URL into a chat after you redeploy. The card you see is these tags.", "checks": [{"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description"}, {"sel": "meta[property=\"og:title\"]", "attr": "content", "label": "An og:title tag"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "og:image uses an https URL", "contains": "https://"}]}, {"type": "concept", "heading": "Elements that say what they are", "body": "article: a piece that makes sense alone, like a post or recipe. section: a themed group with its own heading. aside: related but not essential. time with a datetime attribute: a date machines can read."}, {"type": "build", "prompt": "Add a semantic content block: an article, a section with its own heading, and a time element with a datetime attribute.", "example": "<section>\n  <h2>Latest</h2>\n  <article class=\"card\">\n    <h3>Lemon pasta</h3>\n    <p>Posted <time datetime=\"2026-09-30\">30 September</time></p>\n  </article>\n</section>", "explain": "The page looks the same, but now it describes itself to search engines and assistive tech.", "checks": [{"sel": "article", "exists": true, "label": "An article element"}, {"sel": "section h2, section h3", "exists": true, "label": "A section with a heading inside"}, {"sel": "time", "attr": "datetime", "label": "A time element with datetime"}]}, {"type": "concept", "heading": "Landmarks and headings", "body": "header, nav, main and footer are landmarks: screen reader users jump between them, and later lessons build on them. One main per page holds the content that is unique to it. Cards read better with a heading of their own, so people scanning the page, or a list of headings, can tell them apart.", "code": "<main>\n  <h1>Casa Verde</h1>\n  <div class=\"card\"><h3>Soups</h3><p>Warm bowls.</p></div>\n</main>\n<footer>\n  <p>Casa Verde, weeknight recipes</p>\n</footer>"}, {"type": "build", "prompt": "Give the page its landmarks: wrap your content (everything after the nav) in a main element, add a footer at the end, and give at least three of your cards a heading (h2 or h3).", "example": "<nav>...</nav>\n<main>\n  <h1>Casa Verde</h1>\n  ...\n  <div class=\"gallery\">\n    <div class=\"card\"><h3>Soups</h3><p>Warm bowls</p></div>\n    <div class=\"card\"><h3>Pasta</h3><p>Ten minutes</p></div>\n    <div class=\"card\"><h3>Salads</h3><p>Crunchy</p></div>\n  </div>\n</main>\n<footer>\n  <p>Casa Verde, weeknight recipes</p>\n</footer>", "explain": "Your page now has the structure every later lesson builds on: a main to skip to, a footer for links, and cards people can tell apart.", "checks": [{"sel": "main", "exists": true, "label": "A main element"}, {"sel": "footer", "exists": true, "label": "A footer element"}, {"sel": ".card h2, .card h3", "count": 3, "label": "At least three cards with a heading", "hint": "Add an h3 at the top of each card, for example <h3>Soups</h3>."}]}, {"type": "order", "prompt": "Order what a crawler does with your page, in the model from this lesson.", "items": ["Fetch the HTML", "Read the title and meta description", "Read the headings and main content", "Follow the links to more pages"], "explain": "It has to fetch before it reads, and it finds new pages through the links it reads. That is why internal links matter for SEO.", "codeItems": false, "groups": [[1, 2]], "orderNote": "Fetch comes first and following links comes last. The two reading steps can swap."}]}, {"title": "The cascade, specificity, and states", "keywords": ["cascade", "specificity", "hover", "focus", "pseudo", "states", "before", "after", "important"], "steps": [{"type": "concept", "heading": "Who wins", "body": "When two rules set the same property, the browser compares specificity: inline style, then ids, then classes, attributes and pseudo-classes, then elements. On a tie, the later rule wins.", "code": "#menu a { color: red; }   /* 1 id, 1 element */\n.nav a { color: blue; }   /* 1 class, 1 element */"}, {"type": "mcq", "prompt": "Both rules match the same link. Which color wins?", "options": ["blue, because .nav a comes later", "red, because one id outweighs any number of classes", "They tie, so the browser picks", "Neither, links ignore color"], "answer": 1, "explain": "Source order only breaks ties. An id beats classes no matter where it sits."}, {"type": "concept", "heading": "States and pseudo-elements", "body": ":hover and :focus-visible react to the visitor. ::before and ::after add decoration without new HTML, and they need a content property to appear.", "code": ".card:hover { transform: translateY(-2px); }\na:focus-visible { outline: 3px solid; }\n.card h3::before { content: \"# \"; }"}, {"type": "build", "prompt": "Add interactive states: a .card:hover rule, a :focus-visible rule, and a ::before or ::after with content. Do it without !important.", "example": ".card:hover {\n  box-shadow: 0 4px 12px rgba(0,0,0,.15);\n}\na:focus-visible {\n  outline: 3px solid #4f46e5;\n  outline-offset: 2px;\n}\n.card h3::after {\n  content: \" >\";\n}", "explain": "Hover for mice, focus-visible for keyboards, and decoration that stays out of your HTML.", "checks": [{"cssContains": ".card:hover", "label": "A .card:hover rule"}, {"cssContains": ":focus-visible", "label": "A :focus-visible rule"}, {"cssContains": "content:", "label": "A pseudo-element with content"}, {"cssContains": "!important", "label": "No !important in your stylesheet", "negate": true}]}, {"type": "mcq", "prompt": "A style refuses to apply. What is the best first move?", "options": ["Inspect the element in DevTools and see which rule wins", "Add !important", "Rewrite the stylesheet", "Clear the browser cache"], "answer": 0, "explain": "DevTools shows every matching rule, crossed out or not. Guessing with !important hides the cause."}, {"type": "order", "prompt": "Order these from lowest to highest specificity.", "items": ["p", ".card", ".card p", "#main", "style=\"\" (inline)"], "explain": "Elements, then classes, then a class plus element, then an id, then inline style.", "codeItems": true, "orderNote": "Order matters: each one outweighs every item before it."}]}, {"title": "Motion with care", "keywords": ["animation", "transition", "keyframes", "motion", "reduced", "transform", "opacity"], "steps": [{"type": "concept", "heading": "Two kinds of motion", "body": "A transition animates between two states when something changes, like a hover. @keyframes defines a sequence that runs on its own, like an entrance.", "code": ".card { transition: transform 200ms ease; }\n@keyframes rise { from { opacity: 0; transform: translateY(8px); } }"}, {"type": "mcq", "prompt": "Which properties are cheapest to animate?", "options": ["width and height", "top and left", "transform and opacity", "margin and padding"], "answer": 2, "explain": "The browser can move and fade a layer without redoing layout. Animating size or position forces layout on every frame."}, {"type": "concept", "heading": "Respect the setting", "body": "Some people get dizzy or sick from motion. Operating systems let them ask for less, and CSS reads it as prefers-reduced-motion. Honor it by removing or shortening animations."}, {"type": "build", "prompt": "Add motion: a transition on .card, a hover rule that uses transform, an @keyframes animation, and a prefers-reduced-motion rule that turns motion down.", "example": ".card { transition: transform 200ms ease; }\n.card:hover { transform: translateY(-3px); }\n@keyframes rise {\n  from { opacity: 0; transform: translateY(8px); }\n}\nh1 { animation: rise 400ms ease both; }\n@media (prefers-reduced-motion: reduce) {\n  .card, h1 { animation: none; transition: none; }\n}", "explain": "Motion that helps, and an off switch for the people it hurts.", "checks": [{"sel": ".card", "style": "transitionDuration", "label": ".card has a transition", "not": "0s"}, {"cssContains": "transform", "label": "A rule uses transform"}, {"cssContains": "@keyframes", "label": "An @keyframes animation"}, {"cssContains": "prefers-reduced-motion", "label": "A prefers-reduced-motion rule"}]}, {"type": "mcq", "prompt": "A visitor says your page animation makes them dizzy. What should the site do?", "options": ["Make the animation faster", "Honor prefers-reduced-motion and stop or tone down the motion", "Add a warning banner", "Nothing, it is their device"], "answer": 1, "explain": "They already told their device. The media query is how your site listens."}, {"type": "order", "prompt": "Add a safe animation.", "items": ["Pick one element where motion helps", "Animate only transform or opacity", "Keep UI feedback short, about 200 to 300ms", "Add a reduced-motion override", "Test with reduced motion turned on"], "explain": "Choose with purpose, animate cheaply, keep it brief, give an off switch, then test.", "codeItems": false, "groups": [[1, 2]], "orderNote": "Steps 2 and 3 can swap; the check accepts either."}]}]}, {"title": "Run it", "lessons": [{"title": "Images done right", "keywords": ["images", "srcset", "picture", "webp", "avif", "lazy", "responsive", "formats"], "steps": [{"type": "concept", "heading": "Pick the right format", "body": "JPEG for photos, PNG for screenshots with sharp edges, SVG for logos and icons, WebP or AVIF for smaller photos with the same quality. A 4000 pixel photo shown 800 pixels wide wastes most of its bytes."}, {"type": "mcq", "prompt": "Which format fits a logo best?", "options": ["JPEG", "SVG", "GIF", "BMP"], "answer": 1, "explain": "SVG is drawn from shapes, so it stays sharp at every size and is usually tiny."}, {"type": "concept", "heading": "Let the browser choose", "body": "srcset lists the same image at several widths. sizes says how wide it displays. The browser downloads the smallest file that looks sharp. picture with source elements offers new formats with a fallback.", "code": "<picture>\n  <source type=\"image/webp\" srcset=\"hero-800.webp 800w, hero-1600.webp 1600w\">\n  <img src=\"hero-800.jpg\" srcset=\"hero-800.jpg 800w, hero-1600.jpg 1600w\" sizes=\"100vw\" width=\"1600\" height=\"900\" alt=\"Lemon pasta in a blue bowl\">\n</picture>"}, {"type": "build", "prompt": "Make one image responsive: wrap it in picture with a source element, give the img a srcset, width and height, lazy-load an image that sits further down the page, and add img { max-width: 100%; height: auto; } to your CSS so a 1200 pixel image shrinks to fit a phone instead of widening the page. The Workshop cannot hold image files, so use full https image URLs, like the picsum.photos ones in the example; on your own host you can swap in files you upload.", "example": "<picture>\n  <source type=\"image/webp\" srcset=\"https://picsum.photos/id/292/800/450.webp 800w\">\n  <img src=\"https://picsum.photos/id/292/800/450\" srcset=\"https://picsum.photos/id/292/800/450 800w, https://picsum.photos/id/292/1600/900 1600w\" sizes=\"100vw\" width=\"800\" height=\"450\" alt=\"Ingredients on a table\">\n</picture>\n<img src=\"https://picsum.photos/id/429/600/400\" loading=\"lazy\" width=\"600\" height=\"400\" alt=\"A finished dish\">\n\n/* CSS */\nimg {\n  max-width: 100%;\n  height: auto;\n}", "explain": "Phones get small files, big screens get sharp ones, and images below the fold wait until someone scrolls.", "checks": [{"sel": "picture source", "exists": true, "label": "A picture element with a source"}, {"sel": "img[srcset]", "attr": "srcset", "label": "An img with srcset"}, {"sel": "img[width][height]", "exists": true, "label": "An img with width and height"}, {"sel": "img[loading=\"lazy\"]", "exists": true, "label": "An img with loading=\"lazy\""}, {"sel": "img", "style": "maxWidth", "label": "Images shrink to fit: img has max-width: 100%", "equals": "100%", "hint": "Width and height attributes reserve space, but without max-width a big image runs off the side of a phone. Add img { max-width: 100%; height: auto; }."}, {"sel": "img", "attr": "src", "label": "Every image uses a full https URL, so it loads", "match": "^(https://|data:image/)", "every": true, "hint": "A name like hero.jpg points at a file the Workshop and your export do not have, so it shows as a broken image. Use a full https URL, such as https://picsum.photos/id/292/800/450."}, {"sel": "img[srcset], source[srcset]", "attr": "srcset", "label": "Every srcset lists full https URLs", "match": "^\\s*(https://|data:image/)\\S+(\\s+\\d+(\\.\\d+)?[wx])?\\s*(,\\s*(https://|data:image/)\\S+(\\s+\\d+(\\.\\d+)?[wx])?\\s*)*$", "every": true, "hint": "Each entry is a full https URL and a width, separated by commas: https://picsum.photos/id/292/800/450 800w, https://picsum.photos/id/292/1600/900 1600w"}]}, {"type": "mcq", "prompt": "Why set width and height on images?", "options": ["They make the file smaller", "The browser reserves the space, so text does not jump when the image arrives", "They are required for alt text to work", "They turn on lazy loading"], "answer": 1, "explain": "Without dimensions the page reflows when each image loads. That jump is layout shift, and it is measured."}, {"type": "order", "prompt": "Add a new photo to the site properly.", "items": ["Resize the original to the largest size you show", "Export WebP plus a JPEG fallback", "Add width, height and alt", "Add srcset and sizes", "Lazy-load it if it sits below the fold"], "explain": "Prepare the files first, then describe them in HTML.", "codeItems": false, "groups": [[2, 3, 4]], "orderNote": "The HTML attributes in steps 3 to 5 can go in any order; the check accepts them."}]}, {"title": "A little JavaScript on your page", "keywords": ["javascript", "dom", "events", "menu", "dark", "mode", "theme", "localstorage", "toggle", "script"], "steps": [{"type": "concept", "heading": "Three moves cover most page scripts", "body": "Find an element with querySelector, listen with addEventListener, change something with classList or setAttribute. Put the script at the end of body, or use defer on an external file. Use type=\"module\" on your script tags: each module keeps its names to itself, so two scripts can both have a btn without crashing. The Prexis preview never runs scripts, for your safety; checks read your code, the code step below runs your logic, and your exported site runs it for real.", "code": "const btn = document.querySelector(\".menu-toggle\");\nbtn.addEventListener(\"click\", () => {\n  const open = btn.getAttribute(\"aria-expanded\") === \"true\";\n  btn.setAttribute(\"aria-expanded\", String(!open));\n  document.querySelector(\"nav\").classList.toggle(\"open\");\n});"}, {"type": "mcq", "prompt": "Why use a button element for the menu toggle instead of a div?", "options": ["Divs cannot have click handlers", "A button is focusable and works with Enter and Space for free", "Buttons load faster", "Divs break CSS"], "answer": 1, "explain": "Keyboard support and the correct role come built in. A clickable div needs all of that rebuilt by hand."}, {"type": "build", "prompt": "Add a mobile menu: a button with class menu-toggle and aria-expanded=\"false\" just before your nav, a script that toggles an open class on the nav with classList.toggle, and CSS that hides the nav on narrow screens until it has the open class. The lesson preview is narrow, so your nav will tuck away behind the button there; export and open the page at phone width to watch the button open it.", "example": "<button class=\"menu-toggle\" aria-expanded=\"false\">Menu</button>\n<nav>...</nav>\n<script type=\"module\">\n  const btn = document.querySelector(\".menu-toggle\");\n  const nav = document.querySelector(\"nav\");\n  btn.addEventListener(\"click\", () => {\n    const open = nav.classList.toggle(\"open\");\n    btn.setAttribute(\"aria-expanded\", String(open));\n  });\n</script>\n\n/* CSS */\n.menu-toggle { display: none; }\n@media (max-width: 600px) {\n  .menu-toggle { display: inline-block; }\n  nav { display: none; }\n  nav.open { display: flex; flex-direction: column; gap: 8px; }\n}", "explain": "aria-expanded tells screen readers the menu state; the open class tells your CSS to show the nav. On wide screens the button hides and the nav stays put.", "checks": [{"sel": "button.menu-toggle", "exists": true, "label": "A button with class menu-toggle"}, {"sel": "button.menu-toggle", "attr": "aria-expanded", "label": "The button has aria-expanded"}, {"sel": "script", "exists": true, "label": "A script element"}, {"htmlContains": "classList.toggle", "label": "The script uses classList.toggle"}, {"cssContains": "nav.open", "label": "CSS shows the nav when it has the open class", "hint": "Without CSS for nav.open the button flips a class nobody styles, so nothing visibly happens. Inside @media (max-width: 600px), hide nav and show nav.open, as in the example."}]}, {"type": "concept", "heading": "Dark mode from your tokens", "body": "You already keep colors in custom properties. Redefine them under [data-theme=\"dark\"] on the html element, flip that attribute with a button, and save the choice in localStorage so it sticks.", "code": "[data-theme=\"dark\"] {\n  --paper: #1d1f24;\n  --ink: #f1efe8;\n}"}, {"type": "code", "prompt": "Write pickTheme(saved, prefersDark). Return saved only when it is exactly \"light\" or \"dark\"; anything else that was saved (null, or a stray value like \"purple\") is ignored. Otherwise return \"dark\" if prefersDark is true, else \"light\".", "starter": "function pickTheme(saved, prefersDark) {\n  \n}", "tests": [{"call": "pickTheme(\"dark\", false)", "expect": "dark"}, {"call": "pickTheme(\"light\", true)", "expect": "light"}, {"call": "pickTheme(null, true)", "expect": "dark"}, {"call": "pickTheme(\"purple\", false)", "expect": "light"}], "solution": "function pickTheme(saved, prefersDark) {\n  if (saved === \"light\" || saved === \"dark\") return saved;\n  return prefersDark ? \"dark\" : \"light\";\n}", "explain": "A saved choice beats the system setting; the system setting beats your default."}, {"type": "build", "prompt": "Wire dark mode: a [data-theme=\"dark\"] rule in your CSS that changes your tokens, a button with class theme-toggle, and a script that saves the choice with localStorage.", "example": "<button class=\"theme-toggle\">Dark mode</button>\n<script type=\"module\">\n  const root = document.documentElement;\n  root.dataset.theme = localStorage.getItem(\"theme\") || \"light\";\n  document.querySelector(\".theme-toggle\").addEventListener(\"click\", () => {\n    root.dataset.theme = root.dataset.theme === \"dark\" ? \"light\" : \"dark\";\n    localStorage.setItem(\"theme\", root.dataset.theme);\n  });\n</script>\n\n/* CSS */\n[data-theme=\"dark\"] { --paper: #1d1f24; --ink: #f1efe8; }", "explain": "Export and open it in a browser: the toggle works and remembers your choice after a reload.", "checks": [{"cssContains": "[data-theme=\"dark\"]", "label": "A [data-theme=\"dark\"] rule in your CSS"}, {"sel": "button.theme-toggle", "exists": true, "label": "A button with class theme-toggle"}, {"htmlContains": "localStorage", "label": "The script saves the choice in localStorage"}]}, {"type": "mcq", "prompt": "The page flashes light for a moment before going dark. What is the fix?", "options": ["Add a transition to body", "Set data-theme in a tiny script in the head, before the page paints", "Load the script with async", "Use a darker light theme"], "answer": 1, "explain": "A script at the end of body runs after the first paint. Reading the saved theme in the head sets it before anything shows."}]}, {"title": "Git and GitHub for real", "keywords": ["git", "github", "commit", "push", "repository", "repo", "version", "control", "pages", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free GitHub account and Git on your computer (git-scm.com; on a Mac, typing git in Terminal offers to install it). GitHub Desktop works too if you would rather click than type. Cost: free."}, {"type": "concept", "heading": "Snapshots with a story", "body": "Git saves snapshots of your files called commits, each with a message saying why. GitHub stores your repository online, shows the history, and can publish it with GitHub Pages. If a change breaks the site, you can go back to any commit."}, {"type": "order", "prompt": "Order the everyday Git loop.", "items": ["Edit your files", "git add index.html", "git commit -m \"Add contact form\"", "git push"], "explain": "Change, stage, snapshot, upload. Nothing reaches GitHub until you push.", "codeItems": true, "orderNote": "Each command works on the result of the one before it."}, {"type": "worked", "heading": "From a folder to a published repo", "problem": "Your exported index.html sits in a folder called my-site. Put it on GitHub from a terminal.", "steps": ["cd my-site, then git init to start a repository.", "git add index.html, then git commit -m \"First version\".", "Create an empty repo on github.com, then git remote add origin https://github.com/you/my-site.git", "git branch -M main, then git push -u origin main. In the repo, Settings, Pages, deploy from main. Each future push updates the site."], "takeaway": "Once the remote is set, publishing is git push.", "code": "git init\ngit add index.html\ngit commit -m \"First version\"\ngit branch -M main\ngit remote add origin https://github.com/you/my-site.git\ngit push -u origin main"}, {"type": "mcq", "prompt": "Which commit message helps you most six months from now?", "options": ["stuff", "fix", "Add contact form with email validation", "asdfgh"], "answer": 2, "explain": "Say what changed and why in a short line. History is only searchable if the messages mean something."}, {"type": "mcq", "prompt": "You pushed a change but the live site still shows the old version. What do you check first?", "options": ["Delete the repository", "The Pages or Actions tab, to see if the deploy finished or failed", "Buy a new domain", "Rewrite the commit"], "answer": 1, "explain": "Publishing takes a minute and can fail. The deploy status tells you which one happened."}, {"type": "build", "prompt": "Intermediate capstone. Your site should have everything from this level: a nav with 3 links and aria-current, a contact form, a meta description and og:image, a favicon, a responsive image, a theme toggle, and a link to your GitHub repo in your footer. Commit it, push it, and paste your repo URL.", "example": "<footer>\n  <p>Source on <a href=\"https://github.com/you/my-site\">GitHub</a></p>\n</footer>", "explain": "A real multi page site, live, in Git, with a form and dark mode. You run a website now.", "checks": [{"sel": "nav a", "count": 3, "label": "Nav with at least 3 links"}, {"sel": "nav [aria-current=\"page\"]", "exists": true, "label": "Current page marked with aria-current"}, {"sel": "form input[type=\"email\"]", "exists": true, "label": "A contact form with an email input"}, {"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "An og:image tag"}, {"sel": "link[rel~=\"icon\"]", "attr": "href", "label": "A favicon link (inline data: or https)", "match": "^(data:image/|https://)"}, {"sel": "img[srcset]", "exists": true, "label": "A responsive image with srcset"}, {"sel": "button.theme-toggle", "exists": true, "label": "A theme toggle button"}, {"sel": "footer a[href*=\"github.com\"]", "exists": true, "label": "A footer link to your GitHub repo"}, {"confirm": true, "label": "I committed and pushed this version to GitHub"}, {"url": "repoUrl", "label": "Your GitHub repo URL", "kind": "repo"}]}]}]}]}, {"id": "web-advanced", "subject": "Web apps", "level": "Advanced", "title": "Web apps with real tools", "track": "web", "prereq": "web-intermediate", "rev": "2026-09-30", "unlock": {"after": "web-intermediate", "mastery": 85, "skill": "Web development"}, "blurb": "Modern CSS, modules, fetch, Vite, deploy from Git, your own domain, speed, accessibility, CI.", "units": [{"title": "Modern front end", "lessons": [{"title": "Modern CSS architecture", "keywords": ["css", "architecture", "layer", "container", "queries", "has", "where", "bem"], "steps": [{"type": "concept", "heading": "Names that scale", "body": "Pick one naming pattern and keep it. BEM names a block, its elements and variants: .card, .card__title, .card--featured. Anyone reading the HTML knows which CSS owns it."}, {"type": "concept", "heading": "Newer tools that remove hacks", "body": "@layer sets the order your CSS groups win in, so a utility class beats a component without specificity fights. Container queries style a component by the width of its container, not the window. :has() styles a parent based on what it contains.", "code": "@layer reset, base, components, utilities;\n.cards { container-type: inline-size; }\n@container (min-width: 500px) { .card { display: flex; } }\n.card:has(img) { padding-top: 0; }"}, {"type": "mcq", "prompt": "When is a container query better than a media query?", "options": ["When the whole page changes at a phone width", "When the same component appears in a wide main area and a narrow sidebar", "When printing", "Never, they do the same thing"], "answer": 1, "explain": "Media queries know the window. A card does not care about the window; it cares about the space it was given."}, {"type": "build", "prompt": "Refactor your CSS: declare layers with @layer, give one card heading the class card__title (your cards got headings in Semantic HTML, SEO, and sharing; add an h3 to a card if it has none), and make your card wrapper a container with an @container rule.", "example": "@layer reset, base, components;\n@layer components {\n  .cards { container-type: inline-size; }\n  @container (min-width: 500px) {\n    .card { display: flex; gap: 12px; }\n  }\n}\n\n<h3 class=\"card__title\">Lemon pasta</h3>", "explain": "Your styles now have an explicit order and your cards adapt to wherever you put them.", "checks": [{"cssContains": "@layer", "label": "An @layer rule"}, {"sel": ".card__title", "exists": true, "label": "An element with class card__title", "hint": "Add the class to a heading inside a card: <h3 class=\"card__title\">Soups</h3>."}, {"cssContains": "container-type", "label": "A container-type declaration"}, {"cssContains": "@container", "label": "An @container rule"}]}, {"type": "build", "prompt": "Use smarter selectors: make sure at least one card contains an image so .card:has(img) matches (move an image into a card, or add one), and write a :where( rule.", "example": ".card:has(img) { padding-top: 0; }\n:where(.card, .panel) h3 { margin-top: 0; }", "explain": ":has() replaces the extra class you used to add by hand. :where() groups selectors with zero specificity, so it never fights your components.", "checks": [{"sel": ".card:has(img)", "exists": true, "label": "A card that contains an image"}, {"cssContains": ":has(", "label": "A rule that uses :has("}, {"cssContains": ":where(", "label": "A rule that uses :where("}]}, {"type": "order", "prompt": "Order the layers from first (weakest) to last (strongest).", "items": ["reset", "base", "components", "utilities"], "explain": "Later layers win. Utilities sit last so a single class can override a component on purpose.", "codeItems": true, "orderNote": "Order matters here: in @layer, the order you declare is the order that wins."}]}, {"title": "JavaScript modules and components", "keywords": ["modules", "import", "export", "components", "template", "literals", "render", "textcontent", "innerhtml"], "steps": [{"type": "concept", "heading": "Modules keep code apart", "body": "type=\"module\" scripts have their own scope, run after the HTML is parsed, and can import from other files. Each file exports what others may use.", "code": "// projects.js\nexport const projects = [{ title: \"Lemon pasta\", summary: \"Ten minutes\" }];\n\n// main.js\nimport { projects } from \"./projects.js\";"}, {"type": "mcq", "prompt": "What does type=\"module\" change about a script?", "options": ["Nothing, it is only a label", "It gets its own scope, is deferred, and can use import", "It runs before the HTML loads", "It can only contain JSON"], "answer": 1, "explain": "Module scripts behave like defer by default and never leak variables onto window."}, {"type": "concept", "heading": "Data in, markup out", "body": "Keep repeated content as an array of objects. A small function turns one object into markup, and map turns the array into a page section. Change the data, the page follows.", "code": "const html = projects.map(renderCard).join(\"\");"}, {"type": "code", "prompt": "Write renderCard(p) so it returns exactly: <article class=\"card\"><h3 class=\"card__title\">TITLE</h3><p>SUMMARY</p></article> using p.title and p.summary. Use a template literal.", "starter": "function renderCard(p) {\n  return ``;\n}", "tests": [{"call": "renderCard({ title: \"Lemon pasta\", summary: \"Ten minutes\" })", "expect": "<article class=\"card\"><h3 class=\"card__title\">Lemon pasta</h3><p>Ten minutes</p></article>"}, {"call": "[{ title: \"A\", summary: \"1\" }, { title: \"B\", summary: \"2\" }].map(renderCard).join(\"\")", "expect": "<article class=\"card\"><h3 class=\"card__title\">A</h3><p>1</p></article><article class=\"card\"><h3 class=\"card__title\">B</h3><p>2</p></article>"}], "solution": "function renderCard(p) {\n  return `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n}", "explain": "One function, any number of cards. This is the core idea behind every component framework."}, {"type": "build", "prompt": "Make your cards data-driven: add a module script that defines renderCard and maps over an array into your card grid. That is the .gallery you built in Grid for real layouts, or a .grid if you named it that. Keep three static .card elements inside it as the fallback; the preview does not run scripts, and your exported site replaces them.", "example": "<div class=\"gallery\">\n  <article class=\"card\">...</article>\n  <article class=\"card\">...</article>\n  <article class=\"card\">...</article>\n</div>\n<script type=\"module\">\n  const projects = [{ title: \"Lemon pasta\", summary: \"Ten minutes\" }];\n  const renderCard = (p) => `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n  document.querySelector(\".gallery, .grid\").innerHTML = projects.map(renderCard).join(\"\");\n</script>", "explain": "The markup now comes from data. Adding a project is one line in an array, not a copy and paste.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A script with type=\"module\""}, {"htmlContains": "renderCard", "label": "A renderCard function"}, {"htmlContains": ".map(", "label": "The data is rendered with map"}, {"sel": ".grid .card, .gallery .card", "count": 3, "label": "Three fallback cards inside your .gallery or .grid", "hint": "The Beginner grid is class gallery. Keep at least three .card elements inside it (or inside a .grid)."}]}, {"type": "concept", "heading": "textContent for anything a person typed", "body": "innerHTML parses its string as HTML. If that string came from a visitor, they can inject a script. textContent inserts plain text and can never become markup. Use template literals for your own trusted data, and textContent for theirs."}, {"type": "mcq", "prompt": "Which is safest for putting a visitor's name on the page?", "options": ["el.innerHTML = name", "el.textContent = name", "document.write(name)", "el.outerHTML = name"], "answer": 1, "explain": "textContent never parses HTML, so a name like <img onerror=...> shows as text instead of running."}, {"type": "order", "prompt": "Order the render flow.", "items": ["Load the data", "Build markup or elements from it", "Append them to the page", "Attach event listeners"], "explain": "Listeners need elements to attach to, and elements need data to be built from.", "codeItems": false, "orderNote": "Each step depends on the one before it."}]}, {"title": "Fetching data", "keywords": ["fetch", "json", "async", "await", "promise", "loading", "error", "search", "filter", "api"], "steps": [{"type": "concept", "heading": "fetch, await, JSON", "body": "fetch requests a URL and returns a promise for the response. await pauses an async function until it settles. response.ok is true for status 200 to 299; response.json() parses the body.", "code": "async function load() {\n  const res = await fetch(\"data.json\");\n  if (!res.ok) throw new Error(\"HTTP \" + res.status);\n  return res.json();\n}"}, {"type": "mcq", "prompt": "What does response.ok tell you?", "options": ["The network is online", "The status code is in the 200 to 299 range", "The JSON is valid", "The request was cached"], "answer": 1, "explain": "fetch only rejects on network failure. A 404 still resolves, so you must check ok yourself."}, {"type": "code", "prompt": "Write async loadProjects(fetchFn). Call fetchFn(\"data.json\"). If the response is ok, return { status: \"ok\", items: <parsed json> }. If it is not ok, or anything throws, return { status: \"error\", items: [] }.", "starter": "async function loadProjects(fetchFn) {\n  \n}", "tests": [{"call": "loadProjects(async () => ({ ok: true, json: async () => [{ title: \"A\" }] }))", "expect": {"status": "ok", "items": [{"title": "A"}]}}, {"call": "loadProjects(async () => ({ ok: false, status: 404, json: async () => ({}) }))", "expect": {"status": "error", "items": []}}, {"call": "loadProjects(async () => { throw new Error(\"offline\"); })", "expect": {"status": "error", "items": []}}], "solution": "async function loadProjects(fetchFn) {\n  try {\n    const res = await fetchFn(\"data.json\");\n    if (!res.ok) return { status: \"error\", items: [] };\n    return { status: \"ok\", items: await res.json() };\n  } catch (e) {\n    return { status: \"error\", items: [] };\n  }\n}", "explain": "Every fetch has three outcomes: data, a bad status, or no answer at all. Handle all three."}, {"type": "concept", "heading": "Data the page carries", "body": "Your exported site is one file, so there is no data.json next to it yet, and a page opened straight from disk cannot fetch at all. Carry a copy of the data inside the page as a JSON data island: a script tag with type=\"application/json\". Browsers never run it; your code reads it with JSON.parse. Fetch fresh data first, fall back to the island, and show the error only when both fail.", "code": "<script type=\"application/json\" id=\"recipes-data\">\n[{ \"title\": \"Lemon pasta\", \"summary\": \"Ten minutes\" }]\n</script>"}, {"type": "build", "prompt": "Add loading and error states with data that always arrives: an element with class loading, an element with class error and role=\"alert\", a JSON data island (a script with type=\"application/json\" and an id), and a module script that tries fetch( first, falls back to the island with JSON.parse inside catch, hides the loading message, and shows the error only if both fail.", "example": "<p class=\"loading\">Loading recipes...</p>\n<p class=\"error\" role=\"alert\" hidden>Could not load recipes. Try again.</p>\n<script type=\"application/json\" id=\"recipes-data\">\n[{ \"title\": \"Lemon pasta\", \"summary\": \"Ten minutes\" }, { \"title\": \"Tomato soup\", \"summary\": \"One pot\" }]\n</script>\n<script type=\"module\">\n  let recipes = [];\n  try {\n    const res = await fetch(\"data.json\");\n    if (!res.ok) throw new Error(\"HTTP \" + res.status);\n    recipes = await res.json();\n  } catch (e) {\n    try {\n      recipes = JSON.parse(document.getElementById(\"recipes-data\").textContent);\n    } catch (e2) {\n      document.querySelector(\".error\").hidden = false;\n    }\n  }\n  document.querySelector(\".loading\").hidden = true;\n</script>", "explain": "Visitors now know when the page is waiting and when something failed, and the page works on any host, even opened from a file. Upload a real data.json later and the same code uses it.", "checks": [{"sel": ".loading", "exists": true, "label": "An element with class loading"}, {"sel": ".error[role=\"alert\"]", "exists": true, "label": "An .error element with role=\"alert\""}, {"sel": "script[type=\"application/json\"][id]", "exists": true, "label": "A JSON data island: a script with type=\"application/json\" and an id"}, {"htmlContains": "fetch(", "label": "The script calls fetch("}, {"htmlContains": "catch", "label": "The script handles failure with catch"}, {"htmlMatch": "JSON\\.parse\\(", "label": "It falls back to the island with JSON.parse(", "hint": "Inside catch, read the island: JSON.parse(document.getElementById(\"recipes-data\").textContent)."}]}, {"type": "code", "prompt": "Write filterProjects(list, query). Return the items whose title, or any of their tags, contains query, ignoring case and surrounding spaces. An empty query returns the whole list.", "starter": "function filterProjects(list, query) {\n  \n}", "tests": [{"call": "filterProjects([{ title: \"Lemon pasta\", tags: [\"quick\"] }, { title: \"Stew\", tags: [\"slow\"] }], \"PASTA\").length", "expect": 1}, {"call": "filterProjects([{ title: \"Lemon pasta\", tags: [\"quick\"] }, { title: \"Stew\", tags: [\"slow\"] }], \" slow \")[0].title", "expect": "Stew"}, {"call": "filterProjects([{ title: \"A\", tags: [] }, { title: \"B\", tags: [] }], \"\").length", "expect": 2}], "solution": "function filterProjects(list, query) {\n  const q = String(query || \"\").trim().toLowerCase();\n  if (!q) return list;\n  return list.filter((p) => p.title.toLowerCase().includes(q) || (p.tags || []).some((t) => t.toLowerCase().includes(q)));\n}", "explain": "Normalize once, compare everywhere. Search that ignores case and stray spaces feels correct."}, {"type": "build", "prompt": "Add a search box: an input with type=\"search\" and id=\"search\", and a label for it.", "example": "<label for=\"search\">Search projects</label>\n<input id=\"search\" type=\"search\" placeholder=\"pasta, quick...\">", "explain": "Hook it to filterProjects on the input event in your exported site, and the grid filters as people type.", "checks": [{"sel": "input#search[type=\"search\"]", "exists": true, "label": "A search input with id=\"search\""}, {"sel": "label[for=\"search\"]", "exists": true, "label": "A label for the search input"}]}, {"type": "order", "prompt": "Order what happens from a keystroke to new results.", "items": ["The visitor types in the search box", "The input event fires", "Filter the array by the query", "Render the matching cards"], "explain": "The event carries the new value, the data is filtered, and the page re-renders from the result.", "codeItems": false, "orderNote": "Each step uses the result of the one before it."}]}]}, {"title": "Real tooling", "lessons": [{"title": "Build tools: npm and Vite", "keywords": ["npm", "vite", "package", "json", "build", "bundler", "node", "dev", "server", "tooling", "terminal"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A computer you can install software on (Windows, macOS or Linux; a phone or a locked school laptop will not do), Node.js 20 or newer from nodejs.org (the LTS download), and a code editor such as VS Code. Cost: free. From this lesson on, part of the work happens in a terminal outside Prexis, so the next two cards cover the terminal from zero."}, {"type": "concept", "heading": "The terminal in five commands", "body": "Open it: on macOS, Terminal (press Cmd and Space, type Terminal). On Windows, PowerShell or the Terminal app. In VS Code, View, then Terminal. You type a command, press Enter and read the answer. Tab finishes a file name for you, and the up arrow brings back the last command. You only need a handful to start.", "code": "pwd            # where am I?\nls             # what is in this folder? (dir in old Windows cmd)\nmkdir my-site  # make a folder\ncd my-site     # go into it\ncd ..          # go back up one folder"}, {"type": "concept", "heading": "Install Node and check it", "body": "Install the LTS version from nodejs.org, then close the terminal and open a new one. node -v and npm -v should each print a version number, like v20.11.0. npm comes with Node; it downloads the tools a project lists in package.json. If you see command not found, the window was opened before the install; a new window fixes it.", "code": "node -v\nnpm -v"}, {"type": "mcq", "prompt": "You type npm -v and the terminal says command not found, right after installing Node. What is the most likely fix?", "options": ["Reinstall your operating system", "Open a new terminal window, then try again", "Type it in the browser address bar", "Put sudo in front of every command"], "answer": 1, "explain": "A terminal reads the list of installed programs when it opens. A window opened before the install does not know Node exists yet."}, {"type": "concept", "heading": "What the tools do", "body": "npm installs packages listed in package.json. Vite runs a dev server that reloads as you save, and npm run build bundles and minifies everything into a dist folder ready to deploy."}, {"type": "mcq", "prompt": "What is in the dist folder after npm run build?", "options": ["Your original source files", "Optimized files ready to upload to a host", "The node_modules packages", "Your Git history"], "answer": 1, "explain": "dist is the output. You deploy dist; you edit src."}, {"type": "worked", "heading": "Move your site into Vite", "problem": "Your exported index.html and a terminal with Node installed.", "steps": ["npm create vite@latest my-site -- --template vanilla, then cd my-site and npm install.", "Replace the generated index.html body with yours. Move the CSS from the style tag into src/style.css.", "In src/main.js add import \"./style.css\"; and keep a script tag: <script type=\"module\" src=\"/src/main.js\"></script>", "npm run dev to work locally, npm run build to produce dist."], "takeaway": "Same HTML and CSS, now with a dev server, imports, and an optimized build.", "code": "npm create vite@latest my-site -- --template vanilla\ncd my-site\nnpm install\nnpm run dev"}, {"type": "order", "prompt": "Order the commands for a fresh clone of a Vite project.", "items": ["npm install", "npm run dev", "npm run build", "npm run preview"], "explain": "Install dependencies, develop, build the output, then preview the built output before deploying.", "codeItems": true, "orderNote": "Order matters: preview serves what build produced, and nothing runs before install."}, {"type": "mcq", "prompt": "Why should node_modules stay out of Git?", "options": ["It is secret", "npm install rebuilds it from package.json and the lockfile, and it is huge", "Git cannot store JavaScript", "Vite deletes it"], "answer": 1, "explain": "Commit package.json and package-lock.json; anyone can recreate node_modules exactly from those."}, {"type": "build", "prompt": "Point your page at a Vite entry: add <script type=\"module\" src=\"/src/main.js\"></script> to your HTML, then set up the project outside Prexis and confirm each part. main.js lives in your Vite project, not in the Workshop, so the Workshop lists it under files your export does not include. That is expected: your Vite build is now the real site.", "example": "<script type=\"module\" src=\"/src/main.js\"></script>\n\n// package.json\n\"scripts\": { \"dev\": \"vite\", \"build\": \"vite build\", \"preview\": \"vite preview\" }\n\n# .gitignore\nnode_modules\ndist", "explain": "Your site has a real toolchain. The same page, now built the way production sites are built.", "checks": [{"sel": "script[type=\"module\"][src*=\"main\"]", "exists": true, "label": "A module script pointing at your main.js entry"}, {"confirm": true, "label": "node -v prints version 20 or newer in my terminal"}, {"confirm": true, "label": "package.json has dev and build scripts"}, {"confirm": true, "label": ".gitignore lists node_modules and dist"}, {"confirm": true, "label": "npm run build produced a dist folder"}]}]}, {"title": "Deploy from Git", "keywords": ["deploy", "continuous", "netlify", "vercel", "preview", "build", "ship", "pull", "request"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your site in a GitHub repo (from Git and GitHub for real) and a free Netlify or Vercel account that you sign in to with GitHub. Cost: free on the hobby plans."}, {"type": "concept", "heading": "Push to deploy", "body": "Connect your GitHub repo to Netlify or Vercel once. After that, every push to main builds and publishes the site, and every pull request gets its own preview URL. No more dragging folders."}, {"type": "worked", "heading": "Connect the repo", "problem": "Your Vite site is on GitHub. Make Netlify or Vercel build it on every push.", "steps": ["Netlify: Add new site, Import an existing project, pick GitHub and your repo.", "Build command: npm run build. Publish directory: dist. Deploy.", "Vercel: Add New, Project, import the repo. It detects Vite and fills in npm run build and dist.", "Commit the settings as a file so they live with the code: netlify.toml or vercel.json."], "takeaway": "Settings in a file are reviewed, versioned, and survive changing hosts.", "code": "# netlify.toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\""}, {"type": "mcq", "prompt": "For a Vite site, which folder should the host publish?", "options": ["src", "public", "dist", "node_modules"], "answer": 2, "explain": "Vite builds into dist. Publishing src would serve unbuilt files."}, {"type": "build", "prompt": "Link your live site from the page footer over https, then connect the repo to your host and confirm the setup.", "example": "<footer>\n  <p>Live at <a href=\"https://my-site.netlify.app\">my-site.netlify.app</a></p>\n</footer>\n\n# netlify.toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\"", "explain": "Every push now ships itself. Your job becomes writing the change; the host does the rest.", "checks": [{"sel": "footer a[href^=\"https://\"]", "exists": true, "label": "A footer link to your live site over https"}, {"confirm": true, "label": "netlify.toml or vercel.json sets npm run build and dist"}, {"confirm": true, "label": "A push to main triggered a deploy that succeeded"}, {"url": "liveUrl", "label": "Your live site address", "kind": "site"}]}, {"type": "concept", "heading": "Preview deploys", "body": "Open a pull request and the host comments with a preview URL built from that branch. Click through it before merging. Problems show up on the preview, not on your real site."}, {"type": "order", "prompt": "Order a change from branch to live.", "items": ["Create a branch", "Commit and push it", "Open a pull request", "Check the preview deploy", "Merge into main", "Watch the production deploy finish"], "explain": "The preview is the safety net between a branch and your visitors.", "codeItems": false, "orderNote": "Order matters: the preview only exists after the pull request, and production only updates after the merge."}, {"type": "mcq", "prompt": "A deploy failed. Where do you look first?", "options": ["The build log on the host", "Your DNS settings", "The browser cache", "The domain registrar"], "answer": 0, "explain": "The log shows the exact command and error. Most failures are a missing package or a typo the build caught."}]}, {"title": "Custom domain and HTTPS", "keywords": ["domain", "dns", "https", "certificate", "cname", "records", "canonical", "registrar", "ssl"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A domain name from a registrar such as Cloudflare, Porkbun or Namecheap, about 10 to 20 dollars a year. This is the only paid step in the course, and it is optional: you can pass this lesson without buying one, and come back when you are ready."}, {"type": "concept", "heading": "Domains in one minute", "body": "A registrar rents you a name like casaverde.com for about 10 to 20 dollars a year. DNS is the phone book that maps the name to your host. The theory is in Websites that work, lesson Domains, hosting, going live. Here you do it."}, {"type": "concept", "heading": "The records you will add", "body": "A record: points the bare domain (casaverde.com) at an IP address. CNAME: points a name like www at another name, such as your-site.netlify.app. TXT: proves to the host that you own the domain. Your host's domain settings page tells you exactly which values to enter."}, {"type": "mcq", "prompt": "Which record usually points www.casaverde.com at your host?", "options": ["TXT", "MX", "CNAME", "AAAA"], "answer": 2, "explain": "CNAME aliases one name to another. MX is for email, TXT is for verification."}, {"type": "order", "prompt": "Put a custom domain live.", "items": ["Buy the domain at a registrar", "Add the domain in your host's settings", "Add the DNS records the host shows you", "Wait for DNS to spread (minutes to hours)", "Confirm the certificate and force HTTPS"], "explain": "The host has to know the domain before it can tell you the records, and the certificate can only be issued once DNS points at the host.", "codeItems": false, "orderNote": "Order matters: each step needs the one before it."}, {"type": "concept", "heading": "HTTPS is free now", "body": "GitHub Pages, Netlify and Vercel issue certificates automatically once DNS points at them. Turn on Force HTTPS, pick one main address (with or without www), and redirect the other to it so search engines see one site."}, {"type": "build", "prompt": "Make the page domain-ready: add a canonical link with an https URL, make sure og:image uses https, and remove any http:// links or images. Paste your domain if you set one up.", "example": "<link rel=\"canonical\" href=\"https://casaverde.com/\">\n<meta property=\"og:image\" content=\"https://casaverde.com/share.png\">", "explain": "One canonical https address, no insecure leftovers. Browsers show the lock and search engines index one site.", "checks": [{"sel": "link[rel=\"canonical\"]", "attr": "href", "label": "A canonical link using https", "contains": "https://"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "og:image uses https", "contains": "https://"}, {"sel": "a[href^=\"http:\"], img[src^=\"http:\"], link[href^=\"http:\"]", "none": true, "label": "No http:// links, images or stylesheets"}, {"url": "domainUrl", "label": "Your custom domain (optional)", "optional": true, "kind": "domain"}]}, {"type": "mcq", "prompt": "After setup, the browser says Not secure on your domain. What is the likely cause?", "options": ["The domain is too long", "Mixed content (an http:// image or script), or the certificate is still being issued", "You used a CNAME", "Your CSS has errors"], "answer": 1, "explain": "One insecure resource drops the lock. If there is none, wait for the certificate and reload."}]}]}, {"title": "Professional quality", "lessons": [{"title": "Performance", "keywords": ["performance", "speed", "lighthouse", "web", "vitals", "lcp", "cls", "inp", "preload", "lazy", "fonts"], "steps": [{"type": "concept", "heading": "What gets measured", "body": "Lighthouse in Chrome DevTools scores a page. Core Web Vitals are the three numbers Google uses: LCP, how fast the main content appears; CLS, how much the layout jumps; INP, how fast the page responds to a tap or click."}, {"type": "mcq", "prompt": "Which change most often fixes a slow LCP?", "options": ["Minifying the HTML", "A smaller, properly sized hero image that loads first", "Adding more fonts", "Moving the footer"], "answer": 1, "explain": "The largest element is usually the hero image. Shrink it and tell the browser it matters."}, {"type": "concept", "heading": "Tell the browser what matters", "body": "fetchpriority=\"high\" on the hero image moves it to the front of the queue. link rel=\"preload\" starts a key font or image early. font-display: swap shows text in a fallback font instead of hiding it. loading=\"lazy\" defers images below the fold."}, {"type": "build", "prompt": "Speed up the page: give your hero img fetchpriority=\"high\", lazy-load an image lower down, add a link rel=\"preload\", and use font-display: swap in an @font-face rule.", "example": "<link rel=\"preload\" as=\"image\" href=\"https://picsum.photos/id/292/800/450\">\n<img src=\"https://picsum.photos/id/292/800/450\" fetchpriority=\"high\" width=\"800\" height=\"450\" alt=\"Ingredients on a table\">\n<img src=\"https://picsum.photos/id/429/600/400\" loading=\"lazy\" width=\"600\" height=\"400\" alt=\"A finished dish\">\n\n@font-face {\n  font-family: \"Body\";\n  src: local(\"Georgia\");\n  font-display: swap;\n}", "explain": "The important image arrives first, text never hides, and the rest waits its turn.", "checks": [{"sel": "img[fetchpriority=\"high\"]", "exists": true, "label": "A hero img with fetchpriority=\"high\""}, {"sel": "img[loading=\"lazy\"]", "exists": true, "label": "A lazy-loaded image"}, {"sel": "link[rel=\"preload\"]", "exists": true, "label": "A link rel=\"preload\""}, {"cssContains": "font-display", "label": "An @font-face with font-display"}]}, {"type": "code", "prompt": "Write overBudget(assets, limitKb). assets is an array of { name, kb }. Return the total kb when it is over limitKb, otherwise return 0.", "starter": "function overBudget(assets, limitKb) {\n  \n}", "tests": [{"call": "overBudget([{ name: \"hero.jpg\", kb: 300 }, { name: \"app.js\", kb: 120 }], 400)", "expect": 420}, {"call": "overBudget([{ name: \"hero.webp\", kb: 90 }, { name: \"app.js\", kb: 120 }], 400)", "expect": 0}, {"call": "overBudget([], 100)", "expect": 0}], "solution": "function overBudget(assets, limitKb) {\n  const total = assets.reduce((s, a) => s + a.kb, 0);\n  return total > limitKb ? total : 0;\n}", "explain": "A weight budget turns speed into a number a build can check, so the site stays fast after the first cleanup."}, {"type": "order", "prompt": "Run a performance pass.", "items": ["Run Lighthouse on a mobile profile", "Find the biggest issue it reports", "Fix that one thing", "Run Lighthouse again and compare"], "explain": "Measure, fix one thing, measure again. Fixing many things at once hides which one helped.", "codeItems": false, "orderNote": "Order matters: you cannot compare without a first measurement."}, {"type": "mcq", "prompt": "Which metric measures the layout jumping around while the page loads?", "options": ["LCP", "INP", "CLS", "TTFB"], "answer": 2, "explain": "Cumulative Layout Shift. Width and height on images and reserved space for ads keep it low."}]}, {"title": "Accessibility deep dive", "keywords": ["accessibility", "aria", "dialog", "modal", "focus", "skip", "link", "keyboard", "screen", "reader"], "steps": [{"type": "concept", "heading": "The first rule of ARIA", "body": "If a native element does the job, use it. button, a, dialog, details and select come with keyboard support and the right roles. ARIA adds meaning to custom widgets, but it never adds behavior; you would have to write that yourself."}, {"type": "concept", "heading": "dialog does the hard parts", "body": "dialog.showModal() opens a modal that traps focus, makes the rest of the page inert, and closes on Escape. Your job: a close button inside, and focus back on the button that opened it.", "code": "const dlg = document.querySelector(\"dialog\");\nopenBtn.addEventListener(\"click\", () => dlg.showModal());\ndlg.addEventListener(\"close\", () => openBtn.focus());"}, {"type": "build", "prompt": "Add an accessible project modal: a dialog element with a close button inside, and a script that opens it with showModal and returns focus with .focus() when it closes.", "example": "<button class=\"open-details\">Details</button>\n<dialog aria-labelledby=\"dlg-title\">\n  <h2 id=\"dlg-title\">Lemon pasta</h2>\n  <p>Ten minutes, one pan.</p>\n  <form method=\"dialog\"><button>Close</button></form>\n</dialog>\n<script type=\"module\">\n  const dlg = document.querySelector(\"dialog\");\n  const opener = document.querySelector(\".open-details\");\n  opener.addEventListener(\"click\", () => dlg.showModal());\n  dlg.addEventListener(\"close\", () => opener.focus());\n</script>", "explain": "Keyboard users can open, use and close it, and they land back where they started.", "checks": [{"sel": "dialog", "exists": true, "label": "A dialog element"}, {"sel": "dialog button", "exists": true, "label": "A close button inside the dialog"}, {"htmlContains": "showModal", "label": "The script opens it with showModal"}, {"htmlContains": ".focus()", "label": "Focus returns with .focus()"}]}, {"type": "mcq", "prompt": "Which element gives you keyboard support for free?", "options": ["<div onclick>", "<span role=\"button\">", "<button>", "<a> without href"], "answer": 2, "explain": "button is focusable and fires click on Enter and Space. An a without href is not even focusable."}, {"type": "build", "prompt": "Add a skip link: an a with class skip-link and href=\"#main\" at the very top of your HTML, id=\"main\" on your main element (you added main in Semantic HTML, SEO, and sharing; wrap your content in one if you have none), and CSS that shows the link on :focus.", "example": "<a class=\"skip-link\" href=\"#main\">Skip to content</a>\n...\n<main id=\"main\">...</main>\n\n.skip-link { position: absolute; left: -999px; }\n.skip-link:focus { left: 8px; top: 8px; }", "explain": "Keyboard users skip the nav in one keystroke instead of tabbing through every link on every page.", "checks": [{"sel": "a.skip-link[href=\"#main\"]", "exists": true, "label": "A skip link pointing at #main"}, {"sel": "main#main", "exists": true, "label": "A main element with id=\"main\"", "hint": "Add the id to the main you already have: <main id=\"main\">."}, {"cssContains": ".skip-link:focus", "label": "The skip link appears on :focus"}]}, {"type": "order", "prompt": "Run a quick screen reader test.", "items": ["Turn on the screen reader (VoiceOver or NVDA)", "Jump through the headings", "Jump through the landmarks", "Tab through every control and listen to its name", "Open and close the modal"], "explain": "Start it, then check structure, then interaction.", "codeItems": false, "groups": [[1, 2], [3, 4]], "orderNote": "Headings and landmarks can go in either order, and so can the last two checks."}, {"type": "mcq", "prompt": "A custom dropdown cannot be opened with the keyboard. What is the best fix?", "options": ["Add aria-label", "Add tabindex=\"5\"", "Use a native select, or rebuild it on a button with proper keyboard handling", "Hide it from screen readers"], "answer": 2, "explain": "Native elements first. A custom widget needs focus, keys and roles all done by hand."}]}, {"title": "Checks that run themselves: linting and CI", "keywords": ["ci", "github", "actions", "lint", "eslint", "prettier", "workflow", "pipeline", "branch", "protection", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your GitHub repo and the Vite project from earlier lessons. GitHub Actions is free for public repos and includes free monthly minutes for private ones. Cost: free."}, {"type": "concept", "heading": "Machines catch the boring mistakes", "body": "A linter (ESLint) flags likely bugs. A formatter (Prettier) settles style arguments. Continuous integration runs them, plus your build, on every pull request, so a broken change cannot slip in."}, {"type": "worked", "heading": "A GitHub Actions workflow", "problem": "Run lint and build on every pull request.", "steps": ["Create .github/workflows/ci.yml in your repo.", "on: pull_request means it runs for every PR; push to main covers direct pushes.", "Steps check out the code, set up Node, install with npm ci, then run lint and build.", "A red X on the PR means a step failed. Click it to read the log."], "takeaway": "If it would break the build, it breaks the PR first.", "code": "name: ci\non: [pull_request]\njobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build"}, {"type": "order", "prompt": "Order the pipeline.", "items": ["Check out the code", "Install with npm ci", "Lint", "Build", "Deploy"], "explain": "Nothing runs without the code, nothing builds without packages, and nothing should deploy that failed a check.", "codeItems": false, "groups": [[2, 3]], "orderNote": "Lint and build can swap; deploy always goes last."}, {"type": "mcq", "prompt": "CI fails on your pull request, but the change looks fine to you. Should you merge?", "options": ["Yes, CI is often wrong", "No. Read the log, fix the cause, and push again", "Yes, then fix it on main", "Delete the workflow"], "answer": 1, "explain": "A red check is information. Merging past it trains everyone to ignore it."}, {"type": "concept", "heading": "Branch protection", "body": "In Settings, Branches, add a rule for main: require a pull request and require the ci check to pass. Now nobody, including you, can push broken code straight to production."}, {"type": "build", "prompt": "Advanced capstone. Your page should show everything from this level: a module script, loading and error states, a search input, an accessible dialog, a skip link, @layer and @container in your CSS, and a canonical https link. Confirm the tooling outside Prexis and paste a passing CI run.", "example": "Use your work from lessons 1 to 8. Nothing new to write here; this step checks it all at once.", "explain": "A data-driven site on a real toolchain, deployed from Git, on your domain, guarded by CI. That is how professional sites run.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A module script"}, {"sel": ".loading", "exists": true, "label": "A loading state"}, {"sel": ".error[role=\"alert\"]", "exists": true, "label": "An error state with role=\"alert\""}, {"sel": "input[type=\"search\"]", "exists": true, "label": "A search input"}, {"sel": "dialog button", "exists": true, "label": "An accessible dialog with a close button"}, {"sel": "a[href=\"#main\"]", "exists": true, "label": "A skip link"}, {"cssContains": "@layer", "label": "@layer in your CSS"}, {"cssContains": "@container", "label": "@container in your CSS"}, {"sel": "link[rel=\"canonical\"]", "attr": "href", "label": "A canonical https link", "contains": "https://"}, {"confirm": true, "label": "package.json has dev, build and lint scripts"}, {"confirm": true, "label": ".github/workflows/ci.yml runs lint and build on pull_request"}, {"url": "ciUrl", "label": "A link to a passing CI run on GitHub", "kind": "ci"}]}]}]}]}, {"id": "web-expert", "subject": "Web engineering", "level": "Expert", "title": "Shipping real web apps", "track": "web", "prereq": "web-advanced", "rev": "2026-09-30", "unlock": {"after": "web-advanced", "mastery": 85, "skill": "Web apps"}, "blurb": "TypeScript, components, routing, APIs, databases and sign in, security, testing, production.", "units": [{"title": "Typed components", "lessons": [{"title": "TypeScript for the web", "keywords": ["typescript", "types", "interface", "jsdoc", "ts-check", "tsconfig", "strict", "type"], "steps": [{"type": "concept", "heading": "How the Expert level works", "body": "The real app now lives in a project on your computer, built with the Node, npm and Vite you set up in the Advanced level. Every lesson has the same three parts. The page in Prexis grows the parts a browser can show. A code step runs the core logic for real, so you know it works. A worked example walks you through the part that happens in your project, and self checks track it on your honor. If a step feels like a jump, do the worked example in your project first, then come back."}, {"type": "concept", "heading": "Before you start: what you need", "body": "Node 20 or newer, a terminal and a code editor (VS Code checks TypeScript as you type). Cost: free."}, {"type": "worked", "heading": "Start the Expert project once", "problem": "Make a TypeScript and React project you will grow through this level.", "steps": ["In a terminal: npm create vite@latest casa-app -- --template react-ts, then cd casa-app and npm install.", "npm run dev prints a local address. Open it, edit src/App.tsx, save, and watch the page update.", "Copy your Workshop page into index.html and your CSS into src/index.css, so both versions match.", "git init, commit, and push it to a new GitHub repo. Every later lesson adds to this project."], "takeaway": "One project, set up once. The rest of the level fills it in.", "code": "npm create vite@latest casa-app -- --template react-ts\ncd casa-app\nnpm install\nnpm run dev"}, {"type": "concept", "heading": "Types catch bugs before the browser does", "body": "TypeScript is JavaScript plus type annotations. The compiler checks them and then strips them, so the browser still runs plain JavaScript. You can start without a build step: add // @ts-check to a JS file and describe types in JSDoc comments; VS Code checks them as you type.", "code": "// @ts-check\n/** @typedef {{ title: string, tags: string[] }} Project */\n/** @param {Project} p */\nfunction renderCard(p) { return p.title; }"}, {"type": "mcq", "prompt": "A type error at build time saves you from what?", "options": ["Slower page loads", "A crash in a visitor's browser, like reading .length of undefined", "Bad SEO", "Merge conflicts"], "answer": 1, "explain": "The same mistake either shows up on your screen during the build, or on a visitor's screen in production."}, {"type": "concept", "heading": "Unknown data needs a guard", "body": "Data from fetch has no guaranteed shape. Type it as unknown, then write a type guard: a function that checks the shape at runtime and tells the compiler what it proved.", "code": "function isProject(x: unknown): x is Project {\n  return typeof x === \"object\" && x !== null && typeof (x as any).title === \"string\";\n}"}, {"type": "code", "prompt": "Write isProject(x). Return true only when x is a non-null object with a string title and an array tags whose items are all strings.", "starter": "function isProject(x) {\n  \n}", "tests": [{"call": "isProject({ title: \"Stew\", tags: [\"slow\"] })", "expect": true}, {"call": "isProject({ title: \"Stew\" })", "expect": false}, {"call": "isProject(null)", "expect": false}, {"call": "isProject({ title: 7, tags: [] })", "expect": false}, {"call": "isProject({ title: \"A\", tags: [1] })", "expect": false}], "solution": "function isProject(x) {\n  return typeof x === \"object\" && x !== null && typeof x.title === \"string\" && Array.isArray(x.tags) && x.tags.every((t) => typeof t === \"string\");\n}", "explain": "Check at the boundary once, then the rest of your code can trust the type."}, {"type": "build", "prompt": "Type your page script without a build: in a module script, add // @ts-check, a @typedef for Project, and a @param on renderCard.", "example": "<script type=\"module\">\n  // @ts-check\n  /** @typedef {{ title: string, summary: string }} Project */\n  /** @param {Project} p */\n  const renderCard = (p) => `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n</script>", "explain": "Your editor now flags a typo like p.tittle before you ever load the page. The next step is real .ts files with tsconfig strict.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A module script"}, {"htmlContains": "@ts-check", "label": "The script opts in with // @ts-check", "raw": true}, {"htmlContains": "@typedef", "label": "A @typedef describes Project", "raw": true}, {"htmlContains": "@param", "label": "renderCard has a typed @param", "raw": true}]}, {"type": "mcq", "prompt": "Data from fetch has an unknown shape. What is the safe approach?", "options": ["Cast it with as Project and move on", "Validate it with a type guard or schema, then use the typed value", "Turn off strict mode", "Use any everywhere"], "answer": 1, "explain": "A cast is a promise you cannot keep. A guard is a check you actually run."}, {"type": "order", "prompt": "Migrate one file to TypeScript.", "items": ["Add tsconfig.json with strict set to true", "Rename one file from .js to .ts", "Fix the errors the compiler reports", "Run tsc --noEmit in CI so it stays fixed"], "explain": "Config first so the rules apply, then one file at a time, then lock it in with CI.", "codeItems": false, "orderNote": "Order matters: the compiler needs its config before it can report errors."}]}, {"title": "A component framework", "keywords": ["react", "framework", "components", "props", "state", "usestate", "keys", "reducer", "jsx"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "The Vite project from TypeScript for the web, with React (it came with the react-ts template). For the page in Prexis you can also load React from https://esm.sh, a free public CDN, so the exported page runs it with no build. Cost: free."}, {"type": "concept", "heading": "Components are functions", "body": "A component takes props and returns UI. React, Vue and Svelte all share the idea; React is the most common, so the examples use it. Your renderCard was already a component without the name.", "code": "function Card({ title, summary }) {\n  return <article className=\"card\"><h3>{title}</h3><p>{summary}</p></article>;\n}"}, {"type": "concept", "heading": "State and keys", "body": "State is data that changes while the page is open, like a search query. When it changes, React re-runs the component and updates only what differs. In lists, each item needs a stable key so React can tell which one moved.", "code": "const [query, setQuery] = useState(\"\");\nprojects.filter(match(query)).map((p) => <Card key={p.id} {...p} />)"}, {"type": "mcq", "prompt": "Why does each item in a rendered list need a key?", "options": ["It sets the CSS class", "React uses it to match items between renders, so state and focus stay with the right item", "It sorts the list", "It is only needed on servers"], "answer": 1, "explain": "Without stable keys, deleting the first item can shift every input's state to the wrong card."}, {"type": "code", "prompt": "State updates should not mutate. Write reducer(state, action) for { query, tags }. On { type: \"query\", value } return a new state with query set. On { type: \"toggleTag\", tag } add the tag if missing or remove it if present. Return state unchanged for anything else.", "starter": "function reducer(state, action) {\n  \n}", "tests": [{"call": "reducer({ query: \"\", tags: [] }, { type: \"query\", value: \"pasta\" })", "expect": {"query": "pasta", "tags": []}}, {"call": "reducer({ query: \"\", tags: [\"quick\"] }, { type: \"toggleTag\", tag: \"vegan\" })", "expect": {"query": "", "tags": ["quick", "vegan"]}}, {"call": "reducer({ query: \"\", tags: [\"quick\", \"vegan\"] }, { type: \"toggleTag\", tag: \"quick\" })", "expect": {"query": "", "tags": ["vegan"]}}, {"call": "(() => { const s = { query: \"a\", tags: [] }; reducer(s, { type: \"query\", value: \"b\" }); return s.query; })()", "expect": "a"}], "solution": "function reducer(state, action) {\n  if (action.type === \"query\") return { ...state, query: action.value };\n  if (action.type === \"toggleTag\") {\n    const has = state.tags.includes(action.tag);\n    return { ...state, tags: has ? state.tags.filter((t) => t !== action.tag) : [...state.tags, action.tag] };\n  }\n  return state;\n}", "explain": "Return new objects instead of editing old ones. That is how React notices a change."}, {"type": "build", "prompt": "Mark the island your framework will own: a div with id=\"cards-root\" holding three static .card fallbacks, and a module script with a real component that keeps state with useState and gives each card a key. Import React from https://esm.sh so the exported page runs it, as in the example. Comments do not count; the check reads your code.", "example": "<div id=\"cards-root\">\n  <article class=\"card\"><h3>Lemon pasta</h3></article>\n  <article class=\"card\"><h3>Tomato soup</h3></article>\n  <article class=\"card\"><h3>Green salad</h3></article>\n</div>\n<script type=\"module\">\n  import { createElement as h, useState } from \"https://esm.sh/react@18\";\n  import { createRoot } from \"https://esm.sh/react-dom@18/client\";\n  const recipes = [\n    { id: 1, title: \"Lemon pasta\" },\n    { id: 2, title: \"Tomato soup\" },\n    { id: 3, title: \"Green salad\" },\n  ];\n  function CardGrid() {\n    const [query, setQuery] = useState(\"\");\n    const shown = recipes.filter((r) => r.title.toLowerCase().includes(query.toLowerCase()));\n    return h(\"div\", null,\n      h(\"input\", { type: \"search\", \"aria-label\": \"Filter recipes\", value: query, onChange: (e) => setQuery(e.target.value) }),\n      shown.map((r) => h(\"article\", { key: r.id, className: \"card\" }, h(\"h3\", null, r.title))));\n  }\n  createRoot(document.getElementById(\"cards-root\")).render(h(CardGrid));\n</script>\n\nIn your Vite + React project the same component is JSX in src/CardGrid.jsx:\n  shown.map((r) => <Card key={r.id} {...r} />)", "explain": "The static cards keep the page useful before JavaScript loads; React takes over #cards-root when it does. Export it and type in the filter box to watch state at work.", "checks": [{"sel": "#cards-root", "exists": true, "label": "A mount point with id=\"cards-root\""}, {"sel": "#cards-root .card", "count": 3, "label": "Three fallback cards inside it"}, {"htmlMatch": "\\buseState\\s*\\(", "label": "The component calls useState( in code, not in a comment", "hint": "Write the component for real, like the example. Lines inside // or /* */ comments are ignored."}, {"htmlMatch": "\\bkey\\s*[:=]\\s*[{\\w\\\"']", "label": "Each rendered card gets a key in code", "hint": "Pass a key when you map: h(\"article\", { key: r.id }, ...) or <Card key={r.id} /> in JSX."}]}, {"type": "order", "prompt": "Order what happens when state changes.", "items": ["The visitor types in the search box", "onChange calls setQuery", "React re-runs the component with the new state", "React compares the new output to the old", "Only the changed DOM nodes update"], "explain": "Event, state update, re-render, diff, patch. You write the first two; React does the rest.", "codeItems": false, "orderNote": "Each step triggers the next."}, {"type": "mcq", "prompt": "When is plain HTML and CSS a better choice than a framework?", "options": ["Never", "A mostly static content site with a little interactivity", "Any site with a form", "Any site with more than one page"], "answer": 1, "explain": "Frameworks pay off with lots of changing state. For a brochure site they add weight and nothing else."}]}, {"title": "Routing and app structure", "keywords": ["routing", "router", "spa", "routes", "history", "hash", "404", "layout", "next"], "steps": [{"type": "concept", "heading": "Pages or routes", "body": "Separate HTML files are the simplest router there is. A single page app swaps views in JavaScript and updates the URL with history.pushState or the hash. Meta frameworks like Next.js or Astro generate routes from folders and can render on the server."}, {"type": "mcq", "prompt": "What does a 404 route handle?", "options": ["Server crashes", "Any URL that matches no other route", "Slow pages", "Signed out users"], "answer": 1, "explain": "Every router needs a catch-all, or unknown URLs show a blank screen instead of a helpful page."}, {"type": "code", "prompt": "Write matchRoute(path) for the routes \"/\", \"/projects\" and \"/projects/:id\". Return { name, params }: names are \"home\", \"projects\", \"project\" (with params.id), and \"notFound\" with empty params for anything else. Ignore one trailing slash.", "starter": "function matchRoute(path) {\n  \n}", "tests": [{"call": "matchRoute(\"/\")", "expect": {"name": "home", "params": {}}}, {"call": "matchRoute(\"/projects/\")", "expect": {"name": "projects", "params": {}}}, {"call": "matchRoute(\"/projects/lemon-pasta\")", "expect": {"name": "project", "params": {"id": "lemon-pasta"}}}, {"call": "matchRoute(\"/nope\")", "expect": {"name": "notFound", "params": {}}}], "solution": "function matchRoute(path) {\n  const p = path.length > 1 && path.endsWith(\"/\") ? path.slice(0, -1) : path;\n  if (p === \"/\") return { name: \"home\", params: {} };\n  if (p === \"/projects\") return { name: \"projects\", params: {} };\n  const m = /^\\/projects\\/([^/]+)$/.exec(p);\n  if (m) return { name: \"project\", params: { id: m[1] } };\n  return { name: \"notFound\", params: {} };\n}", "explain": "Every router, from a dozen lines to Next.js, is this: turn a URL into a name and some parameters."}, {"type": "build", "prompt": "Add hash routes to your page: at least two links whose href starts with #/, a section with data-route=\"not-found\" for unknown URLs, and a script that listens for hashchange.", "example": "<nav>\n  <a href=\"#/\">Home</a>\n  <a href=\"#/projects\">Projects</a>\n</nav>\n<section data-route=\"not-found\" hidden>\n  <h2>Page not found</h2>\n  <p><a href=\"#/\">Back home</a></p>\n</section>\n<script type=\"module\">\n  const routes = [\"#/\", \"#/projects\"];\n  function render() {\n    const hash = location.hash || \"#/\";\n    document.querySelector('[data-route=\"not-found\"]').hidden = routes.includes(hash);\n  }\n  window.addEventListener(\"hashchange\", render);\n  render();\n</script>", "explain": "Hash routes work on any static host with no server setup, which makes them a safe first router.", "checks": [{"sel": "a[href^=\"#/\"]", "count": 2, "label": "At least two #/ route links"}, {"sel": "[data-route=\"not-found\"]", "exists": true, "label": "A not-found view"}, {"htmlContains": "hashchange", "label": "The script listens for hashchange"}]}, {"type": "concept", "heading": "A shared layout", "body": "Header, nav and footer render once in a layout; only the inner view changes per route. After each route change, set document.title and move focus to the new heading so screen reader users know the page changed."}, {"type": "order", "prompt": "Order what a client router does when a link is clicked.", "items": ["Intercept the click", "Update the URL with history.pushState", "Match the URL to a route", "Render that view inside the layout", "Update document.title and move focus to the new heading"], "explain": "The URL changes first so back and forward work, then the view, then the announcements.", "codeItems": false, "orderNote": "Order matters: rendering needs the matched route, and focus needs the rendered heading."}, {"type": "mcq", "prompt": "After a client route change, screen reader users hear nothing. What fixes it?", "options": ["Reload the page", "Move focus to the new view's heading and update document.title", "Add more ARIA labels to the nav", "Use a slower transition"], "answer": 1, "explain": "A full page load announces itself. A JavaScript view swap has to announce itself on purpose."}]}]}, {"title": "Backend", "lessons": [{"title": "Your own API", "keywords": ["api", "serverless", "functions", "http", "status", "codes", "rest", "env", "secrets", "backend"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free Netlify or Vercel account to run serverless functions (the free tiers cover a small site), and Node to test the function locally with netlify dev or vercel dev. Cost: free."}, {"type": "concept", "heading": "An API is a URL that returns data", "body": "GET reads, POST creates, PUT or PATCH updates, DELETE removes. Status codes report the result: 200 OK, 201 Created, 400 bad input, 401 not signed in, 404 not found, 405 wrong method, 500 server error."}, {"type": "mcq", "prompt": "Which status code means a new item was created?", "options": ["200", "201", "204", "302"], "answer": 1, "explain": "201 Created. 200 is a general success, 204 is success with no body."}, {"type": "concept", "heading": "Serverless functions", "body": "Netlify and Vercel run a function file when its URL is requested. No server to manage, and small sites stay on the free tier. On Vercel, api/recipes.js answers /api/recipes; name the file after your data.", "code": "export default function handler(req, res) {\n  if (req.method !== \"GET\") return res.status(405).json({ error: \"Method not allowed\" });\n  res.status(200).json(projects);\n}"}, {"type": "code", "prompt": "Write handle(req, projects). For method \"GET\" return { status: 200, body: projects }. For any other method return { status: 405, body: { error: \"Method not allowed\" } }.", "starter": "function handle(req, projects) {\n  \n}", "tests": [{"call": "handle({ method: \"GET\" }, [{ id: 1 }])", "expect": {"status": 200, "body": [{"id": 1}]}}, {"call": "handle({ method: \"DELETE\" }, [])", "expect": {"status": 405, "body": {"error": "Method not allowed"}}}, {"call": "handle({ method: \"POST\" }, []).status", "expect": 405}], "solution": "function handle(req, projects) {\n  if (req.method === \"GET\") return { status: 200, body: projects };\n  return { status: 405, body: { error: \"Method not allowed\" } };\n}", "explain": "Pure request in, response out. Keeping the logic in a plain function also makes it easy to test."}, {"type": "concept", "heading": "Secrets stay on the server", "body": "API keys go in environment variables on the host, read with process.env.NAME inside the function. Anything in your page's JavaScript is public. Commit a .env.example with empty values, and list .env in .gitignore."}, {"type": "build", "prompt": "Point the front end at your API: a module script that fetches one of your own routes (any /api/ path, such as /api/recipes or /api/projects), and a new message with id=\"api-error\" and role=\"alert\" that the script shows when the request fails. Then build the function outside Prexis and confirm it.", "example": "<p id=\"api-error\" role=\"alert\" hidden>Could not reach the recipe API.</p>\n<script type=\"module\">\n  try {\n    const res = await fetch(\"/api/recipes\");\n    if (!res.ok) throw new Error(\"HTTP \" + res.status);\n    const recipes = await res.json();\n  } catch (e) {\n    document.getElementById(\"api-error\").hidden = false;\n  }\n</script>\n\n# .gitignore\n.env", "explain": "Your site now has a backend. The data can change without redeploying the page. Until the function is deployed, the exported page shows your api-error message, which is the point of having one.", "checks": [{"htmlMatch": "fetch\\(\\s*[\\\"'`]/api/[\\w-]+", "label": "The page fetches one of your /api/ routes", "hint": "Name the route after your data, for example fetch(\"/api/recipes\"). Any /api/ path works."}, {"sel": "#api-error[role=\"alert\"]", "exists": true, "label": "A new #api-error message with role=\"alert\"", "hint": "The .error from Fetching data does not count; this message is for API failures. Add <p id=\"api-error\" role=\"alert\" hidden>...</p>."}, {"htmlMatch": "getElementById\\(\\s*[\\\"']api-error[\\\"']|querySelector\\(\\s*[\\\"']#api-error[\\\"']", "label": "The script shows #api-error when the request fails", "hint": "In your catch, set document.getElementById(\"api-error\").hidden = false."}, {"confirm": true, "label": "My api function returns 200 for GET and 405 for other methods"}, {"confirm": true, "label": ".env is in .gitignore and the function reads process.env"}]}, {"type": "order", "prompt": "Order a request from click to cards.", "items": ["The visitor clicks Load projects", "The browser sends GET /api/projects", "The host runs your function", "The function returns JSON with status 200", "The page renders the cards"], "explain": "Browser to host to function and back. Every step is a place a log line can tell you what went wrong.", "codeItems": false, "orderNote": "Each step waits on the one before it."}]}, {"title": "Databases and sign in", "keywords": ["database", "sql", "postgres", "supabase", "auth", "sign", "login", "session", "authorization", "tables"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free Supabase or Neon account for the database, and an auth provider (Supabase Auth, Clerk or Auth.js all have free tiers). Cost: free for a small project; paid plans start when you have real traffic."}, {"type": "concept", "heading": "Tables, rows, and when hosted is enough", "body": "A table is a list of rows with fixed columns: projects(id, title, owner_id). Hosted Postgres from Supabase or Neon gives you a real database with a free tier and nothing to maintain. Your API function reads from it instead of data.json."}, {"type": "concept", "heading": "Sign in without storing passwords", "body": "Use an auth provider (Supabase Auth, Clerk, Auth.js) instead of storing passwords yourself. After sign in, the server sets a session cookie. Every protected API call checks that session and answers 401 without one."}, {"type": "mcq", "prompt": "Where must the check \"can this user edit this project?\" happen?", "options": ["In the button's onclick", "On the server, in the API or the database rules", "In CSS", "In localStorage"], "answer": 1, "explain": "Anything in the browser can be edited by the visitor. Only the server's answer counts."}, {"type": "code", "prompt": "Write canEdit(user, project). Return true when user exists and either user.id equals project.ownerId or user.role is \"admin\". Return false otherwise.", "starter": "function canEdit(user, project) {\n  \n}", "tests": [{"call": "canEdit({ id: 1, role: \"user\" }, { ownerId: 1 })", "expect": true}, {"call": "canEdit({ id: 2, role: \"user\" }, { ownerId: 1 })", "expect": false}, {"call": "canEdit({ id: 3, role: \"admin\" }, { ownerId: 1 })", "expect": true}, {"call": "canEdit(null, { ownerId: 1 })", "expect": false}], "solution": "function canEdit(user, project) {\n  if (!user) return false;\n  return user.id === project.ownerId || user.role === \"admin\";\n}", "explain": "Signed out is false first. Then ownership, then roles. Run it on the server for every write."}, {"type": "build", "prompt": "Add sign in to the page: a button with class sign-in, an element marked data-requires-auth for content only signed-in users see, and code that handles a 401 response.", "example": "<button class=\"sign-in\" hidden>Sign in</button>\n<section data-requires-auth hidden>\n  <h2>Your drafts</h2>\n</section>\n<script type=\"module\">\n  try {\n    const res = await fetch(\"/api/drafts\");\n    if (res.status === 401) {\n      document.querySelector(\".sign-in\").hidden = false;\n    } else if (res.ok) {\n      document.querySelector(\"[data-requires-auth]\").hidden = false;\n    }\n  } catch (e) {\n    document.querySelector(\".sign-in\").hidden = false;\n  }\n</script>", "explain": "The page shows what a visitor may see, and the server enforces it.", "checks": [{"sel": "button.sign-in", "exists": true, "label": "A sign-in button"}, {"sel": "[data-requires-auth]", "exists": true, "label": "A section marked data-requires-auth"}, {"htmlMatch": "\\.status\\s*(===?|!==?)\\s*401\\b|\\b401\\s*(===?|!==?)\\s*[\\w.]*status\\b|\\bcase\\s+401\\b", "label": "The script checks the response for status 401", "hint": "Compare the response status, for example: if (res.status === 401) { show the sign-in button }."}]}, {"type": "order", "prompt": "Order the sign in flow.", "items": ["The visitor presses Sign in", "The app redirects to the auth provider", "The visitor proves who they are", "The provider redirects back with a code", "The server swaps the code for a session cookie", "API calls now carry the session"], "explain": "This is the OAuth shape almost every sign in button uses.", "codeItems": false, "orderNote": "Each step needs the result of the one before it."}, {"type": "mcq", "prompt": "A signed-in user can see another user's drafts. What is missing?", "options": ["A prettier login page", "A server-side check that filters by owner, such as row level security", "A longer session", "HTTPS"], "answer": 1, "explain": "Authentication says who you are. Authorization says what you may see, and it has to run on the server."}]}, {"title": "Security for web developers", "keywords": ["security", "xss", "csrf", "injection", "csp", "headers", "escape", "secrets", "dependabot"], "steps": [{"type": "concept", "heading": "The three classics", "body": "XSS: attacker text becomes script on your page. CSRF: another site makes a visitor's browser send a request to yours. Injection: input changes the meaning of a database query. Escaping output, SameSite cookies, and parameterized queries stop most of it."}, {"type": "mcq", "prompt": "Which line has an XSS risk when comment comes from a visitor?", "options": ["el.textContent = comment", "el.innerHTML = comment", "el.setAttribute(\"title\", comment)", "console.log(comment)"], "answer": 1, "explain": "innerHTML parses the string as HTML, so a crafted comment can run script."}, {"type": "code", "prompt": "Write escapeHtml(s). Replace & with &amp;, < with &lt;, > with &gt;, \" with &quot; and ' with &#39;. Do & first.", "starter": "function escapeHtml(s) {\n  \n}", "tests": [{"call": "escapeHtml(\"<b>hi</b>\")", "expect": "&lt;b&gt;hi&lt;/b&gt;"}, {"call": "escapeHtml(\"Tom & Jerry\")", "expect": "Tom &amp; Jerry"}, {"call": "escapeHtml(\"say \\\"hi\\\" it's\")", "expect": "say &quot;hi&quot; it&#39;s"}], "solution": "function escapeHtml(s) {\n  return String(s).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\").replace(/'/g, \"&#39;\");\n}", "explain": "Ampersand first, or you would double-escape the entities you just made."}, {"type": "concept", "heading": "Headers that defend you", "body": "Content-Security-Policy lists where scripts, styles and images may come from, so injected script is blocked. X-Content-Type-Options: nosniff and a Referrer-Policy close smaller holes. Set them in netlify.toml or vercel.json; a meta tag can carry CSP too."}, {"type": "concept", "heading": "A policy that does not lock you out", "body": "default-src 'self' on its own blocks every inline style tag and inline script, and every image from another site. Your exported page is exactly that: one file with an inline style, inline scripts, picsum images and React from esm.sh. So name each kind: style-src and script-src with 'self' and 'unsafe-inline', script-src with any host you import from, and img-src with https: and data:. Once you have a build step, replace 'unsafe-inline' in script-src with nonces or hashes."}, {"type": "build", "prompt": "Harden the page: a meta Content-Security-Policy with default-src plus style-src, script-src and img-src that still allow your own page (its inline style and scripts, your image hosts, and https://esm.sh if you import React from it), a meta referrer policy, and no innerHTML anywhere in your page code. The innerHTML from JavaScript modules and components counts: rebuild those cards with createElement and textContent, as the example shows. Then set the headers on your host.", "example": "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://esm.sh; img-src 'self' https: data:\">\n<meta name=\"referrer\" content=\"strict-origin-when-cross-origin\">\n\nReplace the innerHTML line from JavaScript modules and components:\n  const grid = document.querySelector(\".gallery, .grid\");\n  grid.replaceChildren(...projects.map((p) => {\n    const card = document.createElement(\"article\");\n    card.className = \"card\";\n    const title = document.createElement(\"h3\");\n    title.className = \"card__title\";\n    title.textContent = p.title;\n    card.append(title);\n    return card;\n  }));", "explain": "Export puts these meta tags in the head where browsers enforce them. Your policy allows your own inline style and scripts and nothing you did not name; tighten script-src with nonces once you have a build.", "checks": [{"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "A CSP meta tag with default-src", "contains": "default-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets style-src", "contains": "style-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets script-src", "contains": "script-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets img-src", "contains": "img-src"}, {"cspOk": true, "label": "The policy still lets your own styles, scripts and images load", "hint": "The lines below say what your policy would block in the exported site. The Workshop shows the same list next to Export my site."}, {"sel": "meta[name=\"referrer\"]", "attr": "content", "label": "A referrer policy"}, {"htmlContains": "innerHTML", "label": "No innerHTML in your page code", "negate": true, "hint": "Look in the module script from JavaScript modules and components: replace the .innerHTML = line with replaceChildren and createElement, as the example shows."}, {"confirm": true, "label": "My host config sends X-Content-Type-Options: nosniff"}]}, {"type": "order", "prompt": "Respond to a leaked API key.", "items": ["Revoke the key at the provider", "Create a new key", "Update the environment variable on the host", "Redeploy", "Review the provider's logs for misuse"], "explain": "Kill it first; every minute it works is a minute it can be used. Deleting the commit does not help, the key is already copied.", "codeItems": false, "orderNote": "Revoke comes first, always."}, {"type": "concept", "heading": "Keep dependencies patched", "body": "Turn on Dependabot alerts and security updates in your repo's Settings. It opens pull requests when a package you use has a known hole, and your CI tells you if the update breaks anything."}]}]}, {"title": "Production", "lessons": [{"title": "Testing at depth", "keywords": ["testing", "tests", "unit", "e2e", "playwright", "vitest", "flaky", "tdd", "ci"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Vitest and Playwright, both free from npm. Playwright downloads its own browsers the first time, about 300 MB. Your CI from Checks that run themselves runs them. Cost: free."}, {"type": "concept", "heading": "Three kinds of tests", "body": "Unit tests check one function, fast. Integration tests check pieces together, like an API with its database. End to end tests drive a real browser through a real flow, like signing in. Many unit tests, a few end to end tests."}, {"type": "mcq", "prompt": "Which test type catches a broken sign in flow?", "options": ["A unit test of a helper", "An end to end test that signs in through the browser", "A lint rule", "A type check"], "answer": 1, "explain": "Sign in crosses the page, the provider and your API. Only a test that drives the whole path sees it break."}, {"type": "code", "prompt": "Red, green: these tests already exist. Write slugify(title) so they pass: lowercase, trim, turn every run of non letters or digits into one hyphen, and drop hyphens at the ends.", "starter": "function slugify(title) {\n  \n}", "tests": [{"call": "slugify(\"Lemon Pasta\")", "expect": "lemon-pasta"}, {"call": "slugify(\"  Fast & Easy!  \")", "expect": "fast-easy"}, {"call": "slugify(\"10 minute meals\")", "expect": "10-minute-meals"}], "solution": "function slugify(title) {\n  return String(title).toLowerCase().trim().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\");\n}", "explain": "The tests defined done before the code existed. That is test driven development in one step."}, {"type": "worked", "heading": "An end to end test with Playwright", "problem": "Check that search filters the cards on the real page.", "steps": ["npm init playwright@latest adds the runner and an example.", "page.goto opens your local build. getByTestId finds elements by data-testid.", "fill types into the search box; expect waits until the visible card count matches.", "npx playwright test runs it locally; the same command runs in CI."], "takeaway": "Stable test ids make tests survive redesigns.", "code": "test(\"search filters cards\", async ({ page }) => {\n  await page.goto(\"/\");\n  await page.getByTestId(\"search\").fill(\"pasta\");\n  await expect(page.getByTestId(\"card\")).toHaveCount(1);\n});"}, {"type": "build", "prompt": "Make the page testable: data-testid=\"search\" on your search input, data-testid=\"card\" on at least three cards, and an email error message with id=\"email-error\" and aria-live. Then add the tests to CI.", "example": "<input id=\"search\" type=\"search\" data-testid=\"search\">\n<article class=\"card\" data-testid=\"card\">...</article>\n<p id=\"email-error\" aria-live=\"polite\"></p>", "explain": "Tests can now find what they need without depending on your class names or layout.", "checks": [{"sel": "[data-testid=\"search\"]", "exists": true, "label": "A search input with data-testid=\"search\""}, {"sel": "[data-testid=\"card\"]", "count": 3, "label": "At least three cards with data-testid=\"card\""}, {"sel": "#email-error[aria-live]", "exists": true, "label": "An email error region with aria-live"}, {"confirm": true, "label": "ci.yml runs npm test on every pull request"}]}, {"type": "order", "prompt": "Order the red, green, refactor loop.", "items": ["Write a failing test", "Run it and watch it fail", "Write the least code that passes", "Run it and watch it pass", "Refactor with the test still green"], "explain": "Watching it fail proves the test can fail. Refactoring last means you change shape with a safety net.", "codeItems": false, "orderNote": "Order matters: that is the whole method."}, {"type": "mcq", "prompt": "A test fails only sometimes. What is it called, and what do you do?", "options": ["A smoke test; delete it", "A flaky test; find the race or shared state and fix it, quarantining it meanwhile", "A unit test; rerun until green", "A regression; revert everything"], "answer": 1, "explain": "Flaky tests teach a team to ignore red. Fix the timing or isolation problem, do not just retry."}]}, {"title": "Running in production", "keywords": ["production", "monitoring", "logs", "errors", "uptime", "health", "rollback", "incident", "analytics"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Optional: a free Sentry account for error tracking and a free uptime checker such as UptimeRobot or Better Stack. The lesson works without them; you send errors to your own /api/log. Cost: free."}, {"type": "concept", "heading": "Know before your users tell you", "body": "Logs show what your functions did. Error tracking (Sentry and similar) collects browser and server errors with stack traces. An uptime check hits a URL every minute. Privacy friendly analytics (Plausible, Fathom) show traffic without tracking people."}, {"type": "mcq", "prompt": "Users report a blank page. Which tool tells you the actual error?", "options": ["Uptime monitoring", "Browser error tracking with stack traces", "Analytics page views", "The DNS dashboard"], "answer": 1, "explain": "Uptime only says the server answered. The blank page is a script error in their browser, which error tracking captures."}, {"type": "code", "prompt": "Write health(checks). checks is an object like { db: true, auth: false }. Return { status: 200, body: { ok: true } } when every value is true, otherwise { status: 503, body: { ok: false, failing: [names of false checks] } }.", "starter": "function health(checks) {\n  \n}", "tests": [{"call": "health({ db: true, auth: true })", "expect": {"status": 200, "body": {"ok": true}}}, {"call": "health({ db: true, auth: false })", "expect": {"status": 503, "body": {"ok": false, "failing": ["auth"]}}}, {"call": "health({})", "expect": {"status": 200, "body": {"ok": true}}}], "solution": "function health(checks) {\n  const failing = Object.keys(checks).filter((k) => !checks[k]);\n  if (!failing.length) return { status: 200, body: { ok: true } };\n  return { status: 503, body: { ok: false, failing } };\n}", "explain": "An uptime check pointed at /api/health now tells you which dependency broke, not just that something did."}, {"type": "build", "prompt": "Catch errors on the page: an element with id=\"app-error\" and role=\"alert\" as a friendly fallback, and a module script that listens for unhandledrejection and sends errors to a trackError( function. Do not call it reportError: browsers already have a built-in window.reportError, and a function with that name replaces it.", "example": "<div id=\"app-error\" role=\"alert\" hidden>Something broke. Reload, or try again in a minute.</div>\n<script type=\"module\">\n  function trackError(e) {\n    navigator.sendBeacon(\"/api/log\", JSON.stringify({ message: String(e) }));\n    document.getElementById(\"app-error\").hidden = false;\n  }\n  window.addEventListener(\"error\", (e) => trackError(e.message));\n  window.addEventListener(\"unhandledrejection\", (e) => trackError(e.reason));\n</script>", "explain": "Visitors see a calm message instead of a blank page, and you get the error.", "checks": [{"sel": "#app-error[role=\"alert\"]", "exists": true, "label": "A friendly error region with role=\"alert\""}, {"htmlContains": "unhandledrejection", "label": "The script catches unhandled promise rejections"}, {"htmlContains": "trackError(", "label": "Errors go to a trackError( function"}, {"htmlMatch": "function\\s+reportError\\b|(const|let|var)\\s+reportError\\b", "label": "Nothing replaces the browser's built-in reportError", "negate": true, "hint": "Rename your function to trackError so window.reportError keeps working."}]}, {"type": "concept", "heading": "Rollbacks and flags", "body": "Netlify and Vercel keep every deploy. Rolling back is one click on an older one, and it takes seconds. Feature flags let you ship code turned off, then turn it on for a few users first."}, {"type": "order", "prompt": "Order an incident.", "items": ["Notice: an alert or a user report", "Roll back to the last good deploy", "Find the cause in logs and error reports", "Fix it with a test that would have caught it", "Write a short note on what happened"], "explain": "Stop the damage before you investigate. Investigating a live outage costs users every minute.", "codeItems": false, "orderNote": "Order matters: roll back first, debug second."}, {"type": "mcq", "prompt": "A deploy broke checkout late at night. What is the fastest safe move?", "options": ["Debug it live on production", "Roll back to the previous deploy, then debug in the morning", "Turn off the whole site", "Push a guess and hope"], "answer": 1, "explain": "A rollback is tested, instant and reversible. A midnight hotfix is none of those."}]}, {"title": "Working like a pro: reviews, docs, and open source", "keywords": ["review", "pull", "request", "docs", "readme", "contributing", "open", "source", "semver", "changelog", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your app's GitHub repo and its live deploy from the earlier lessons. Contributing to someone else's project needs only your GitHub account. Cost: free."}, {"type": "concept", "heading": "Pull request habits", "body": "Small changes, one idea each. A title that says what changed, a description that says why, and screenshots for anything visual. A reviewer should understand it in five minutes."}, {"type": "concept", "heading": "Giving and getting review", "body": "Comment on the code, not the person. Ask questions when unsure, say which comments block the merge, and suggest a fix when you can. When receiving, answer every comment, even with \"done\"."}, {"type": "mcq", "prompt": "Which review comment is most useful?", "options": ["This is wrong.", "Why not do it differently?", "This fetch has no catch, so a network error leaves the spinner forever. Wrap it and show .error?", "LGTM"], "answer": 2, "explain": "Specific problem, specific consequence, suggested fix."}, {"type": "order", "prompt": "Contribute to an open source project.", "items": ["Find an issue labeled good first issue", "Fork the repo", "Create a branch", "Make the change and run the tests", "Open a pull request that links the issue"], "explain": "Fork, branch, change, test, propose. Comment on the issue first so nobody duplicates the work.", "codeItems": false, "orderNote": "Each step needs the one before it."}, {"type": "concept", "heading": "Versions that mean something", "body": "Semantic versioning: MAJOR.MINOR.PATCH. Breaking change bumps major, new feature bumps minor, fix bumps patch. A CHANGELOG lists what changed in each version in plain words."}, {"type": "mcq", "prompt": "What belongs in a good bug report?", "options": ["Just \"it is broken\"", "Steps to reproduce, what you expected, what happened, and your browser and device", "A screenshot of the whole desktop", "The fix only"], "answer": 1, "explain": "If the maintainer can reproduce it in a minute, it gets fixed."}, {"type": "build", "prompt": "Expert capstone. Your page should carry the whole app: components in #cards-root, testable search, a not-found route, a CSP, an error fallback, a health check link, and a footer link to the repo. Confirm the rest of the stack outside Prexis and paste your live app URL.", "example": "Use your work from lessons 1 to 8. Add a status link, for example <a href=\"/api/health\">Status</a> in the footer.", "explain": "Typed, componentized, routed, backed by an API and a database, secured, tested, monitored and documented. You build and run real web apps.", "checks": [{"sel": "#cards-root .card", "count": 3, "label": "Cards rendered in #cards-root"}, {"sel": "[data-testid=\"search\"]", "exists": true, "label": "A testable search input"}, {"sel": "[data-route=\"not-found\"]", "exists": true, "label": "A not-found route"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "exists": true, "label": "A Content-Security-Policy"}, {"cspOk": true, "label": "The policy still lets your own page load"}, {"sel": "#app-error[role=\"alert\"]", "exists": true, "label": "An error fallback"}, {"htmlContains": "/api/health", "label": "A link to /api/health"}, {"sel": "footer a[href*=\"github.com\"]", "exists": true, "label": "A footer link to the repo"}, {"confirm": true, "label": "TypeScript strict, unit tests and end to end tests run in CI"}, {"confirm": true, "label": "README covers setup, deploy and rollback; CONTRIBUTING.md, a PR template and a LICENSE exist"}, {"url": "appUrl", "label": "Your live app address", "kind": "site"}]}]}]}]}, {"id": "js-intermediate", "subject": "JavaScript patterns", "level": "Intermediate", "title": "JavaScript that holds up", "track": "code", "prereq": "core-js", "rev": "2026-10-02", "unlock": {"after": "core-js", "mastery": 55, "skill": "JavaScript"}, "blurb": "Destructuring, Map and Set, sorting, regex, safe numbers, errors, classes, pure functions.", "units": [{"title": "Data in motion", "lessons": [{"title": "Destructuring and defaults", "keywords": ["javascript", "js", "destructuring", "defaults", "parameters", "options", "rest"], "steps": [{"type": "concept", "heading": "Unpack what you need", "body": "Destructuring pulls named values out of an object or array in one line. It reads like a shape: the left side says where each value lands. Defaults fill any value that comes back undefined.", "code": "const { name, role = \"guest\" } = { name: \"Ada\" };\n// name is \"Ada\", role is \"guest\"\nconst [first, , third] = [10, 20, 30];\n// first is 10, third is 30"}, {"type": "output", "prompt": "What does this print?", "code": "const { size = 3, color = \"red\" } = { color: \"blue\" };\nconsole.log(size + \" \" + color);", "expect": "3 blue", "explain": "size was missing, so its default 3 applied. color was present, so the default was ignored."}, {"type": "mcq", "prompt": "Which value does NOT trigger a destructuring default?", "options": ["A missing key", "A key set to undefined", "A key set to null", "An empty object"], "answer": 2, "explain": "Defaults only fire for undefined. null is a real value, so { a = 1 } = { a: null } leaves a as null."}, {"type": "concept", "heading": "Options objects", "body": "Functions with more than two settings read better with one options object than with a row of positional arguments. Destructure it in the parameter list and give every option a default, then give the whole object a default of {} so calling with nothing still works.", "code": "function greet({ name = \"friend\", loud = false } = {}) {\n  const s = \"Hello, \" + name;\n  return loud ? s.toUpperCase() : s;\n}"}, {"type": "code", "prompt": "Write label(opts) that returns text like \"Coffee x2\". opts may carry name (default \"Item\") and qty (default 1). Calling label() with no argument must work too.", "starter": "function label(opts) {\n  return opts.name + \" x\" + opts.qty;\n}", "tests": [{"call": "label({ name: \"Coffee\", qty: 2 })", "expect": "Coffee x2"}, {"call": "label({ name: \"Tea\" })", "expect": "Tea x1"}, {"call": "label()", "expect": "Item x1"}, {"call": "label({ qty: 0 })", "expect": "Item x0"}], "solution": "function label({ name = \"Item\", qty = 1 } = {}) {\n  return name + \" x\" + qty;\n}", "explain": "Defaults in the parameter list handle the missing keys, and = {} handles the missing object. qty 0 stays 0 because only undefined triggers a default."}, {"type": "order", "prompt": "Order what happens when greet({ name: \"Ada\" }) runs with the signature above.", "items": ["The call passes one object", "The parameter default {} is skipped because an object arrived", "name is read as \"Ada\"", "loud is undefined, so its default false applies", "The body runs with both names bound"], "explain": "The outer default only fires when the whole argument is undefined. Then each key is unpacked and defaulted on its own.", "codeItems": false}, {"type": "code", "prompt": "Write swapEnds(arr) that returns a new array with the first and last items swapped, using destructuring. Arrays shorter than 2 come back as copies.", "starter": "function swapEnds(arr) {\n  return arr;\n}", "tests": [{"call": "swapEnds([1, 2, 3, 4])", "expect": [4, 2, 3, 1]}, {"call": "swapEnds([\"a\", \"b\"])", "expect": ["b", "a"]}, {"call": "swapEnds([7])", "expect": [7]}, {"call": "(() => { const a = [1, 2, 3]; swapEnds(a); return a; })()", "expect": [1, 2, 3]}], "solution": "function swapEnds(arr) {\n  if (arr.length < 2) return [...arr];\n  const [first, ...rest] = arr;\n  const last = rest.pop();\n  return [last, ...rest, first];\n}", "explain": "The rest pattern collects the middle, pop takes the last, and the spread builds a new array so the caller's array is untouched."}]}, {"title": "Map, Set and fast lookups", "keywords": ["javascript", "js", "map", "set", "lookup", "unique", "dedupe", "frequency", "count"], "steps": [{"type": "concept", "heading": "When an object is the wrong tool", "body": "A Map is a key value store whose keys can be anything, keeps insertion order, and knows its size. A Set holds each value once. Both answer has() in constant time, which matters once lists get long.", "code": "const seen = new Set([\"a\", \"b\", \"a\"]);\nseen.size;          // 2\nconst ages = new Map([[\"ada\", 36]]);\nages.get(\"ada\");    // 36"}, {"type": "output", "prompt": "What does this print?", "code": "const s = new Set([3, 1, 3, 2, 1]);\nconsole.log([...s].join(\",\"));", "expect": "3,1,2", "explain": "A Set keeps the first time it saw each value, in that order. Duplicates are dropped, not moved."}, {"type": "mcq", "prompt": "You need to count how often each word appears, and some words are \"constructor\" or \"toString\". Which store is safest?", "options": ["A plain object {}", "A Map", "An array of pairs", "A Set"], "answer": 1, "explain": "A plain object inherits keys like toString from its prototype, so obj[\"toString\"] is already a function. A Map starts truly empty."}, {"type": "code", "prompt": "Write unique(list) that returns the items with duplicates removed, keeping the first occurrence order.", "starter": "function unique(list) {\n  return list;\n}", "tests": [{"call": "unique([1, 2, 2, 3, 1])", "expect": [1, 2, 3]}, {"call": "unique([\"b\", \"a\", \"b\"])", "expect": ["b", "a"]}, {"call": "unique([])", "expect": []}], "solution": "function unique(list) {\n  return [...new Set(list)];\n}", "explain": "Spreading a Set back into an array is the shortest correct dedupe for primitive values."}, {"type": "code", "prompt": "Write wordCounts(text) that returns an array of [word, count] pairs in first-seen order. Lowercase the text and split on spaces.", "starter": "function wordCounts(text) {\n  const counts = {};\n  return counts;\n}", "tests": [{"call": "wordCounts(\"the cat and the hat\")", "expect": [["the", 2], ["cat", 1], ["and", 1], ["hat", 1]]}, {"call": "wordCounts(\"Constructor constructor\")", "expect": [["constructor", 2]]}, {"call": "wordCounts(\"\")", "expect": []}], "solution": "function wordCounts(text) {\n  const counts = new Map();\n  for (const w of text.toLowerCase().split(\" \")) {\n    if (!w) continue;\n    counts.set(w, (counts.get(w) || 0) + 1);\n  }\n  return [...counts];\n}", "explain": "get(w) || 0 starts each new word at zero. Spreading a Map gives [key, value] pairs in insertion order."}, {"type": "order", "prompt": "Order the steps to find which ids appear in both lists in linear time.", "items": ["Put every id from the first list into a Set", "Walk the second list", "Keep an id when the Set has it", "Return the kept ids"], "explain": "Building the Set costs one pass; each has() check is constant, so the whole job is one pass over each list instead of a nested loop.", "codeItems": false}, {"type": "concept", "heading": "Pick by the question you ask", "body": "Ask \"is it in there?\" use a Set. Ask \"what goes with this key?\" use a Map. Need JSON out the door? Convert at the edge with Object.fromEntries(map) or [...set]."}]}, {"title": "Sorting without surprises", "keywords": ["javascript", "js", "sort", "sorting", "comparator", "order", "tosorted", "localecompare"], "steps": [{"type": "concept", "heading": "sort compares strings unless told otherwise", "body": "Array.prototype.sort with no argument converts items to strings and sorts by code units, so 10 lands before 9. Pass a comparator that returns a negative number, zero, or a positive number.", "code": "[10, 9, 1].sort();              // [1, 10, 9]\n[10, 9, 1].sort((a, b) => a - b); // [1, 9, 10]"}, {"type": "output", "prompt": "What does this print?", "code": "console.log([25, 100, 3].sort().join(\" \"));", "expect": "100 25 3", "explain": "Compared as strings, \"1\" is less than \"2\" which is less than \"3\", so 100 comes first."}, {"type": "mcq", "prompt": "sort changes the array it is called on. Which call returns a sorted copy and leaves the original alone?", "options": ["arr.sort()", "arr.toSorted((a, b) => a - b)", "arr.reverse()", "arr.sort().slice()"], "answer": 1, "explain": "toSorted is the non-mutating version. arr.sort().slice() still sorts arr in place first, then copies it."}, {"type": "code", "prompt": "Write byPrice(items) that returns a NEW array sorted by price ascending; equal prices keep their original order. Do not change the input.", "starter": "function byPrice(items) {\n  return items.sort();\n}", "tests": [{"call": "byPrice([{n:\"b\",price:3},{n:\"a\",price:1},{n:\"c\",price:3}]).map(i => i.n)", "expect": ["a", "b", "c"]}, {"call": "(() => { const x = [{price:2},{price:1}]; byPrice(x); return x[0].price; })()", "expect": 2}], "solution": "function byPrice(items) {\n  return [...items].sort((a, b) => a.price - b.price);\n}", "explain": "Copy first, then sort with a numeric comparator. Modern engines sort stably, so b stays ahead of c."}, {"type": "code", "prompt": "Write rank(people) that sorts by score descending, then by name A to Z for ties. Return the names.", "starter": "function rank(people) {\n  return people.map(p => p.name);\n}", "tests": [{"call": "rank([{name:\"Cy\",score:5},{name:\"Al\",score:9},{name:\"Bo\",score:5}])", "expect": ["Al", "Bo", "Cy"]}, {"call": "rank([])", "expect": []}], "solution": "function rank(people) {\n  return [...people]\n    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))\n    .map(p => p.name);\n}", "explain": "When the scores tie, b.score - a.score is 0, which is falsy, so || moves on to the name comparison."}, {"type": "order", "prompt": "Order the parts of a multi-key comparator for \"newest first, then title A to Z\".", "items": ["Compute the date difference, newer first", "If it is not zero, return it", "Otherwise compare titles with localeCompare", "Return that result"], "explain": "Each key only decides when every earlier key tied. That is all a multi-key sort is.", "codeItems": false}, {"type": "concept", "heading": "Sorting is a contract", "body": "A comparator must be consistent: if a comes before b, b must not come before a. Random comparators like () => Math.random() - 0.5 break that contract and give biased shuffles. Shuffle with Fisher-Yates instead."}]}]}, {"title": "Text, numbers, errors", "lessons": [{"title": "Strings and regular expressions", "keywords": ["javascript", "js", "strings", "regex", "regular", "expressions", "match", "replace", "validate", "parse"], "steps": [{"type": "concept", "heading": "A pattern, not a string", "body": "A regular expression describes text by shape. \\d is a digit, + means one or more, ^ and $ pin the start and end. test() asks yes or no, match() returns the pieces, and replace() rewrites what matches.", "code": "/^\\d{5}$/.test(\"60614\");          // true\n\"a1b22\".match(/\\d+/g);           // [\"1\", \"22\"]\n\"2026-10-02\".replace(/-/g, \"/\");  // \"2026/10/02\""}, {"type": "output", "prompt": "What does this print?", "code": "console.log(\"red, green,blue\".split(/,\\s*/).length);", "expect": "3", "explain": "The pattern splits on a comma followed by any amount of whitespace, so both separators count."}, {"type": "mcq", "prompt": "What does the g flag change in \"aaa\".replace(/a/g, \"b\")?", "options": ["Nothing, replace always changes every match", "It replaces every match instead of only the first", "It makes the match case-insensitive", "It makes the pattern greedy"], "answer": 1, "explain": "Without g, replace stops after the first match. The i flag is the case-insensitive one."}, {"type": "code", "prompt": "Write slugify(title) that lowercases, turns every run of characters that are not a-z or 0-9 into one hyphen, and trims hyphens from both ends.", "starter": "function slugify(title) {\n  return title.toLowerCase();\n}", "tests": [{"call": "slugify(\"Hello, World!\")", "expect": "hello-world"}, {"call": "slugify(\"  Ten  tips: CSS & JS  \")", "expect": "ten-tips-css-js"}, {"call": "slugify(\"2026 Plan\")", "expect": "2026-plan"}], "solution": "function slugify(title) {\n  return title\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \"-\")\n    .replace(/^-+|-+$/g, \"\");\n}", "explain": "One pattern collapses every run of junk into a single hyphen; a second anchored pattern trims the ends."}, {"type": "code", "prompt": "Write parseTime(s) that reads \"HH:MM\" (24 hour) and returns total minutes, or null when the text is not a valid time.", "starter": "function parseTime(s) {\n  const [h, m] = s.split(\":\");\n  return h * 60 + m;\n}", "tests": [{"call": "parseTime(\"09:30\")", "expect": 570}, {"call": "parseTime(\"23:59\")", "expect": 1439}, {"call": "parseTime(\"24:00\")", "expect": null}, {"call": "parseTime(\"9:30\")", "expect": null}, {"call": "parseTime(\"ab:cd\")", "expect": null}], "solution": "function parseTime(s) {\n  const m = /^(\\d{2}):(\\d{2})$/.exec(s);\n  if (!m) return null;\n  const h = Number(m[1]), min = Number(m[2]);\n  if (h > 23 || min > 59) return null;\n  return h * 60 + min;\n}", "explain": "Capture groups pull out the parts, the anchors reject extra text, and a range check catches values the shape alone allows."}, {"type": "order", "prompt": "Order the safe way to read structured text from a user.", "items": ["Match the whole string against an anchored pattern", "Reject it if there is no match", "Convert the captured parts to numbers", "Check the ranges", "Return the clean value"], "explain": "Shape first, then meaning. A pattern alone accepts 99:99; a range check alone accepts garbage.", "codeItems": false}, {"type": "concept", "heading": "Know when to stop", "body": "Regular expressions are good at short, regular text: ids, dates, slugs. They are bad at nested formats like HTML or JSON. Use a real parser for those (DOMParser, JSON.parse)."}]}, {"title": "Numbers that do not lie", "keywords": ["javascript", "js", "numbers", "floating", "point", "rounding", "money", "cents", "integer", "nan"], "steps": [{"type": "concept", "heading": "Floating point, in one example", "body": "JavaScript numbers are binary floating point. Most decimal fractions cannot be stored exactly, so 0.1 + 0.2 is 0.30000000000000004. That is not a bug in JavaScript; every language using IEEE 754 doubles does the same.", "code": "0.1 + 0.2 === 0.3;              // false\nMath.abs(0.1 + 0.2 - 0.3) < 1e-9; // true"}, {"type": "output", "prompt": "What does this print?", "code": "console.log(Number(\"12px\") + \" \" + parseInt(\"12px\", 10));", "expect": "NaN 12", "explain": "Number() needs the whole string to be numeric. parseInt reads digits until it hits something else."}, {"type": "mcq", "prompt": "You are adding up prices. What is the robust approach?", "options": ["Add the floats and round at every step", "Store whole cents as integers and format at the edge", "Use toFixed(2) on every value", "Use parseFloat everywhere"], "answer": 1, "explain": "Integers below 2^53 are exact. Keep money in cents while you calculate, then divide by 100 only to display."}, {"type": "code", "prompt": "Write totalCents(prices) that takes prices as strings like \"4.10\" or \"3\" and returns the total in whole cents.", "starter": "function totalCents(prices) {\n  return prices.reduce((s, p) => s + parseFloat(p), 0);\n}", "tests": [{"call": "totalCents([\"0.10\", \"0.20\"])", "expect": 30}, {"call": "totalCents([\"4.10\", \"3\", \"0.99\"])", "expect": 809}, {"call": "totalCents([])", "expect": 0}], "solution": "function totalCents(prices) {\n  return prices.reduce((s, p) => s + Math.round(parseFloat(p) * 100), 0);\n}", "explain": "Convert each price to cents once, rounding away the tiny float error, then add integers."}, {"type": "code", "prompt": "Write isValidQty(v) that returns true only for whole numbers from 1 to 99. Strings, NaN, decimals and Infinity are false.", "starter": "function isValidQty(v) {\n  return v > 0;\n}", "tests": [{"call": "isValidQty(3)", "expect": true}, {"call": "isValidQty(\"3\")", "expect": false}, {"call": "isValidQty(2.5)", "expect": false}, {"call": "isValidQty(NaN)", "expect": false}, {"call": "isValidQty(100)", "expect": false}, {"call": "isValidQty(Infinity)", "expect": false}], "solution": "function isValidQty(v) {\n  return Number.isInteger(v) && v >= 1 && v <= 99;\n}", "explain": "Number.isInteger never coerces, so the string \"3\" fails, and it already rejects NaN and Infinity."}, {"type": "order", "prompt": "Order a safe price calculation for a cart line.", "items": ["Parse the unit price into cents", "Check the quantity is a valid whole number", "Multiply cents by quantity", "Format the result for display only at the end"], "explain": "Parse and validate at the edge, calculate in integers, and format last. Formatting early turns numbers back into strings you then have to parse again.", "codeItems": false, "groups": [[0, 1]], "orderNote": "Parsing the price and checking the quantity can happen in either order."}, {"type": "concept", "heading": "NaN is contagious", "body": "Any arithmetic with NaN gives NaN, and NaN !== NaN. Check with Number.isNaN(x), not x === NaN. Validate inputs where they enter, so one bad value does not quietly poison every total downstream."}]}, {"title": "Errors on purpose", "keywords": ["javascript", "js", "errors", "throw", "try", "catch", "finally", "validation", "custom", "error"], "steps": [{"type": "concept", "heading": "Fail loudly, early, with a name", "body": "Throw when a function cannot do its job, and say why. A subclass of Error gives the caller something to check with instanceof, so it can handle a bad input differently from a crash.", "code": "class ValidationError extends Error {\n  constructor(field, msg) {\n    super(msg);\n    this.name = \"ValidationError\";\n    this.field = field;\n  }\n}"}, {"type": "output", "prompt": "What does this print?", "code": "function f() {\n  try { return \"try\"; }\n  finally { console.log(\"finally\"); }\n}\nf();", "expect": "finally", "explain": "finally runs on the way out even after a return. It is where cleanup belongs."}, {"type": "mcq", "prompt": "Which is the worst way to handle an error you cannot fix here?", "options": ["Let it propagate to a caller who can", "Wrap it with more context and rethrow", "catch (e) {} and carry on", "Log it and rethrow"], "answer": 2, "explain": "An empty catch hides the failure. The program continues with bad state and the real cause is lost."}, {"type": "code", "prompt": "Write parseAge(v) that returns a number from 0 to 150. Throw a RangeError for numbers out of range and a TypeError when v is not a finite number. Strings are not numbers here.", "starter": "function parseAge(v) {\n  return v;\n}", "tests": [{"call": "parseAge(30)", "expect": 30}, {"call": "(() => { try { parseAge(200); } catch (e) { return e.name; } })()", "expect": "RangeError"}, {"call": "(() => { try { parseAge(\"30\"); } catch (e) { return e.name; } })()", "expect": "TypeError"}, {"call": "(() => { try { parseAge(NaN); } catch (e) { return e.name; } })()", "expect": "TypeError"}], "solution": "function parseAge(v) {\n  if (typeof v !== \"number\" || !Number.isFinite(v)) throw new TypeError(\"age must be a number\");\n  if (v < 0 || v > 150) throw new RangeError(\"age out of range\");\n  return v;\n}", "explain": "Different error types let the caller react differently: a TypeError is a programming mistake, a RangeError is bad data."}, {"type": "code", "prompt": "Write safeParse(text) that returns { ok: true, value } for valid JSON and { ok: false, error } with the error message for invalid JSON. It must never throw.", "starter": "function safeParse(text) {\n  return { ok: true, value: JSON.parse(text) };\n}", "tests": [{"call": "safeParse(\"[1,2]\")", "expect": {"ok": true, "value": [1, 2]}}, {"call": "safeParse(\"{bad\").ok", "expect": false}, {"call": "typeof safeParse(\"{bad\").error", "expect": "string"}], "solution": "function safeParse(text) {\n  try {\n    return { ok: true, value: JSON.parse(text) };\n  } catch (e) {\n    return { ok: false, error: e.message };\n  }\n}", "explain": "Turning an exception into a result value is useful at boundaries such as reading a file or a network response."}, {"type": "order", "prompt": "Order a try, catch, finally block that writes a file safely.", "items": ["Open the file", "Write the data inside try", "In catch, add context and rethrow", "In finally, close the file"], "explain": "Open before try so finally only closes what was opened. finally runs whether the write worked or not.", "codeItems": false}, {"type": "concept", "heading": "Errors are part of the interface", "body": "Document what a function throws the way you document what it returns. Callers who know a function throws ValidationError can show a helpful message instead of a generic crash screen."}]}]}, {"title": "Programs with shape", "lessons": [{"title": "Classes and prototypes", "keywords": ["javascript", "js", "classes", "class", "prototype", "inheritance", "private", "getter", "methods", "oop"], "steps": [{"type": "concept", "heading": "A class is a prototype with nicer syntax", "body": "class builds a constructor function and puts methods on its prototype, so every instance shares one copy of each method. Fields marked with # are private: code outside the class body cannot read them.", "code": "class Counter {\n  #n = 0;\n  inc() { this.#n += 1; return this; }\n  get value() { return this.#n; }\n}\nnew Counter().inc().inc().value; // 2"}, {"type": "output", "prompt": "What does this print?", "code": "class A { hi() { return \"A\"; } }\nclass B extends A { hi() { return super.hi() + \"B\"; } }\nconsole.log(new B().hi());", "expect": "AB", "explain": "super.hi() calls the parent's version, then B adds to it."}, {"type": "mcq", "prompt": "Why does new Counter().inc().inc() work?", "options": ["inc is static", "inc returns this, so the next call has an object to run on", "Counters are arrays", "JavaScript chains every method"], "answer": 1, "explain": "Returning this from a method enables chaining. Without it the second .inc() would run on undefined."}, {"type": "code", "prompt": "Write a class Stack with push(x), pop() and a size getter. pop() on an empty stack returns undefined. Keep the items in a private field.", "starter": "class Stack {\n  push(x) {}\n}", "tests": [{"call": "(() => { const s = new Stack(); s.push(1); s.push(2); return [s.pop(), s.size]; })()", "expect": [2, 1]}, {"call": "new Stack().pop() === undefined", "expect": true}, {"call": "(() => { const s = new Stack(); s.push(1); return Object.keys(s).length + s.size; })()", "expect": 1}], "solution": "class Stack {\n  #items = [];\n  push(x) { this.#items.push(x); return this; }\n  pop() { return this.#items.pop(); }\n  get size() { return this.#items.length; }\n}", "explain": "The private field is invisible to Object.keys, which is the point: callers use the interface, not the internals."}, {"type": "code", "prompt": "Write class Temperature with a constructor taking celsius, a fahrenheit getter, and a fahrenheit setter that updates celsius. F = C * 9 / 5 + 32.", "starter": "class Temperature {\n  constructor(c) { this.c = c; }\n}", "tests": [{"call": "new Temperature(100).fahrenheit", "expect": 212}, {"call": "(() => { const t = new Temperature(0); t.fahrenheit = 50; return t.celsius; })()", "expect": 10}], "solution": "class Temperature {\n  constructor(celsius) { this.celsius = celsius; }\n  get fahrenheit() { return this.celsius * 9 / 5 + 32; }\n  set fahrenheit(f) { this.celsius = (f - 32) * 5 / 9; }\n}", "explain": "Getters and setters let one stored value present itself in two units without the caller noticing."}, {"type": "order", "prompt": "Order what new Stack() does.", "items": ["Create a fresh empty object", "Link it to Stack.prototype", "Set up private fields", "Run the constructor body", "Return the object"], "explain": "Linking to the prototype is why every Stack shares push and pop without copying them.", "codeItems": false}, {"type": "concept", "heading": "Prefer composition", "body": "Inheritance chains get brittle past one level. When a class needs a capability, pass in an object that has it (a logger, a store) rather than extending a class that does. That is composition, and it is easier to test."}]}, {"title": "Pure functions and modules", "keywords": ["javascript", "js", "pure", "functions", "modules", "import", "export", "side", "effects", "refactor", "testing"], "steps": [{"type": "concept", "heading": "Same input, same output, no side effects", "body": "A pure function returns a value computed only from its arguments and changes nothing outside itself. Pure functions are trivial to test and safe to reuse. Push side effects (DOM, network, storage, time, randomness) to the edges of your program."}, {"type": "mcq", "prompt": "Which function is pure?", "options": ["function now() { return Date.now(); }", "function add(a, b) { return a + b; }", "function save(x) { localStorage.setItem(\"x\", x); }", "function bump(o) { o.n++; return o; }"], "answer": 1, "explain": "Date.now changes over time, save writes to storage and bump mutates its argument. add depends only on a and b."}, {"type": "concept", "heading": "Modules keep files honest", "body": "An ES module has its own scope. Only what you export can be imported elsewhere, so helpers stay private by default. A good module file has pure logic exported and a thin layer that touches the world.", "code": "// cart.js\nexport function total(items) { /* pure */ }\n// main.js\nimport { total } from \"./cart.js\";"}, {"type": "code", "prompt": "Refactor: applyDiscount mutates the cart. Rewrite it so it returns a new cart and leaves the original unchanged. percent is a whole number like 10.", "starter": "function applyDiscount(cart, percent) {\n  cart.items.forEach(i => { i.price = i.price * (100 - percent) / 100; });\n  return cart;\n}", "tests": [{"call": "applyDiscount({ items: [{ price: 200 }] }, 10).items[0].price", "expect": 180}, {"call": "(() => { const c = { items: [{ price: 200 }] }; applyDiscount(c, 50); return c.items[0].price; })()", "expect": 200}, {"call": "(() => { const c = { id: 7, items: [] }; return applyDiscount(c, 10).id; })()", "expect": 7}], "solution": "function applyDiscount(cart, percent) {\n  return { ...cart, items: cart.items.map(i => ({ ...i, price: i.price * (100 - percent) / 100 })) };\n}", "explain": "Copy each level you change: a new cart, a new items array, a new item. Untouched fields like id ride along in the spread."}, {"type": "code", "prompt": "Write makeIdGen(prefix) that returns a function producing \"prefix-1\", \"prefix-2\" and so on. Two generators must not share a counter.", "starter": "let n = 0;\nfunction makeIdGen(prefix) {\n  return () => prefix + \"-\" + (++n);\n}", "tests": [{"call": "(() => { const a = makeIdGen(\"a\"); a(); return a(); })()", "expect": "a-2"}, {"call": "(() => { const a = makeIdGen(\"a\"); const b = makeIdGen(\"b\"); a(); a(); return b(); })()", "expect": "b-1"}], "solution": "function makeIdGen(prefix) {\n  let n = 0;\n  return () => prefix + \"-\" + (++n);\n}", "explain": "Moving the counter inside the factory gives each generator its own state instead of one shared global."}, {"type": "order", "prompt": "Order how to make a messy function testable.", "items": ["Find the side effects (DOM, fetch, storage, time)", "Move the calculation into a pure function", "Pass the values it needs in as arguments", "Call it from a thin function that does the side effects"], "explain": "This is the functional core, imperative shell pattern. The core gets unit tests; the shell stays too thin to break quietly.", "codeItems": false}]}, {"title": "Capstone: an expense ledger", "keywords": ["javascript", "js", "capstone", "project", "ledger", "csv", "parse", "report", "budget"], "steps": [{"type": "concept", "heading": "The brief", "body": "Build the logic for a small expense ledger. Input arrives as CSV text, one expense per line: date,category,amount. You will parse it safely, reject bad rows with reasons, and produce a report. This uses destructuring, Maps, sorting, regex, integer cents and errors from this course."}, {"type": "code", "prompt": "Step 1. Write parseLine(line) that returns { date, category, cents } for a valid row and throws an Error for a bad one. Trim each field and lowercase the category. Valid: date is YYYY-MM-DD, category is not empty, amount is a positive number with at most 2 decimals.", "starter": "function parseLine(line) {\n  const [date, category, amount] = line.split(\",\");\n  return { date, category, cents: amount * 100 };\n}", "tests": [{"call": "parseLine(\"2026-10-01,Food,12.50\")", "expect": {"date": "2026-10-01", "category": "food", "cents": 1250}}, {"call": "parseLine(\" 2026-10-02 , rent , 900 \").cents", "expect": 90000}, {"call": "(() => { try { parseLine(\"2026-10-01,,5\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}, {"call": "(() => { try { parseLine(\"10/01/2026,food,5\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}, {"call": "(() => { try { parseLine(\"2026-10-01,food,-5\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}, {"call": "(() => { try { parseLine(\"2026-10-01,food,1.999\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}], "solution": "function parseLine(line) {\n  const parts = line.split(\",\");\n  if (parts.length !== 3) throw new Error(\"expected 3 fields\");\n  const [date, rawCat, amount] = parts.map(p => p.trim());\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)) throw new Error(\"bad date\");\n  if (!rawCat) throw new Error(\"missing category\");\n  if (!/^\\d+(\\.\\d{1,2})?$/.test(amount) || Number(amount) <= 0) throw new Error(\"bad amount\");\n  return { date, category: rawCat.toLowerCase(), cents: Math.round(Number(amount) * 100) };\n}", "explain": "Every rule is a guard clause with a reason. Lowercasing the category now means Food and food add up together later."}, {"type": "code", "prompt": "Step 2. Write report(csv). Include your parseLine in the answer. Skip blank lines. Return { totals, rejected } where totals is an array of [category, cents] sorted by cents descending, then category A to Z, and rejected lists the 1-based line numbers that failed.", "starter": "function report(csv) {\n  return { totals: [], rejected: [] };\n}", "tests": [{"call": "report(\"2026-10-01,food,10\\n2026-10-01,rent,900\\n2026-10-02,Food,2.5\")", "expect": {"totals": [["rent", 90000], ["food", 1250]], "rejected": []}}, {"call": "report(\"2026-10-01,food,5\\nbad line\\n\\n2026-10-03,fun,5\\n2026-13,x,1\").rejected", "expect": [2, 5]}, {"call": "report(\"2026-10-01,b,5\\n2026-10-01,a,5\").totals", "expect": [["a", 500], ["b", 500]]}, {"call": "report(\"\")", "expect": {"totals": [], "rejected": []}}], "solution": "function parseLine(line) {\n  const parts = line.split(\",\");\n  if (parts.length !== 3) throw new Error(\"expected 3 fields\");\n  const [date, rawCat, amount] = parts.map(p => p.trim());\n  if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)) throw new Error(\"bad date\");\n  if (!rawCat) throw new Error(\"missing category\");\n  if (!/^\\d+(\\.\\d{1,2})?$/.test(amount) || Number(amount) <= 0) throw new Error(\"bad amount\");\n  return { date, category: rawCat.toLowerCase(), cents: Math.round(Number(amount) * 100) };\n}\nfunction report(csv) {\n  const sums = new Map();\n  const rejected = [];\n  csv.split(\"\\n\").forEach((line, i) => {\n    if (!line.trim()) return;\n    try {\n      const { category, cents } = parseLine(line);\n      sums.set(category, (sums.get(category) || 0) + cents);\n    } catch (e) {\n      rejected.push(i + 1);\n    }\n  });\n  const totals = [...sums].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));\n  return { totals, rejected };\n}", "explain": "A try/catch per line keeps one bad row from sinking the whole file, and the rejected list tells the user exactly which rows to fix."}, {"type": "mcq", "prompt": "A user uploads a 50,000 line file and one line is bad. What should the ledger do?", "options": ["Throw and show nothing", "Silently skip it", "Report everything it could parse and list the bad line number", "Guess the missing value"], "answer": 2, "explain": "Partial results plus a precise list of rejects is the most useful behavior. Silent skipping hides data loss; guessing invents it."}, {"type": "order", "prompt": "Order the ledger's pipeline.", "items": ["Split the text into lines", "Parse and validate each line", "Collect rejects with line numbers", "Sum cents per category in a Map", "Sort and return the report"], "explain": "Parse, validate, aggregate, present. Each stage only trusts what the previous stage produced.", "codeItems": false, "groups": [[2, 3]], "orderNote": "Collecting rejects and summing the good rows happen in the same pass, so either can come first."}, {"type": "concept", "heading": "What you can do now", "body": "You turned untrusted text into a correct report with integer money, clear errors and a stable sort. That pattern, parse at the edge and compute on clean data, carries into every program you write next."}]}]}]}, {"id": "js-advanced", "subject": "Advanced JavaScript", "level": "Advanced", "title": "JavaScript under the hood", "track": "code", "prereq": "js-intermediate", "rev": "2026-10-02", "unlock": {"after": "js-intermediate", "mastery": 85, "skill": "JavaScript patterns"}, "blurb": "Event loop, promise combinators, retries, higher-order functions, generators, this, immutability, recursion.", "units": [{"title": "Async for real", "lessons": [{"title": "The event loop", "keywords": ["javascript", "js", "event", "loop", "microtask", "macrotask", "settimeout", "promise", "async", "order"], "steps": [{"type": "concept", "heading": "One thread, two queues", "body": "JavaScript runs one piece of code at a time. When the current script finishes, the engine drains the microtask queue (promise callbacks, await continuations, queueMicrotask) completely, then takes ONE task from the task queue (setTimeout, events), and repeats.", "code": "console.log(\"A\");\nsetTimeout(() => console.log(\"B\"), 0);\nPromise.resolve().then(() => console.log(\"C\"));\nconsole.log(\"D\");\n// A D C B"}, {"type": "mcq", "prompt": "In the code above, why does C print before B even though the timeout is 0 ms?", "options": ["Promises are faster to create", "Microtasks run before the next task is taken from the task queue", "setTimeout(0) is rounded to 4 ms", "console.log is asynchronous"], "answer": 1, "explain": "The 0 ms timer only makes B eligible as a task. All microtasks, including C, run first."}, {"type": "output", "prompt": "What does this print?", "code": "(async () => {\n  const out = [];\n  out.push(1);\n  setTimeout(() => out.push(5), 0);\n  queueMicrotask(() => out.push(3));\n  Promise.resolve().then(() => out.push(4));\n  out.push(2);\n  await null;\n  console.log(out.join(\"\"));\n})();", "expect": "1234", "explain": "The two microtasks were queued before the await, so they run in order before the await continues. The timer is a task and has not run yet."}, {"type": "code", "prompt": "Write order() that returns a promise of an array showing the order these labels are pushed: push \"sync\" now, \"micro\" in a promise then, and \"macro\" in a setTimeout of 0. Resolve with the array once \"macro\" is pushed.", "starter": "function order() {\n  const log = [];\n  setTimeout(() => log.push(\"macro\"), 0);\n  log.push(\"sync\");\n  return Promise.resolve(log);\n}", "tests": [{"call": "order()", "expect": ["sync", "micro", "macro"]}], "solution": "function order() {\n  const log = [];\n  return new Promise(resolve => {\n    setTimeout(() => { log.push(\"macro\"); resolve(log); }, 0);\n    Promise.resolve().then(() => log.push(\"micro\"));\n    log.push(\"sync\");\n  });\n}", "explain": "Resolving from inside the timer callback waits for the task; by then the microtask already ran."}, {"type": "order", "prompt": "Order what happens after a click handler awaits fetch().", "items": ["The handler runs until the await", "The browser is free to paint and handle other events", "The response arrives and queues the continuation", "The microtask runs the rest of the handler"], "explain": "await splits a function in two. The second half is a microtask that runs only when the awaited promise settles.", "codeItems": false}, {"type": "mcq", "prompt": "A loop computes for 3 seconds on the main thread. What do users see?", "options": ["Nothing, JavaScript is async", "The page freezes: no clicks, no paint, until it ends", "Only animations stop", "The browser moves it to a thread"], "answer": 1, "explain": "Long synchronous work blocks the loop. Split it into chunks, or move it to a Web Worker."}, {"type": "concept", "heading": "Reason about time with the queues", "body": "When output order surprises you, label each line: sync, microtask or task. Run all sync code, then all microtasks, then one task, then all microtasks again. That rule predicts almost every async puzzle."}]}, {"title": "Promise combinators", "keywords": ["javascript", "js", "promise", "all", "allsettled", "race", "any", "parallel", "concurrency"], "steps": [{"type": "concept", "heading": "Four ways to wait for many", "body": "Promise.all resolves with every value or rejects on the first failure. allSettled always resolves with a status for each. race settles with whichever finishes first. any resolves with the first success and rejects only if all fail.", "code": "await Promise.all([a(), b()]);        // [ra, rb] or throws\nawait Promise.allSettled([a(), b()]); // [{status, value|reason}, ...]"}, {"type": "mcq", "prompt": "You load a dashboard from 5 independent widgets and one service is down. Which combinator keeps the other 4 visible?", "options": ["Promise.all", "Promise.allSettled", "Promise.race", "A for loop with await"], "answer": 1, "explain": "all would reject as soon as one fails. allSettled reports each result so you can render the 4 that worked and an error box for the fifth."}, {"type": "output", "prompt": "What does this print?", "code": "(async () => {\n  const p = Promise.any([Promise.reject(1), Promise.resolve(2), Promise.resolve(3)]);\n  console.log(await p);\n})();", "expect": "2", "explain": "any skips rejections and settles with the first fulfilled promise; here 2 is ready first."}, {"type": "code", "prompt": "Write settledSummary(promises) that resolves with { ok, failed }: the count of fulfilled and rejected promises.", "starter": "async function settledSummary(promises) {\n  const values = await Promise.all(promises);\n  return { ok: values.length, failed: 0 };\n}", "tests": [{"call": "settledSummary([Promise.resolve(1), Promise.reject(new Error(\"x\")), Promise.resolve(3)])", "expect": {"ok": 2, "failed": 1}}, {"call": "settledSummary([])", "expect": {"ok": 0, "failed": 0}}], "solution": "async function settledSummary(promises) {\n  const results = await Promise.allSettled(promises);\n  const ok = results.filter(r => r.status === \"fulfilled\").length;\n  return { ok, failed: results.length - ok };\n}", "explain": "allSettled never rejects, so the summary always arrives."}, {"type": "code", "prompt": "Write mapLimit(items, limit, fn) that runs the async fn on every item with at most limit calls in flight, and resolves with results in the original order.", "starter": "async function mapLimit(items, limit, fn) {\n  return Promise.all(items.map(fn));\n}", "tests": [{"call": "mapLimit([1, 2, 3, 4], 2, async x => x * 10)", "expect": [10, 20, 30, 40]}, {"call": "(async () => { let live = 0, peak = 0; await mapLimit([1,2,3,4,5,6], 2, async x => { live++; peak = Math.max(peak, live); await new Promise(r => setTimeout(r, 1)); live--; return x; }); return peak; })()", "expect": 2}, {"call": "mapLimit([], 3, async x => x)", "expect": []}], "solution": "async function mapLimit(items, limit, fn) {\n  const results = new Array(items.length);\n  let next = 0;\n  async function worker() {\n    while (next < items.length) {\n      const i = next++;\n      results[i] = await fn(items[i]);\n    }\n  }\n  const n = Math.max(1, Math.min(limit, items.length));\n  await Promise.all(Array.from({ length: n }, worker));\n  return results;\n}", "explain": "A fixed pool of workers pulls the next index from a shared counter. Writing by index keeps the order even when calls finish out of order."}, {"type": "order", "prompt": "Order a timeout wrapper built with Promise.race.", "items": ["Create a promise that rejects after ms milliseconds", "Race it against the real work", "Return whichever settles first", "Clear the timer once either side settles"], "explain": "race does not cancel the loser, so clear the timer yourself or it fires later for nothing.", "codeItems": false}, {"type": "concept", "heading": "Parallel is not free", "body": "Firing 500 requests at once can hit rate limits or exhaust memory. Batch with a limit, as mapLimit does, and treat partial failure as normal with allSettled."}]}, {"title": "Retries, timeouts and cancellation", "keywords": ["javascript", "js", "retry", "backoff", "timeout", "abort", "abortcontroller", "cancel", "resilience", "fetch"], "steps": [{"type": "concept", "heading": "Networks fail, plan for it", "body": "Real requests time out, drop, and return 503s. Resilient code retries transient failures with growing delays (exponential backoff), gives up after a limit, and can be cancelled when the user leaves. AbortController is the standard cancel button for fetch.", "code": "const ctrl = new AbortController();\nfetch(url, { signal: ctrl.signal });\nctrl.abort(); // the fetch rejects with an AbortError"}, {"type": "mcq", "prompt": "Which failure should NOT be retried automatically?", "options": ["A timeout", "A 503 Service Unavailable", "A 400 Bad Request", "A dropped connection"], "answer": 2, "explain": "A 400 means your request is wrong. Sending it again gets the same answer. Retry only failures that might succeed on another try."}, {"type": "code", "prompt": "Write retry(fn, attempts) that calls the async fn, and on failure tries again until it has made attempts calls in total. Resolve with the first success; if every call fails, reject with the last error.", "starter": "async function retry(fn, attempts) {\n  return fn();\n}", "tests": [{"call": "(async () => { let n = 0; return retry(async () => { n++; if (n < 3) throw new Error(\"x\"); return n; }, 5); })()", "expect": 3}, {"call": "(async () => { let n = 0; try { await retry(async () => { n++; throw new Error(\"e\" + n); }, 3); } catch (e) { return e.message + \" after \" + n; } })()", "expect": "e3 after 3"}], "solution": "async function retry(fn, attempts) {\n  let lastErr;\n  for (let i = 0; i < attempts; i++) {\n    try {\n      return await fn();\n    } catch (e) {\n      lastErr = e;\n    }\n  }\n  throw lastErr;\n}", "explain": "return await inside try is what makes the catch see async failures; a bare return fn() would skip it."}, {"type": "code", "prompt": "Write backoffDelays(base, n) returning the first n delays of exponential backoff capped at 30000 ms: base, 2*base, 4*base and so on.", "starter": "function backoffDelays(base, n) {\n  return Array(n).fill(base);\n}", "tests": [{"call": "backoffDelays(500, 4)", "expect": [500, 1000, 2000, 4000]}, {"call": "backoffDelays(10000, 4)", "expect": [10000, 20000, 30000, 30000]}, {"call": "backoffDelays(100, 0)", "expect": []}], "solution": "function backoffDelays(base, n) {\n  return Array.from({ length: n }, (_, i) => Math.min(30000, base * 2 ** i));\n}", "explain": "Doubling spreads retries out so a struggling server can recover. The cap stops waits from growing absurd. Production code also adds random jitter so many clients do not retry in lockstep."}, {"type": "code", "prompt": "Write withTimeout(promise, ms) that resolves or rejects like promise, but rejects with an Error whose message is \"timeout\" if ms passes first.", "starter": "function withTimeout(promise, ms) {\n  return promise;\n}", "tests": [{"call": "withTimeout(Promise.resolve(\"ok\"), 50)", "expect": "ok"}, {"call": "withTimeout(new Promise(r => setTimeout(() => r(\"late\"), 50)), 5).catch(e => e.message)", "expect": "timeout"}], "solution": "function withTimeout(promise, ms) {\n  let timer;\n  const t = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(\"timeout\")), ms); });\n  return Promise.race([promise, t]).finally(() => clearTimeout(timer));\n}", "explain": "race picks the winner; finally clears the timer either way so nothing fires after the result."}, {"type": "order", "prompt": "Order a search box that cancels stale requests.", "items": ["The user types a new character", "Abort the previous request's controller", "Create a new AbortController", "Start fetch with the new signal", "Ignore AbortError in the catch"], "explain": "Without cancellation, a slow old response can arrive after a fast new one and overwrite the right results.", "codeItems": false}]}]}, {"title": "Functions as tools", "lessons": [{"title": "Functions that build functions", "keywords": ["javascript", "js", "higher", "order", "compose", "pipe", "curry", "memoize", "partial", "functional"], "steps": [{"type": "concept", "heading": "Functions are values, use that", "body": "A higher-order function takes or returns a function. compose and pipe glue small functions into one, currying turns f(a, b) into f(a)(b) so you can pre-fill arguments, and memoize caches results of a pure function.", "code": "const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);\nconst slug = pipe(s => s.trim(), s => s.toLowerCase());"}, {"type": "output", "prompt": "What does this print?", "code": "const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);\nconst f = pipe(x => x + 1, x => x * 10);\nconsole.log(f(2));", "expect": "30", "explain": "pipe runs left to right: 2 + 1 is 3, then 3 * 10 is 30. compose would run right to left and give 21."}, {"type": "code", "prompt": "Write compose(...fns) that runs functions right to left. compose() with no functions returns the identity function.", "starter": "function compose(...fns) {\n  return x => fns[0](x);\n}", "tests": [{"call": "compose(x => x + 1, x => x * 10)(2)", "expect": 21}, {"call": "compose()(5)", "expect": 5}, {"call": "compose(s => s + \"!\", s => s.toUpperCase())(\"hi\")", "expect": "HI!"}], "solution": "function compose(...fns) {\n  return x => fns.reduceRight((v, f) => f(v), x);\n}", "explain": "reduceRight walks from the last function to the first, threading the value through."}, {"type": "code", "prompt": "Write memoize(fn) for single-argument pure functions. The returned function must call fn only once per distinct argument.", "starter": "function memoize(fn) {\n  return fn;\n}", "tests": [{"call": "(() => { let calls = 0; const sq = memoize(x => { calls++; return x * x; }); sq(4); sq(4); sq(5); return [sq(4), calls]; })()", "expect": [16, 2]}, {"call": "(() => { let calls = 0; const f = memoize(x => { calls++; return undefined; }); f(1); f(1); return calls; })()", "expect": 1}], "solution": "function memoize(fn) {\n  const cache = new Map();\n  return arg => {\n    if (!cache.has(arg)) cache.set(arg, fn(arg));\n    return cache.get(arg);\n  };\n}", "explain": "cache.has rather than a truthy check means results like 0 or undefined are cached too."}, {"type": "code", "prompt": "Write curry2(fn) that lets a two-argument function be called as f(a, b) or f(a)(b).", "starter": "function curry2(fn) {\n  return a => b => fn(a, b);\n}", "tests": [{"call": "curry2((a, b) => a - b)(10)(3)", "expect": 7}, {"call": "curry2((a, b) => a - b)(10, 3)", "expect": 7}, {"call": "[1, 2, 3].map(curry2((a, b) => a * b)(5))", "expect": [5, 10, 15]}], "solution": "function curry2(fn) {\n  return function (a, b) {\n    if (arguments.length >= 2) return fn(a, b);\n    return b2 => fn(a, b2);\n  };\n}", "explain": "Checking arguments.length makes the function flexible. In the map test, map passes extra arguments, but after pre-filling only the element reaches b2."}, {"type": "mcq", "prompt": "When is memoize a bad idea?", "options": ["For a pure function called with the same inputs often", "For a function that reads the current time", "For a slow recursive calculation", "For parsing the same config many times"], "answer": 1, "explain": "Memoizing something impure returns stale answers. The cache is only correct when the same input always gives the same output."}, {"type": "order", "prompt": "Order how memoize answers a call.", "items": ["Receive the argument", "Look it up in the cache", "On a miss, call fn and store the result", "Return the cached value"], "explain": "Every call returns from the cache; only misses pay for fn.", "codeItems": false}]}, {"title": "Iterators and generators", "keywords": ["javascript", "js", "iterator", "generator", "yield", "lazy", "iterable", "symbol", "sequence"], "steps": [{"type": "concept", "heading": "Anything can be for...of'd", "body": "An iterable has a Symbol.iterator method returning an object with next(), which hands back { value, done }. Generators (function*) write that object for you: each yield pauses the function and hands out one value.", "code": "function* count(to) {\n  for (let i = 1; i <= to; i++) yield i;\n}\n[...count(3)]; // [1, 2, 3]"}, {"type": "output", "prompt": "What does this print?", "code": "function* g() { yield \"a\"; yield \"b\"; }\nconst it = g();\nit.next();\nconsole.log(it.next().value + it.next().done);", "expect": "btrue", "explain": "The second next() returns b. The third finds the generator finished, so done is true."}, {"type": "mcq", "prompt": "Why can a generator describe an infinite sequence without freezing?", "options": ["It runs on another thread", "It only computes the next value when asked", "It stores values in a cache", "It stops after 1000 items"], "answer": 1, "explain": "Generators are lazy. Ask for 5 values and only 5 are computed."}, {"type": "code", "prompt": "Write a generator take(iterable, n) that yields at most n items from any iterable. The source may be endless, so stop reading it once you have n items.", "starter": "function* take(iterable, n) {\n  yield* iterable;\n}", "tests": [{"call": "[...take([1, 2, 3, 4], 2)]", "expect": [1, 2]}, {"call": "[...take(\"hello\", 3)]", "expect": ["h", "e", "l"]}, {"call": "[...take([1], 0)]", "expect": []}, {"call": "(() => { let pulled = 0; function* nat() { let i = 0; while (i < 1000) { pulled++; yield i++; } } const got = [...take(nat(), 4)]; return [got, pulled <= 5]; })()", "expect": [[0, 1, 2, 3], true]}], "solution": "function* take(iterable, n) {\n  if (n <= 0) return;\n  let i = 0;\n  for (const x of iterable) {\n    yield x;\n    if (++i >= n) return;\n  }\n}", "explain": "Returning after the nth item stops the loop, which also closes an infinite source cleanly."}, {"type": "code", "prompt": "Write a class Range with constructor(start, end) that is iterable: for...of yields start, start+1, up to end inclusive.", "starter": "class Range {\n  constructor(start, end) { this.start = start; this.end = end; }\n}", "tests": [{"call": "[...new Range(2, 5)]", "expect": [2, 3, 4, 5]}, {"call": "[...new Range(3, 1)]", "expect": []}, {"call": "Array.from(new Range(0, 2), x => x * 2)", "expect": [0, 2, 4]}], "solution": "class Range {\n  constructor(start, end) { this.start = start; this.end = end; }\n  *[Symbol.iterator]() {\n    for (let i = this.start; i <= this.end; i++) yield i;\n  }\n}", "explain": "A generator method under the Symbol.iterator key makes any object work with spread, for...of and Array.from."}, {"type": "order", "prompt": "Order what for (const x of thing) does.", "items": ["Call thing[Symbol.iterator]()", "Call next() on the iterator", "Stop if done is true", "Otherwise bind value to x and run the body", "Go back to next()"], "explain": "That is the whole protocol. Spread, destructuring and Array.from all use the same loop.", "codeItems": false}, {"type": "concept", "heading": "Lazy pipelines", "body": "Chain generators (map, filter, take) to process a huge file line by line without loading it all. Each value flows through the whole pipeline before the next is read."}]}, {"title": "this, bind, call and apply", "keywords": ["javascript", "js", "this", "bind", "call", "apply", "context", "arrow", "methods"], "steps": [{"type": "concept", "heading": "this is decided by the call, not the definition", "body": "In a regular function, this is whatever is left of the dot at call time: obj.f() sets this to obj. Pull the function off the object and the dot is gone, so this is undefined in strict mode. Arrow functions have no this of their own; they use the surrounding one.", "code": "const user = { name: \"Ada\", hi() { return this.name; } };\nuser.hi();        // \"Ada\"\nconst f = user.hi;\n// f() loses this"}, {"type": "mcq", "prompt": "Why does setTimeout(user.hi, 0) not see user's name?", "options": ["Timers run in another window", "The function is passed without its object, so the later call has no dot", "Arrow functions break timers", "this is always the global object"], "answer": 1, "explain": "setTimeout calls the bare function later. Use setTimeout(() => user.hi(), 0) or user.hi.bind(user)."}, {"type": "output", "prompt": "What does this print?", "code": "const o = { n: 1, f() { return [1, 2].map(() => this.n).join(\"\"); } };\nconsole.log(o.f());", "expect": "11", "explain": "The arrow callback borrows this from f, where this is o."}, {"type": "code", "prompt": "Write bindAll(obj, names) that replaces each named method with a copy bound to obj, and returns obj.", "starter": "function bindAll(obj, names) {\n  return obj;\n}", "tests": [{"call": "(() => { const o = bindAll({ v: 7, get() { return this && this.v; } }, [\"get\"]); const g = o.get; return g(); })()", "expect": 7}], "solution": "function bindAll(obj, names) {\n  for (const n of names) obj[n] = obj[n].bind(obj);\n  return obj;\n}", "explain": "bind returns a new function with this fixed, so it survives being passed around."}, {"type": "code", "prompt": "Write sumWith(obj) that calls obj.total with call() so that this inside total is obj, and the numbers 1, 2 and 3 are passed as arguments. Then write maxOf(nums) using Math.max.apply.", "starter": "function sumWith(obj) {\n  const f = obj.total;\n  return f(1, 2, 3);\n}\nfunction maxOf(nums) {\n  return Math.max(nums);\n}", "tests": [{"call": "sumWith({ base: 10, total(a, b, c) { return this.base + a + b + c; } })", "expect": 16}, {"call": "maxOf([3, 9, 2])", "expect": 9}, {"call": "maxOf([]) === -Infinity", "expect": true}], "solution": "function sumWith(obj) {\n  return obj.total.call(obj, 1, 2, 3);\n}\nfunction maxOf(nums) {\n  return Math.max.apply(null, nums);\n}", "explain": "call passes this and the arguments one by one; apply takes them as an array. Spread does the same job today, but you will meet both in older code."}, {"type": "order", "prompt": "Order how to find what this is in a regular function call.", "items": ["Is it called with new? Then this is the new object", "Is it bound with bind, call or apply? Then the given object", "Is there an object left of the dot? Then that object", "Otherwise undefined in strict code"], "explain": "Check the rules in this order; the first that applies wins. Arrow functions skip all of them and use the outer this.", "codeItems": false}]}]}, {"title": "Robust data", "lessons": [{"title": "Immutability at depth", "keywords": ["javascript", "js", "immutable", "immutability", "freeze", "structuredclone", "deep", "copy", "update", "nested"], "steps": [{"type": "concept", "heading": "Shallow copies share the inside", "body": "Spread copies one level. Nested objects are still shared, so changing copy.address.city changes the original. structuredClone makes a deep copy of plain data. Object.freeze stops changes, but only one level deep.", "code": "const a = { tags: [\"x\"] };\nconst b = { ...a };\nb.tags.push(\"y\");\na.tags; // [\"x\", \"y\"]"}, {"type": "output", "prompt": "What does this print?", "code": "const a = Object.freeze({ inner: { n: 1 } });\na.inner.n = 2;\nconsole.log(a.inner.n);", "expect": "2", "explain": "freeze is shallow. a itself cannot change, but the object stored in inner is not frozen."}, {"type": "mcq", "prompt": "Which value can structuredClone NOT copy?", "options": ["A Date", "A Map", "A function", "A nested array"], "answer": 2, "explain": "structuredClone copies data, including Dates, Maps and Sets. Functions are behavior, and it throws on them."}, {"type": "code", "prompt": "Write setIn(obj, path, value) that returns a new object with the value at the path (an array of keys) replaced, copying only the objects along the path. Missing objects on the path are created. The original must not change.", "starter": "function setIn(obj, path, value) {\n  let o = obj;\n  for (const k of path.slice(0, -1)) o = o[k];\n  o[path[path.length - 1]] = value;\n  return obj;\n}", "tests": [{"call": "setIn({ a: { b: 1, c: 2 } }, [\"a\", \"b\"], 9)", "expect": {"a": {"b": 9, "c": 2}}}, {"call": "(() => { const o = { a: { b: 1 } }; setIn(o, [\"a\", \"b\"], 9); return o.a.b; })()", "expect": 1}, {"call": "(() => { const o = { a: { b: 1 }, z: { y: 1 } }; return setIn(o, [\"a\", \"b\"], 2).z === o.z; })()", "expect": true}, {"call": "setIn({}, [\"x\", \"y\"], 1)", "expect": {"x": {"y": 1}}}], "solution": "function setIn(obj, path, value) {\n  if (path.length === 0) return value;\n  const [k, ...rest] = path;\n  const child = obj == null ? undefined : obj[k];\n  return { ...obj, [k]: setIn(child == null ? {} : child, rest, value) };\n}", "explain": "Copy the path, share the rest. That structural sharing is why immutable updates stay cheap and why z === o.z."}, {"type": "code", "prompt": "Write deepFreeze(obj) that freezes an object and every object nested inside it, then returns it. Watch out: an object may refer back to itself.", "starter": "function deepFreeze(obj) {\n  return Object.freeze(obj);\n}", "tests": [{"call": "(() => { const o = deepFreeze({ a: { b: [1] } }); return Object.isFrozen(o.a) && Object.isFrozen(o.a.b); })()", "expect": true}, {"call": "(() => { const o = deepFreeze({ a: { b: 1 } }); try { o.a.b = 2; } catch (e) {} return o.a.b; })()", "expect": 1}, {"call": "(() => { const o = { n: 1 }; o.self = o; deepFreeze(o); return Object.isFrozen(o); })()", "expect": true}], "solution": "function deepFreeze(obj) {\n  Object.freeze(obj);\n  for (const v of Object.values(obj)) {\n    if (v && typeof v === \"object\" && !Object.isFrozen(v)) deepFreeze(v);\n  }\n  return obj;\n}", "explain": "Freezing the parent first and skipping anything already frozen is what stops an object that points at itself from looping forever."}, {"type": "order", "prompt": "Order an immutable update of state.user.address.city.", "items": ["Copy state", "Copy state.user into the new state", "Copy the address into the new user", "Set city on the new address"], "explain": "Every object on the path gets a fresh copy; everything off the path is shared with the old state.", "codeItems": false}]}, {"title": "Recursion and trees", "keywords": ["javascript", "js", "recursion", "recursive", "tree", "nested", "flatten", "walk", "json", "depth"], "steps": [{"type": "concept", "heading": "A function that trusts itself", "body": "Recursion solves a problem by solving a smaller copy of it. Every recursive function needs a base case that stops, and a step that moves toward it. Trees (folders, comments, the DOM, JSON) are recursive data, so recursive code fits them.", "code": "function depth(node) {\n  if (!node.children || !node.children.length) return 1;\n  return 1 + Math.max(...node.children.map(depth));\n}"}, {"type": "output", "prompt": "What does this print?", "code": "function sum(n) { return n === 0 ? 0 : n + sum(n - 1); }\nconsole.log(sum(4));", "expect": "10", "explain": "4 + 3 + 2 + 1 + 0. The base case n === 0 stops the chain."}, {"type": "mcq", "prompt": "What happens when a recursive function has no reachable base case?", "options": ["It returns undefined", "It loops forever quietly", "It throws a RangeError: Maximum call stack size exceeded", "JavaScript optimizes it away"], "answer": 2, "explain": "Each call adds a stack frame. With no base case the stack overflows."}, {"type": "code", "prompt": "Write flatten(arr) that flattens arrays nested to any depth, without using Array.prototype.flat.", "starter": "function flatten(arr) {\n  return arr;\n}", "tests": [{"call": "flatten([1, [2, [3, [4]]], 5])", "expect": [1, 2, 3, 4, 5]}, {"call": "flatten([])", "expect": []}, {"call": "flatten([[[]]])", "expect": []}], "solution": "function flatten(arr) {\n  const out = [];\n  for (const x of arr) {\n    if (Array.isArray(x)) out.push(...flatten(x));\n    else out.push(x);\n  }\n  return out;\n}", "explain": "Base case: a non-array item is pushed as is. Recursive step: an array is flattened, then spread in."}, {"type": "code", "prompt": "Write findPaths(tree, name) that returns every path (names joined by \"/\") to a node whose name matches. Nodes look like { name, children? }. Each path starts with the root's name.", "starter": "function findPaths(tree, name) {\n  return tree.name === name ? [tree.name] : [];\n}", "tests": [{"call": "findPaths({ name: \"root\", children: [{ name: \"a\", children: [{ name: \"x\" }] }, { name: \"x\" }] }, \"x\")", "expect": ["root/a/x", "root/x"]}, {"call": "findPaths({ name: \"x\" }, \"x\")", "expect": ["x"]}, {"call": "findPaths({ name: \"r\", children: [] }, \"q\")", "expect": []}], "solution": "function findPaths(tree, name, prefix = \"\") {\n  const here = prefix ? prefix + \"/\" + tree.name : tree.name;\n  const hits = tree.name === name ? [here] : [];\n  for (const c of tree.children || []) hits.push(...findPaths(c, name, here));\n  return hits;\n}", "explain": "Carry the path so far as an argument. Each level adds its own name and asks the children."}, {"type": "order", "prompt": "Order how to write any recursive tree function.", "items": ["Decide the answer for a leaf (the base case)", "Assume the call works on each child", "Combine the children's answers with this node", "Return the combined answer"], "explain": "Trusting the recursive call on a smaller input is the leap. You only design one level.", "codeItems": false}, {"type": "concept", "heading": "Know the limit", "body": "Deep recursion (tens of thousands of levels) can overflow the stack. For very deep data, switch to an explicit stack array and a while loop. Same logic, no stack limit."}]}, {"title": "Capstone: an event-driven task queue", "keywords": ["javascript", "js", "capstone", "project", "queue", "events", "emitter", "async", "concurrency", "jobs"], "steps": [{"type": "concept", "heading": "The brief", "body": "Build a small job queue like the ones that send emails or resize images in real apps. It emits events, runs async jobs with a concurrency limit, retries failures, and reports results. You will use closures, classes, promises, retry and the event loop from this course."}, {"type": "code", "prompt": "Step 1. Write class Emitter with on(event, fn) that returns an unsubscribe function, and emit(event, ...args) that calls every listener in the order added.", "starter": "class Emitter {\n  on(event, fn) {}\n  emit(event, ...args) {}\n}", "tests": [{"call": "(() => { const e = new Emitter(); const log = []; e.on(\"x\", v => log.push(\"a\" + v)); e.on(\"x\", v => log.push(\"b\" + v)); e.emit(\"x\", 1); return log; })()", "expect": ["a1", "b1"]}, {"call": "(() => { const e = new Emitter(); let n = 0; const off = e.on(\"x\", () => n++); e.emit(\"x\"); off(); e.emit(\"x\"); return n; })()", "expect": 1}, {"call": "(() => { const e = new Emitter(); e.emit(\"nobody\"); return \"ok\"; })()", "expect": "ok"}], "solution": "class Emitter {\n  #map = new Map();\n  on(event, fn) {\n    if (!this.#map.has(event)) this.#map.set(event, []);\n    this.#map.get(event).push(fn);\n    return () => {\n      const list = this.#map.get(event);\n      const i = list.indexOf(fn);\n      if (i >= 0) list.splice(i, 1);\n    };\n  }\n  emit(event, ...args) {\n    for (const fn of [...(this.#map.get(event) || [])]) fn(...args);\n  }\n}", "explain": "Copying the list before calling lets a listener unsubscribe itself mid-emit without skipping the next one."}, {"type": "code", "prompt": "Step 2. Write class Queue with constructor(concurrency, retries). add(job) takes an async function and returns a promise of its result. At most concurrency jobs run at once. A failing job is retried up to retries more times before its promise rejects.", "starter": "class Queue {\n  constructor(concurrency, retries) {}\n  add(job) { return job(); }\n}", "tests": [{"call": "(async () => { const q = new Queue(2, 0); return Promise.all([q.add(async () => 1), q.add(async () => 2), q.add(async () => 3)]); })()", "expect": [1, 2, 3]}, {"call": "(async () => { const q = new Queue(2, 0); let live = 0, peak = 0; const job = async () => { live++; peak = Math.max(peak, live); await new Promise(r => setTimeout(r, 2)); live--; }; await Promise.all([1,2,3,4,5].map(() => q.add(job))); return peak; })()", "expect": 2}, {"call": "(async () => { const q = new Queue(1, 2); let n = 0; return q.add(async () => { n++; if (n < 3) throw new Error(\"x\"); return \"ok after \" + n; }); })()", "expect": "ok after 3"}, {"call": "(async () => { const q = new Queue(1, 1); let n = 0; try { await q.add(async () => { n++; throw new Error(\"no\"); }); } catch (e) { return e.message + n; } })()", "expect": "no2"}], "solution": "class Queue {\n  constructor(concurrency, retries = 0) {\n    this.concurrency = concurrency;\n    this.retries = retries;\n    this.running = 0;\n    this.waiting = [];\n  }\n  add(job) {\n    return new Promise((resolve, reject) => {\n      this.waiting.push({ job, resolve, reject });\n      this.#pump();\n    });\n  }\n  #pump() {\n    while (this.running < this.concurrency && this.waiting.length) {\n      const { job, resolve, reject } = this.waiting.shift();\n      this.running++;\n      this.#attempt(job, this.retries)\n        .then(resolve, reject)\n        .finally(() => { this.running--; this.#pump(); });\n    }\n  }\n  async #attempt(job, left) {\n    try {\n      return await job();\n    } catch (e) {\n      if (left > 0) return this.#attempt(job, left - 1);\n      throw e;\n    }\n  }\n}", "explain": "A waiting list plus a running count is the whole scheduler. finally frees the slot whether the job worked or not, then pumps the next one."}, {"type": "mcq", "prompt": "A job hangs forever and never settles. What happens to your queue?", "options": ["Nothing, other jobs carry on at full speed", "It permanently holds one slot; with enough hung jobs the queue stalls", "It is retried automatically", "JavaScript times it out after 30 seconds"], "answer": 1, "explain": "Nothing in the queue limits time. Real queues wrap each attempt in a timeout like withTimeout from lesson 3."}, {"type": "order", "prompt": "Order the life of one job in your queue.", "items": ["add() puts it on the waiting list", "pump() starts it when a slot is free", "A failure is retried while retries remain", "The promise from add() settles", "The slot is released and pump() runs again"], "explain": "Each stage hands off to the next through promises, so the main thread is never blocked.", "codeItems": false}, {"type": "concept", "heading": "What you can do now", "body": "You built a scheduler with backpressure, retries and events: the core of job runners, upload managers and crawlers. Add timeouts and persistence and it is production shaped."}]}]}]}, {"id": "js-expert", "subject": "JavaScript engineering", "level": "Expert", "title": "JavaScript engineering", "track": "code", "prereq": "js-advanced", "rev": "2026-10-02", "unlock": {"after": "js-advanced", "mastery": 85, "skill": "Advanced JavaScript"}, "blurb": "Complexity, graphs, dynamic programming, parsers, state machines, reactivity, testing, performance.", "units": [{"title": "Algorithms that scale", "lessons": [{"title": "Complexity you can feel", "keywords": ["javascript", "js", "big", "complexity", "performance", "algorithm", "quadratic", "linear", "time", "space"], "steps": [{"type": "concept", "heading": "Count the work, not the seconds", "body": "Big O describes how work grows with input size n. One pass is O(n). A loop inside a loop over the same data is O(n squared): 10 times the data means 100 times the work. A Map or Set lookup is about O(1), which is why it turns nested loops into one pass.", "code": "// O(n^2): for each a, scan all of b\nlist.filter(a => other.includes(a));\n// O(n): build a Set once\nconst s = new Set(other);\nlist.filter(a => s.has(a));"}, {"type": "mcq", "prompt": "An O(n squared) function takes 1 second for 1,000 items. Roughly how long for 10,000?", "options": ["2 seconds", "10 seconds", "100 seconds", "1,000 seconds"], "answer": 2, "explain": "10 times the input squared is 100 times the work. That is why quadratic code that felt fine in testing falls over in production."}, {"type": "mcq", "prompt": "What is the time complexity of arr.indexOf(x) on an unsorted array?", "options": ["O(1)", "O(log n)", "O(n)", "O(n log n)"], "answer": 2, "explain": "It may have to look at every element. A sorted array allows binary search in O(log n)."}, {"type": "code", "prompt": "Write hasPairWithSum(nums, target) that returns true if numbers at two different positions add to target. It must be O(n): 15,000 items has to finish in under 100 ms.", "starter": "function hasPairWithSum(nums, target) {\n  for (let i = 0; i < nums.length; i++)\n    for (let j = 0; j < nums.length; j++)\n      if (nums[i] + nums[j] === target) return true;\n  return false;\n}", "tests": [{"call": "hasPairWithSum([3, 8, 1, 5], 9)", "expect": true}, {"call": "hasPairWithSum([4], 8)", "expect": false}, {"call": "hasPairWithSum([4, 4], 8)", "expect": true}, {"call": "hasPairWithSum([1, 2, 3], 7)", "expect": false}, {"call": "(() => { const a = Array.from({ length: 15000 }, (_, i) => i * 2); const t0 = Date.now(); const r = hasPairWithSum(a, -1); return [r, Date.now() - t0 < 100]; })()", "expect": [false, true]}], "solution": "function hasPairWithSum(nums, target) {\n  const seen = new Set();\n  for (const n of nums) {\n    if (seen.has(target - n)) return true;\n    seen.add(n);\n  }\n  return false;\n}", "explain": "For each number, ask whether its partner was already seen. The starter also fails [4] with 8 because it pairs a position with itself."}, {"type": "code", "prompt": "Write binarySearch(sorted, x) returning the index of x or -1, in O(log n).", "starter": "function binarySearch(sorted, x) {\n  return sorted.indexOf(x);\n}", "tests": [{"call": "binarySearch([1, 3, 5, 7, 9], 7)", "expect": 3}, {"call": "binarySearch([1, 3, 5], 4)", "expect": -1}, {"call": "binarySearch([], 1)", "expect": -1}, {"call": "(() => { let reads = 0; const p = new Proxy(Array.from({ length: 100000 }, (_, i) => i), { get(t, k) { if (typeof k === \"string\" && /^\\d+$/.test(k)) reads++; return t[k]; } }); const i = binarySearch(p, 76543); return [i, reads < 60]; })()", "expect": [76543, true]}], "solution": "function binarySearch(sorted, x) {\n  let lo = 0, hi = sorted.length - 1;\n  while (lo <= hi) {\n    const mid = (lo + hi) >> 1;\n    if (sorted[mid] === x) return mid;\n    if (sorted[mid] < x) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}", "explain": "Each step halves the range. 100,000 items take about 17 comparisons; the last test counts reads to prove it."}, {"type": "order", "prompt": "Order how to fix a slow function.", "items": ["Measure with realistic data to confirm it is slow", "Find the hot loop with a profiler", "Work out its complexity", "Pick a better data structure or algorithm", "Measure again"], "explain": "Measure before and after. Guessing at the bottleneck is how people optimize the wrong thing.", "codeItems": false}]}, {"title": "Graphs and search", "keywords": ["javascript", "js", "graph", "bfs", "dfs", "shortest", "path", "topological", "sort", "dependencies"], "steps": [{"type": "concept", "heading": "Things and the links between them", "body": "A graph is nodes plus edges: routes between cities, imports between files, follows between users. Store it as an adjacency list, a map from each node to its neighbors. Breadth-first search (BFS) explores in rings and finds the fewest-edges path.", "code": "const g = { a: [\"b\", \"c\"], b: [\"d\"], c: [\"d\"], d: [] };"}, {"type": "mcq", "prompt": "Why does BFS find the shortest path in an unweighted graph?", "options": ["It tries random paths", "It visits every node at distance 1 before any at distance 2", "It always goes deepest first", "It sorts the edges"], "answer": 1, "explain": "BFS uses a queue, so nodes come out in order of distance. The first time it reaches the goal is by the fewest edges."}, {"type": "code", "prompt": "Write shortestPath(graph, from, to) returning the list of nodes on a fewest-edges path, or null. graph is an object of neighbor arrays; visit neighbors in array order.", "starter": "function shortestPath(graph, from, to) {\n  return [from, to];\n}", "tests": [{"call": "shortestPath({ a: [\"b\", \"c\"], b: [\"d\"], c: [\"e\"], e: [\"d\"], d: [] }, \"a\", \"d\")", "expect": ["a", "b", "d"]}, {"call": "shortestPath({ a: [\"b\"], b: [] }, \"b\", \"a\")", "expect": null}, {"call": "shortestPath({ a: [] }, \"a\", \"a\")", "expect": ["a"]}, {"call": "shortestPath({ a: [\"b\"], b: [\"a\", \"c\"], c: [] }, \"a\", \"c\")", "expect": ["a", "b", "c"]}], "solution": "function shortestPath(graph, from, to) {\n  const prev = new Map([[from, null]]);\n  const queue = [from];\n  while (queue.length) {\n    const n = queue.shift();\n    if (n === to) {\n      const path = [];\n      for (let c = to; c !== null; c = prev.get(c)) path.unshift(c);\n      return path;\n    }\n    for (const m of graph[n] || []) {\n      if (!prev.has(m)) { prev.set(m, n); queue.push(m); }\n    }\n  }\n  return null;\n}", "explain": "prev records how each node was first reached, which both marks it visited and lets you walk the path back."}, {"type": "code", "prompt": "Write topoSort(deps) where deps maps each task to the tasks it needs first. Return an order where every task comes after its needs, or throw an Error if there is a cycle. Visit tasks in the object's key order.", "starter": "function topoSort(deps) {\n  return Object.keys(deps);\n}", "tests": [{"call": "topoSort({ app: [\"lib\", \"ui\"], ui: [\"lib\"], lib: [] })", "expect": ["lib", "ui", "app"]}, {"call": "(() => { try { topoSort({ a: [\"b\"], b: [\"a\"] }); return \"no\"; } catch (e) { return \"cycle\"; } })()", "expect": "cycle"}, {"call": "topoSort({ x: [] })", "expect": ["x"]}], "solution": "function topoSort(deps) {\n  const out = [], state = new Map();\n  const visit = (t) => {\n    if (state.get(t) === \"done\") return;\n    if (state.get(t) === \"active\") throw new Error(\"cycle at \" + t);\n    state.set(t, \"active\");\n    for (const d of deps[t] || []) visit(d);\n    state.set(t, \"done\");\n    out.push(t);\n  };\n  Object.keys(deps).forEach(visit);\n  return out;\n}", "explain": "Depth-first, emit a task after its needs. A task still active when you meet it again means you went round in a loop."}, {"type": "order", "prompt": "Order BFS.", "items": ["Put the start node in a queue and mark it seen", "Take the next node from the front", "Stop if it is the goal", "Add its unseen neighbors to the back and mark them", "Repeat until the queue is empty"], "explain": "Marking when you enqueue, not when you dequeue, stops a node being queued twice.", "codeItems": false}, {"type": "concept", "heading": "Where you have already met graphs", "body": "npm resolving dependencies, a bundler ordering modules, a spreadsheet recalculating cells and a router matching links all run graph algorithms. Recognising the graph is most of the work."}]}, {"title": "Dynamic programming", "keywords": ["javascript", "js", "dynamic", "programming", "memoization", "tabulation", "optimization", "subproblems", "coins"], "steps": [{"type": "concept", "heading": "Solve each small problem once", "body": "Dynamic programming works when a big problem breaks into overlapping smaller ones. Top-down: write the recursion and memoize it. Bottom-up: fill a table from the smallest case upward. Both turn exponential brute force into polynomial time.", "code": "// fib(n) with a table: O(n) instead of O(2^n)\nconst f = [0, 1];\nfor (let i = 2; i <= n; i++) f[i] = f[i - 1] + f[i - 2];"}, {"type": "mcq", "prompt": "Naive recursive fib(40) makes hundreds of millions of calls. Why?", "options": ["JavaScript recursion is slow", "It recomputes the same subproblems again and again", "40 is too large for a number", "It has no base case"], "answer": 1, "explain": "fib(38) is computed twice, fib(37) three times, and so on. Caching each answer once makes it linear."}, {"type": "code", "prompt": "Write minCoins(coins, amount) returning the fewest coins that make the amount exactly, or -1 if impossible. Coins can be reused.", "starter": "function minCoins(coins, amount) {\n  let n = 0;\n  const sorted = [...coins].sort((a, b) => b - a);\n  for (const c of sorted) while (amount >= c) { amount -= c; n++; }\n  return amount === 0 ? n : -1;\n}", "tests": [{"call": "minCoins([1, 5, 10], 27)", "expect": 5}, {"call": "minCoins([1, 3, 4], 6)", "expect": 2}, {"call": "minCoins([2], 3)", "expect": -1}, {"call": "minCoins([5], 0)", "expect": 0}], "solution": "function minCoins(coins, amount) {\n  const best = new Array(amount + 1).fill(Infinity);\n  best[0] = 0;\n  for (let a = 1; a <= amount; a++) {\n    for (const c of coins) {\n      if (c <= a && best[a - c] + 1 < best[a]) best[a] = best[a - c] + 1;\n    }\n  }\n  return best[amount] === Infinity ? -1 : best[amount];\n}", "explain": "Greedy (the starter) takes 4 then 1 then 1 for 6, three coins. The table finds 3 plus 3. best[a] holds the answer for every smaller amount, built once."}, {"type": "code", "prompt": "Write lcsLength(a, b) returning the length of the longest common subsequence of two strings (characters in order, not necessarily adjacent).", "starter": "function lcsLength(a, b) {\n  let n = 0;\n  for (const ch of a) if (b.includes(ch)) n++;\n  return n;\n}", "tests": [{"call": "lcsLength(\"ABCBDAB\", \"BDCABA\")", "expect": 4}, {"call": "lcsLength(\"abc\", \"cba\")", "expect": 1}, {"call": "lcsLength(\"\", \"abc\")", "expect": 0}, {"call": "lcsLength(\"kitten\", \"sitting\")", "expect": 4}], "solution": "function lcsLength(a, b) {\n  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));\n  for (let i = 1; i <= a.length; i++) {\n    for (let j = 1; j <= b.length; j++) {\n      dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);\n    }\n  }\n  return dp[a.length][b.length];\n}", "explain": "dp[i][j] answers the problem for the first i and j characters. Diff tools are built on this idea."}, {"type": "order", "prompt": "Order the steps to design a dynamic programming solution.", "items": ["Define what one subproblem's answer means", "Write the recurrence that combines smaller answers", "Set the base cases", "Choose a fill order where smaller answers come first", "Read the final answer from the table"], "explain": "The definition is the hard part. Once dp[i] has a precise meaning, the code nearly writes itself.", "codeItems": false}, {"type": "concept", "heading": "Greedy versus exact", "body": "Greedy algorithms are fast and often right, but not always (the 1, 3, 4 coins show it). When a greedy choice can block a better total later, reach for dynamic programming."}]}]}, {"title": "Building tools", "lessons": [{"title": "A tokenizer and parser", "keywords": ["javascript", "js", "parser", "tokenizer", "lexer", "ast", "expression", "evaluate", "precedence", "grammar"], "steps": [{"type": "concept", "heading": "Text in, tree out", "body": "A tokenizer turns characters into tokens (numbers, operators, parentheses). A parser turns tokens into structure that encodes precedence: in 2 + 3 * 4 the multiply binds tighter, so it is computed first. Recursive descent writes one function per precedence level.", "code": "expr   = term (('+' | '-') term)*\nterm   = factor (('*' | '/') factor)*\nfactor = number | '(' expr ')' | '-' factor"}, {"type": "mcq", "prompt": "Why is eval(userText) the wrong way to build a calculator?", "options": ["It is slow", "It runs any JavaScript the user types, including code that steals data", "It cannot do multiplication", "It is not supported in browsers"], "answer": 1, "explain": "eval executes arbitrary code. A parser that only understands arithmetic cannot be tricked into doing anything else."}, {"type": "code", "prompt": "Write tokenize(src) returning an array of tokens: numbers as numbers (decimals allowed) and the characters + - * / ( ) as strings. Skip spaces. Throw an Error on any other character.", "starter": "function tokenize(src) {\n  return src.split(\"\");\n}", "tests": [{"call": "tokenize(\"12 + 3.5*(2-1)\")", "expect": [12, "+", 3.5, "*", "(", 2, "-", 1, ")"]}, {"call": "tokenize(\"\")", "expect": []}, {"call": "(() => { try { tokenize(\"2 ^ 3\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}], "solution": "function tokenize(src) {\n  const out = [];\n  let i = 0;\n  while (i < src.length) {\n    const ch = src[i];\n    if (ch === \" \") { i++; continue; }\n    if (\"+-*/()\".includes(ch)) { out.push(ch); i++; continue; }\n    const m = /^\\d+(\\.\\d+)?/.exec(src.slice(i));\n    if (m) { out.push(Number(m[0])); i += m[0].length; continue; }\n    throw new Error(\"unexpected \" + ch);\n  }\n  return out;\n}", "explain": "Read one token at a time. Numbers need a pattern because they span several characters."}, {"type": "code", "prompt": "Write calc(src) that evaluates + - * / with correct precedence, parentheses and unary minus. Include your tokenizer. Throw on malformed input such as \"2 +\" or \"(1\".", "starter": "function calc(src) {\n  return Number(src);\n}", "tests": [{"call": "calc(\"2 + 3 * 4\")", "expect": 14}, {"call": "calc(\"(2 + 3) * 4\")", "expect": 20}, {"call": "calc(\"10 - 4 - 3\")", "expect": 3}, {"call": "calc(\"-2 * -(1 + 1)\")", "expect": 4}, {"call": "calc(\"8 / 2 / 2\")", "expect": 2}, {"call": "(() => { try { calc(\"2 +\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}, {"call": "(() => { try { calc(\"(1\"); return \"no\"; } catch (e) { return \"threw\"; } })()", "expect": "threw"}], "solution": "function tokenize(src) {\n  const out = [];\n  let i = 0;\n  while (i < src.length) {\n    const ch = src[i];\n    if (ch === \" \") { i++; continue; }\n    if (\"+-*/()\".includes(ch)) { out.push(ch); i++; continue; }\n    const m = /^\\d+(\\.\\d+)?/.exec(src.slice(i));\n    if (m) { out.push(Number(m[0])); i += m[0].length; continue; }\n    throw new Error(\"unexpected \" + ch);\n  }\n  return out;\n}\nfunction calc(src) {\n  const t = tokenize(src);\n  let i = 0;\n  const peek = () => t[i];\n  const take = () => t[i++];\n  function expr() {\n    let v = term();\n    while (peek() === \"+\" || peek() === \"-\") v = take() === \"+\" ? v + term() : v - term();\n    return v;\n  }\n  function term() {\n    let v = factor();\n    while (peek() === \"*\" || peek() === \"/\") v = take() === \"*\" ? v * factor() : v / factor();\n    return v;\n  }\n  function factor() {\n    const tok = take();\n    if (typeof tok === \"number\") return tok;\n    if (tok === \"-\") return -factor();\n    if (tok === \"(\") {\n      const v = expr();\n      if (take() !== \")\") throw new Error(\"missing )\");\n      return v;\n    }\n    throw new Error(\"unexpected \" + tok);\n  }\n  const v = expr();\n  if (i !== t.length) throw new Error(\"extra input\");\n  return v;\n}", "explain": "One function per precedence level, and loops (not recursion) for + and - keep 10 - 4 - 3 left-associative."}, {"type": "order", "prompt": "Order the stages from source text to answer.", "items": ["Tokenize the characters", "Parse tokens by precedence", "Check that every token was used", "Return the value"], "explain": "Compilers and template engines follow the same stages, with a tree in the middle instead of a number.", "codeItems": false}, {"type": "concept", "heading": "Grammars scale", "body": "Add a level to the grammar and you add a feature: a power operator, function calls, comparisons. The same shape parses JSON, CSS selectors and programming languages."}]}, {"title": "State machines and reducers", "keywords": ["javascript", "js", "state", "machine", "reducer", "fsm", "transitions", "redux", "events", "ui"], "steps": [{"type": "concept", "heading": "Make impossible states impossible", "body": "UI bugs often come from flags that disagree: loading is true and error is set at the same time. A finite state machine allows exactly one state at a time and lists the legal transitions. A reducer is a pure function (state, event) => newState that enforces them.", "code": "const machine = {\n  idle:    { FETCH: \"loading\" },\n  loading: { OK: \"success\", FAIL: \"error\" },\n  error:   { RETRY: \"loading\" },\n  success: {}\n};"}, {"type": "mcq", "prompt": "With the machine above, what should happen when the state is success and a FETCH event arrives?", "options": ["Go to loading", "Throw", "Stay in success, the event is not allowed there", "Go to idle"], "answer": 2, "explain": "Events a state does not list are ignored. That is how a double-click cannot start a second request."}, {"type": "code", "prompt": "Write transition(machine, state, event) that returns the next state, or the same state if the event is not allowed.", "starter": "function transition(machine, state, event) {\n  return machine[state][event];\n}", "tests": [{"call": "transition({ idle: { GO: \"run\" }, run: {} }, \"idle\", \"GO\")", "expect": "run"}, {"call": "transition({ idle: { GO: \"run\" }, run: {} }, \"run\", \"GO\")", "expect": "run"}, {"call": "transition({ idle: {} }, \"idle\", \"STOP\")", "expect": "idle"}], "solution": "function transition(machine, state, event) {\n  const next = (machine[state] || {})[event];\n  return next === undefined ? state : next;\n}", "explain": "Unknown events fall through to the current state instead of producing undefined."}, {"type": "code", "prompt": "Write reducer(state, action) for a form with state { status, data, error }. SUBMIT from \"editing\" goes to \"saving\" and clears error. SAVED from \"saving\" goes to \"done\" with action.data. FAILED from \"saving\" goes back to \"editing\" with action.error. Anything else returns the same state object. Never mutate state.", "starter": "function reducer(state, action) {\n  state.status = \"saving\";\n  return state;\n}", "tests": [{"call": "reducer({ status: \"editing\", data: null, error: \"old\" }, { type: \"SUBMIT\" })", "expect": {"status": "saving", "data": null, "error": null}}, {"call": "reducer({ status: \"saving\", data: null, error: null }, { type: \"SAVED\", data: 5 }).data", "expect": 5}, {"call": "reducer({ status: \"saving\", data: null, error: null }, { type: \"FAILED\", error: \"net\" })", "expect": {"status": "editing", "data": null, "error": "net"}}, {"call": "(() => { const s = { status: \"done\", data: 1, error: null }; return reducer(s, { type: \"SUBMIT\" }) === s; })()", "expect": true}, {"call": "(() => { const s = { status: \"editing\", data: null, error: null }; reducer(s, { type: \"SUBMIT\" }); return s.status; })()", "expect": "editing"}], "solution": "function reducer(state, action) {\n  switch (state.status + \":\" + action.type) {\n    case \"editing:SUBMIT\": return { ...state, status: \"saving\", error: null };\n    case \"saving:SAVED\": return { ...state, status: \"done\", data: action.data };\n    case \"saving:FAILED\": return { ...state, status: \"editing\", error: action.error };\n    default: return state;\n  }\n}", "explain": "Switching on state plus event names every legal pair. Returning the same object when nothing changed lets UIs skip work."}, {"type": "order", "prompt": "Order how a reducer-driven UI handles a click.", "items": ["The click dispatches an action", "The reducer computes the next state", "The store saves the new state", "The view re-renders from the state"], "explain": "Data flows one way. The view never edits state directly, which is what makes bugs reproducible: replay the actions.", "codeItems": false}, {"type": "concept", "heading": "Draw it first", "body": "Before coding a tricky flow (checkout, upload, onboarding), draw the states as boxes and the events as arrows. Missing arrows are bugs you just found without running anything."}]}, {"title": "Reactive state", "keywords": ["javascript", "js", "reactive", "store", "subscribe", "observable", "signals", "derived", "computed", "state"], "steps": [{"type": "concept", "heading": "Tell me when it changes", "body": "A store holds state and notifies subscribers when it changes. Signals go further: a computed value tracks which signals it read and recomputes only when one of them changes. Most UI frameworks are built on a version of this.", "code": "const count = signal(1);\nconst double = computed(() => count.get() * 2);\ncount.set(5);\ndouble.get(); // 10"}, {"type": "mcq", "prompt": "Why should a store skip notifying subscribers when set() is called with the same value?", "options": ["To save memory", "To avoid pointless re-renders and possible update loops", "Because subscribers would throw", "It should always notify"], "answer": 1, "explain": "Notifying on no change wastes work and can trigger a subscriber that sets the value again, forever."}, {"type": "code", "prompt": "Write createStore(initial) returning { get, set, subscribe }. set(v) changes the value and calls every subscriber with the new value, unless v is identical (Object.is) to the current value. subscribe returns an unsubscribe function.", "starter": "function createStore(initial) {\n  let value = initial;\n  return { get: () => value, set: v => { value = v; }, subscribe: () => () => {} };\n}", "tests": [{"call": "(() => { const s = createStore(1); const seen = []; s.subscribe(v => seen.push(v)); s.set(2); s.set(2); s.set(3); return seen; })()", "expect": [2, 3]}, {"call": "(() => { const s = createStore(0); let n = 0; const off = s.subscribe(() => n++); s.set(1); off(); s.set(2); return [n, s.get()]; })()", "expect": [1, 2]}, {"call": "(() => { const s = createStore(NaN); let n = 0; s.subscribe(() => n++); s.set(NaN); return n; })()", "expect": 0}], "solution": "function createStore(initial) {\n  let value = initial;\n  const subs = new Set();\n  return {\n    get: () => value,\n    set(v) {\n      if (Object.is(v, value)) return;\n      value = v;\n      for (const fn of [...subs]) fn(value);\n    },\n    subscribe(fn) {\n      subs.add(fn);\n      return () => subs.delete(fn);\n    },\n  };\n}", "explain": "Object.is treats NaN as equal to itself, which === does not. A Set of subscribers makes double subscribing harmless."}, {"type": "code", "prompt": "Write signal(v) returning { get, set } and computed(fn) returning { get }. A computed caches its value and recomputes only after a signal it read has changed. Track dependencies automatically through get().", "starter": "function signal(v) {\n  return { get: () => v, set: n => { v = n; } };\n}\nfunction computed(fn) {\n  return { get: fn };\n}", "tests": [{"call": "(() => { const a = signal(2); const sq = computed(() => a.get() * a.get()); const x = sq.get(); a.set(3); return [x, sq.get()]; })()", "expect": [4, 9]}, {"call": "(() => { const a = signal(1); let runs = 0; const c = computed(() => { runs++; return a.get(); }); c.get(); c.get(); c.get(); return runs; })()", "expect": 1}, {"call": "(() => { const a = signal(1), b = signal(10); let runs = 0; const c = computed(() => { runs++; return a.get(); }); c.get(); b.set(20); c.get(); return runs; })()", "expect": 1}], "solution": "let current = null;\nfunction signal(v) {\n  const readers = new Set();\n  return {\n    get() { if (current) readers.add(current); return v; },\n    set(n) { if (Object.is(n, v)) return; v = n; for (const r of [...readers]) r.dirty = true; },\n  };\n}\nfunction computed(fn) {\n  const node = { dirty: true, value: undefined };\n  return {\n    get() {\n      if (node.dirty) {\n        const prev = current;\n        current = node;\n        try { node.value = fn(); } finally { current = prev; }\n        node.dirty = false;\n      }\n      return node.value;\n    },\n  };\n}", "explain": "A shared pointer to whatever is computing right now lets each signal record its readers. Setting a signal only marks its own readers dirty, so unrelated changes cost nothing."}, {"type": "order", "prompt": "Order what happens when a signal used by a computed changes.", "items": ["set() stores the new value", "set() marks every reader dirty", "Nothing recomputes yet", "The next get() on the computed reruns fn and caches the result"], "explain": "Lazy recomputation means a value nobody reads never costs anything.", "codeItems": false}, {"type": "output", "prompt": "What does this print?", "code": "const subs = new Set();\nconst f = () => {};\nsubs.add(f);\nsubs.add(f);\nconsole.log(subs.size);", "expect": "1", "explain": "A Set ignores a second add of the same function, which is why stores keep subscribers in one."}, {"type": "concept", "heading": "The cost of magic", "body": "Automatic tracking is convenient, but a computed that reads a signal inside a condition only tracks it on runs where that branch executes. When a reactive value seems stale, check which signals it actually read on its last run."}]}]}, {"title": "Production code", "lessons": [{"title": "Testing your own code", "keywords": ["javascript", "js", "testing", "tests", "unit", "assert", "runner", "property", "mocks", "tdd"], "steps": [{"type": "concept", "heading": "A test is a claim you can rerun", "body": "A unit test calls code with known input and asserts the output. A test runner collects tests, runs each in isolation, and reports which failed and why. Property-based tests go further: they check that a rule holds for many generated inputs, like \"sorting twice equals sorting once\"."}, {"type": "mcq", "prompt": "A test passes on your machine and fails in CI every few runs. The most likely cause?", "options": ["CI computers are broken", "The test depends on time, randomness, order or a network, so it is flaky", "The test is too short", "JavaScript is nondeterministic"], "answer": 1, "explain": "Flaky tests usually depend on something outside the code under test. Control it: fake the clock, seed the random generator, stub the network."}, {"type": "code", "prompt": "Write a tiny runner: run(tests) takes an object of name to function and resolves with { passed, failed } where failed is an array of { name, message }. A test fails if it throws or returns a rejected promise. Run tests one after another.", "starter": "async function run(tests) {\n  return { passed: Object.keys(tests).length, failed: [] };\n}", "tests": [{"call": "run({ a() {}, b() { throw new Error(\"nope\"); }, async c() {} })", "expect": {"passed": 2, "failed": [{"name": "b", "message": "nope"}]}}, {"call": "run({ async d() { throw new Error(\"later\"); } })", "expect": {"passed": 0, "failed": [{"name": "d", "message": "later"}]}}], "solution": "async function run(tests) {\n  let passed = 0;\n  const failed = [];\n  for (const [name, fn] of Object.entries(tests)) {\n    try {\n      await fn();\n      passed++;\n    } catch (e) {\n      failed.push({ name, message: e && e.message ? e.message : String(e) });\n    }\n  }\n  return { passed, failed };\n}", "explain": "await fn() handles sync and async tests the same way, and one failure never stops the rest."}, {"type": "code", "prompt": "Write checkProperty(gen, prop, runs) that calls gen(i) to make an input for each i from 0 to runs - 1 and returns the first input where prop(input) is false, or null if all pass.", "starter": "function checkProperty(gen, prop, runs) {\n  return null;\n}", "tests": [{"call": "checkProperty(i => i, n => n * 2 >= n, 50)", "expect": null}, {"call": "checkProperty(i => [i, -i], ([a, b]) => a + b === 0 && a < 10, 100)", "expect": [10, -10]}, {"call": "checkProperty(i => i * 3, n => n % 2 === 0 || n < 20, 30)", "expect": 21}], "solution": "function checkProperty(gen, prop, runs) {\n  for (let i = 0; i < runs; i++) {\n    const input = gen(i);\n    if (!prop(input)) return input;\n  }\n  return null;\n}", "explain": "Real property testing libraries add random generation and shrinking (finding the smallest failing input), but the core loop is this."}, {"type": "order", "prompt": "Order a good unit test.", "items": ["Arrange: set up the input and any fakes", "Act: call the code once", "Assert: compare the result with the expected value", "Clean up anything the test changed"], "explain": "One act per test keeps a failure pointing at one behavior.", "codeItems": false}, {"type": "mcq", "prompt": "What is the main cost of mocking everything in a unit test?", "options": ["Tests run slower", "Tests can pass while the real pieces do not fit together", "Mocks use too much memory", "Mocks cannot return values"], "answer": 1, "explain": "Heavy mocking tests your assumptions about collaborators, not the collaborators. Keep a few integration tests that use the real things."}]}, {"title": "Performance and memory", "keywords": ["javascript", "js", "performance", "debounce", "throttle", "cache", "lru", "memory", "weakmap", "leaks"], "steps": [{"type": "concept", "heading": "Do less, less often, and let go", "body": "Most front end slowness is doing work too often (a handler on every keystroke or scroll) or keeping things too long (caches that only grow, listeners never removed). Debounce waits for a pause, throttle caps the rate, an LRU cache keeps only recent entries, and a WeakMap lets its keys be garbage collected."}, {"type": "mcq", "prompt": "A search box should query the server once the user stops typing for 300 ms. Which tool?", "options": ["Throttle", "Debounce", "setInterval", "A WeakMap"], "answer": 1, "explain": "Debounce restarts its timer on every call and only fires after a quiet gap. Throttle would still fire during typing."}, {"type": "code", "prompt": "Write debounce(fn, ms) that delays fn until ms have passed with no new call, then calls it once with the latest arguments.", "starter": "function debounce(fn, ms) {\n  return (...args) => fn(...args);\n}", "tests": [{"call": "(async () => { const got = []; const d = debounce(v => got.push(v), 10); d(1); d(2); d(3); await new Promise(r => setTimeout(r, 40)); return got; })()", "expect": [3]}, {"call": "(async () => { const got = []; const d = debounce(v => got.push(v), 5); d(\"a\"); await new Promise(r => setTimeout(r, 30)); d(\"b\"); await new Promise(r => setTimeout(r, 30)); return got; })()", "expect": ["a", "b"]}], "solution": "function debounce(fn, ms) {\n  let timer;\n  return (...args) => {\n    clearTimeout(timer);\n    timer = setTimeout(() => fn(...args), ms);\n  };\n}", "explain": "Each call cancels the pending one, so only the last call in a burst survives."}, {"type": "code", "prompt": "Write class LRU(limit) with get(key) and set(key, value). When adding a key would exceed limit, evict the least recently used key. get returns undefined for a missing key and counts as a use.", "starter": "class LRU {\n  constructor(limit) { this.map = new Map(); }\n  get(k) { return this.map.get(k); }\n  set(k, v) { this.map.set(k, v); }\n}", "tests": [{"call": "(() => { const c = new LRU(2); c.set(\"a\", 1); c.set(\"b\", 2); c.get(\"a\"); c.set(\"c\", 3); return [c.get(\"a\"), c.get(\"b\"), c.get(\"c\")]; })()", "expect": [1, null, 3]}, {"call": "(() => { const c = new LRU(1); c.set(\"x\", 1); c.set(\"x\", 2); return [c.get(\"x\"), c.map.size]; })()", "expect": [2, 1]}], "solution": "class LRU {\n  constructor(limit) { this.limit = limit; this.map = new Map(); }\n  get(k) {\n    if (!this.map.has(k)) return undefined;\n    const v = this.map.get(k);\n    this.map.delete(k);\n    this.map.set(k, v);\n    return v;\n  }\n  set(k, v) {\n    if (this.map.has(k)) this.map.delete(k);\n    this.map.set(k, v);\n    if (this.map.size > this.limit) this.map.delete(this.map.keys().next().value);\n  }\n}", "explain": "A Map remembers insertion order, so delete then set moves a key to the newest end, and keys().next() is always the oldest."}, {"type": "order", "prompt": "Order how to find a memory leak in a page.", "items": ["Take a heap snapshot", "Repeat the suspect action several times", "Take another snapshot", "Compare which objects keep growing", "Find what still references them"], "explain": "Growth across repeats points at the leak; the retainer path shows the listener, cache or closure keeping it alive.", "codeItems": false}, {"type": "mcq", "prompt": "You attach extra data to DOM nodes in a Map keyed by the node. The nodes are removed from the page. What happens?", "options": ["They are collected normally", "The Map keeps them alive, a leak", "The Map throws", "The browser clears the Map"], "answer": 1, "explain": "A Map holds strong references. A WeakMap would let removed nodes be garbage collected along with their data."}]}, {"title": "Capstone: a tiny spreadsheet engine", "keywords": ["javascript", "js", "capstone", "project", "spreadsheet", "engine", "formulas", "dependencies", "cycles", "recalculate"], "steps": [{"type": "concept", "heading": "The brief", "body": "Build the core of a spreadsheet: cells hold numbers or formulas like =A1+B2*2, formulas reference other cells, results calculate in dependency order, and a cycle is reported instead of hanging. This combines your parser, graph search, topological order and caching."}, {"type": "code", "prompt": "Step 1. Write refsOf(formula) returning the unique cell references in a formula string, uppercase, in first-seen order. A reference is one or more letters followed by digits, like A1 or bc12. Anything that is not a string starting with = has none.", "starter": "function refsOf(formula) {\n  return formula.match(/[A-Z]+\\d+/g);\n}", "tests": [{"call": "refsOf(\"=A1+b2*A1\")", "expect": ["A1", "B2"]}, {"call": "refsOf(\"42\")", "expect": []}, {"call": "refsOf(\"=3*4\")", "expect": []}, {"call": "refsOf(5)", "expect": []}], "solution": "function refsOf(formula) {\n  if (typeof formula !== \"string\" || !formula.startsWith(\"=\")) return [];\n  const found = formula.slice(1).match(/[A-Za-z]+\\d+/g) || [];\n  return [...new Set(found.map(r => r.toUpperCase()))];\n}", "explain": "Normalising case and deduping now means the graph never has two nodes for one cell."}, {"type": "code", "prompt": "Step 2. Write evaluateSheet(cells) where cells maps names to numbers or formula strings. Formulas use + - * / and parentheses with numbers and cell names; empty or missing cells count as 0. Return an object with every given cell's value, using \"#CYCLE\" for any cell in a cycle or depending on one.", "starter": "function evaluateSheet(cells) {\n  return cells;\n}", "tests": [{"call": "evaluateSheet({ A1: 2, B1: \"=A1*3\", C1: \"=A1+B1\" })", "expect": {"A1": 2, "B1": 6, "C1": 8}}, {"call": "evaluateSheet({ A1: \"=B1+1\", B1: \"=A1+1\", C1: 5 })", "expect": {"A1": "#CYCLE", "B1": "#CYCLE", "C1": 5}}, {"call": "evaluateSheet({ A1: \"=Z9+4\" })", "expect": {"A1": 4}}, {"call": "evaluateSheet({ A1: \"=(1+2)*-B1\", B1: 2 })", "expect": {"A1": -6, "B1": 2}}, {"call": "evaluateSheet({ A1: \"=B1\", B1: \"=B1\", C1: \"=A1+1\" })", "expect": {"A1": "#CYCLE", "B1": "#CYCLE", "C1": "#CYCLE"}}], "solution": "function evaluateSheet(cells) {\n  const norm = {};\n  for (const [k, v] of Object.entries(cells)) norm[k.toUpperCase()] = v;\n  const out = {}, state = {};\n  function value(name) {\n    if (state[name] === \"done\") {\n      if (out[name] === \"#CYCLE\") throw new Error(\"#CYCLE\");\n      return out[name];\n    }\n    if (state[name] === \"active\") throw new Error(\"#CYCLE\");\n    state[name] = \"active\";\n    let v;\n    try {\n      const raw = norm[name];\n      if (raw === undefined || raw === \"\") v = 0;\n      else if (typeof raw === \"number\") v = raw;\n      else if (String(raw).startsWith(\"=\")) v = calc(String(raw).slice(1));\n      else v = Number(raw);\n    } catch (e) {\n      state[name] = \"done\";\n      out[name] = \"#CYCLE\";\n      throw e;\n    }\n    state[name] = \"done\";\n    out[name] = v;\n    return v;\n  }\n  function calc(src) {\n    const t = src.match(/\\d+(\\.\\d+)?|[A-Za-z]+\\d+|[-+*\\/()]/g) || [];\n    let i = 0;\n    const expr = () => { let v = term(); while (t[i] === \"+\" || t[i] === \"-\") v = t[i++] === \"+\" ? v + term() : v - term(); return v; };\n    const term = () => { let v = factor(); while (t[i] === \"*\" || t[i] === \"/\") v = t[i++] === \"*\" ? v * factor() : v / factor(); return v; };\n    const factor = () => {\n      const tok = t[i++];\n      if (tok === \"-\") return -factor();\n      if (tok === \"(\") { const v = expr(); i++; return v; }\n      if (/^[A-Za-z]/.test(tok)) return value(tok.toUpperCase());\n      return Number(tok);\n    };\n    return expr();\n  }\n  const result = {};\n  for (const name of Object.keys(norm)) {\n    try { result[name] = value(name); } catch (e) { result[name] = \"#CYCLE\"; }\n  }\n  return result;\n}", "explain": "Evaluating on demand with active and done marks is a depth-first topological order with cycle detection built in. Each cell is computed once."}, {"type": "mcq", "prompt": "A user edits A1 in a sheet of 100,000 cells. What should recalculation touch?", "options": ["Every cell, top to bottom", "Only A1", "A1 and the cells that depend on it, directly or indirectly, in dependency order", "Cells near A1 on screen"], "answer": 2, "explain": "Real engines keep the reverse graph (who depends on me) and recompute only that downstream set, in topological order."}, {"type": "order", "prompt": "Order what your engine does for one formula cell.", "items": ["Mark the cell active", "Tokenize and parse its formula", "Evaluate each referenced cell first", "Combine the values", "Mark it done and cache the result"], "explain": "Hitting an active cell during step 3 means the formula depends on itself: a cycle.", "codeItems": false}, {"type": "concept", "heading": "What you can do now", "body": "You built a parser, a dependency graph, cycle detection and caching into one working engine. Those same parts power build tools, reactive frameworks and databases. You are writing the kind of code other code runs on."}]}]}]}, {"id": "design-intermediate", "subject": "Web design in practice", "level": "Intermediate", "title": "Websites people use", "track": "web", "prereq": "site-design", "rev": "2026-10-02", "unlock": {"after": "site-design", "mastery": 55, "skill": "Website design"}, "blurb": "Spacing, readable type, contrast, heroes, navigation, forms, proof, mobile targets.", "units": [{"title": "Layout and type", "lessons": [{"title": "Spacing with a scale", "keywords": ["design", "website", "web", "ux", "spacing", "scale", "rhythm", "whitespace", "padding", "layout", "tokens"], "steps": [{"type": "concept", "heading": "Pick five numbers, use only those", "body": "Random spacing (13px here, 22px there) is the most common reason a page looks amateur. Pick a short scale, such as 4, 8, 16, 24, 32, 48 and 64 pixels, and use nothing else. Related things sit close together; unrelated groups get more space between them. That is the proximity principle doing the layout for you."}, {"type": "mcq", "prompt": "A card has 8px between its heading and text, and 8px between it and the next card. What reads wrong?", "options": ["Nothing, consistent is good", "The cards blur together because the gap between groups equals the gap inside a group", "8px is too large", "Headings need no space"], "answer": 1, "explain": "Space between groups must be larger than space inside a group, or the eye cannot tell where one group ends."}, {"type": "numeric", "prompt": "Your base unit is 8px and the scale steps are 1, 2, 3, 4 and 6 times the base. How many pixels is the step-6 space?", "answer": 48, "tolerance": 0, "explain": "6 times 8 is 48. Every space on the page is now a multiple of 8, which is why it looks deliberate.", "gen": {"vars": {"b": [4, 8, 4], "k": [3, 6, 1]}, "answer": "b*k", "round": 0, "prompt": "Your base unit is {b}px. How many pixels is a space of {k} units?", "explain": "{k} times {b} is {A}. Every space is a multiple of the base."}}, {"type": "order", "prompt": "Order these gaps from smallest to largest on a well spaced page.", "items": ["Between a label and its input", "Between paragraphs in one section", "Between a section heading and the section above it", "Between two page sections"], "explain": "Each level of grouping gets a bigger gap. The ladder of spaces is what makes structure visible without lines or boxes.", "codeItems": false}, {"type": "build", "prompt": "Add a spacing scale to your site. In your CSS, declare at least three custom properties named --space-something on :root, then wrap one part of your page in a section with class section and give it top and bottom padding of at least 32px using your scale.", "example": "<section class=\"section\">\n  <h2>Why Casa Verde</h2>\n  <p>Weeknight recipes that work the first time.</p>\n</section>\n\n/* CSS */\n:root {\n  --space-1: 8px;\n  --space-2: 16px;\n  --space-3: 24px;\n  --space-4: 32px;\n  --space-6: 48px;\n}\n.section { padding-block: var(--space-6); }\n.section h2 { margin-bottom: var(--space-2); }", "explain": "One scale, used everywhere. From now on every margin and padding you add can be a var(--space-n).", "checks": [{"cssContains": "--space-", "label": "Spacing custom properties declared in your CSS"}, {"cssContains": "var(--space-", "label": "Your CSS uses the scale with var(--space-...)"}, {"sel": "section.section", "exists": true, "label": "A section with class section"}, {"sel": "section.section", "style": "paddingTop", "label": "The section has at least 32px top padding", "minPx": 32}, {"sel": "section.section", "style": "paddingBottom", "label": "The section has at least 32px bottom padding", "minPx": 32}]}, {"type": "concept", "heading": "Whitespace is not wasted space", "body": "Generous space around the most important element makes it more noticeable, not less. When a page feels cluttered, the fix is usually to remove things and add space, not to shrink everything."}]}, {"title": "Text people can read", "keywords": ["design", "website", "web", "ux", "typography", "readability", "line", "length", "measure", "line-height", "font", "size"], "steps": [{"type": "concept", "heading": "Three numbers decide readability", "body": "Body text needs a comfortable size (16px is the usual floor on screens), a line height around 1.4 to 1.6 times the font size, and a line length of roughly 45 to 75 characters. Long lines make the eye lose its place when jumping back; tight lines make paragraphs look like a wall."}, {"type": "numeric", "prompt": "Body text is 18px with line-height 1.5. How many pixels tall is each line?", "answer": 27, "tolerance": 0, "explain": "18 times 1.5 is 27px. Unitless line-height scales with the font, which is why it is the safe choice.", "gen": {"vars": {"f": [16, 20, 1]}, "answer": "f*1.5", "round": 1, "prompt": "Body text is {f}px with line-height 1.5. How many pixels tall is each line?", "explain": "{f} times 1.5 is {A}px."}}, {"type": "mcq", "prompt": "Which CSS limits a paragraph to a readable line length whatever the screen width?", "options": ["width: 100%", "max-width: 65ch", "font-size: 2vw", "text-align: justify"], "answer": 1, "explain": "The ch unit is about the width of one character, so 65ch caps the line near 65 characters and still shrinks on narrow screens."}, {"type": "mcq", "prompt": "Why prefer a unitless line-height (1.5) over a fixed one (24px)?", "options": ["It loads faster", "It scales with each element's own font size, so headings and small text stay proportional", "Browsers ignore px line heights", "It is required for accessibility"], "answer": 1, "explain": "A fixed 24px is fine for 16px text and cramped for a 40px heading. A ratio adjusts itself."}, {"type": "build", "prompt": "Make your main reading text comfortable. Wrap your longest text in an element with class prose. Give .prose a max-width between 30em and 75ch (no wider than 760px), body text of at least 16px, and a line-height of at least 1.4.", "example": "<div class=\"prose\">\n  <p>Casa Verde started as a notebook of dinners that worked on a Tuesday...</p>\n  <p>Every recipe is tested twice before it goes up.</p>\n</div>\n\n/* CSS */\n.prose {\n  max-width: 65ch;\n  font-size: 1.125rem;\n  line-height: 1.6;\n}", "explain": "Your text now reads like a book page instead of a banner. Most of a site's value is in its text, so this is the cheapest big upgrade there is.", "checks": [{"sel": ".prose p", "exists": true, "label": "A .prose block with at least one paragraph"}, {"sel": ".prose", "style": "maxWidth", "label": "The .prose line length is capped (max-width between 240px and 760px)", "minPx": 240, "maxPx": 760, "hint": "Use max-width in ch or em, for example max-width: 65ch. A width in % or vw does not cap the line."}, {"sel": ".prose p", "style": "fontSize", "label": "Body text at least 16px", "minPx": 16}, {"sel": ".prose p", "style": "lineHeight", "label": "Line height at least 1.4 times a 16px font (22px or more)", "minPx": 22, "hint": "Set line-height: 1.5 (no unit) on .prose. The browser default is usually too tight."}]}, {"type": "order", "prompt": "Order the decisions for a page's body text.", "items": ["Choose a readable typeface at 16px or more", "Set line-height around 1.5", "Cap the line length near 65 characters", "Check it on a phone and a wide screen"], "explain": "Size first, because line height and line length both depend on it. Then check at both extremes.", "codeItems": false}, {"type": "concept", "heading": "Contrast with restraint", "body": "Two typefaces is plenty: one for headings, one for text, or one family in two weights. Hierarchy comes from size, weight and space far more than from new fonts."}]}, {"title": "Color that passes", "keywords": ["design", "website", "web", "ux", "color", "contrast", "wcag", "accessibility", "palette", "ratio", "buttons"], "steps": [{"type": "concept", "heading": "Contrast is a number, not a vibe", "body": "WCAG, the web's accessibility standard, measures text contrast as a ratio from 1:1 (invisible) to 21:1 (black on white). Level AA asks for at least 4.5:1 for normal text and 3:1 for large text (about 24px, or about 19px bold). Light gray text on white usually fails, and so do many brand colors used as button backgrounds with white text."}, {"type": "mcq", "prompt": "Your button is white text on a light orange. A contrast checker says 2.6:1. What is the fix that keeps the brand?", "options": ["Make the text bigger", "Darken the orange until white text reaches 4.5:1, or use dark text on the light orange", "Add a shadow", "Nothing, buttons are exempt"], "answer": 1, "explain": "Buttons are text and need 4.5:1 too. Darkening the shade or switching to dark text keeps the hue."}, {"type": "mcq", "prompt": "Which statement about color and meaning is right?", "options": ["Red text alone is enough to mark an error", "Color should never be the only way information is shown; add an icon or words", "Green means success in every culture", "Color-blind users see in black and white"], "answer": 1, "explain": "About 1 in 12 men has some form of color vision deficiency. Pair color with text or a symbol so nobody misses the meaning."}, {"type": "order", "prompt": "Order a quick palette check.", "items": ["Pick a text color and a background", "Measure the contrast ratio", "Adjust lightness until it reaches 4.5:1 for body text", "Repeat for buttons, links and text on images"], "explain": "Every text and background pair is its own check. One passing pair says nothing about the others.", "codeItems": false}, {"type": "build", "prompt": "Add a highlighted callout and make it pass. Add an element with class callout that has a colored background (not white) and text, and a link or button inside it with class btn-primary that has its own background color. Both must reach 4.5:1 contrast; Prexis measures the real colors in your preview.", "example": "<aside class=\"callout\">\n  <p>New this week: five dinners under 30 minutes.</p>\n  <a class=\"btn-primary\" href=\"#recipes\">See the recipes</a>\n</aside>\n\n/* CSS */\n.callout {\n  background: #fff4d6;\n  color: #3b2f00;\n  padding: var(--space-3, 24px);\n  border-radius: 8px;\n}\n.btn-primary {\n  background: #1f5f3a;\n  color: #ffffff;\n  padding: 12px 20px;\n  border-radius: 6px;\n  text-decoration: none;\n  display: inline-block;\n}", "explain": "You now measure color instead of guessing. Run the same check on every new pair you add.", "checks": [{"sel": ".callout", "exists": true, "label": "A .callout element"}, {"sel": ".callout", "style": "backgroundColor", "label": "The callout has a background color", "not": "rgba(0, 0, 0, 0)"}, {"sel": ".callout p, .callout", "contrastMin": 4.5, "label": "Callout text reaches 4.5:1", "hint": "Darken the text or lighten the background. Very pale text on a pale tint is the usual failure."}, {"sel": ".callout .btn-primary", "exists": true, "label": "A .btn-primary inside the callout"}, {"sel": ".btn-primary", "style": "backgroundColor", "label": "The primary button has its own background", "not": "rgba(0, 0, 0, 0)"}, {"sel": ".btn-primary", "contrastMin": 4.5, "label": "Every .btn-primary reaches 4.5:1", "hint": "White text needs a dark background. Try a deeper shade of your brand color."}]}, {"type": "concept", "heading": "Design the palette in roles", "body": "Name colors by job, not by hue: text, muted text, surface, accent, danger. Then a rebrand changes one value per role, and every pair you already checked stays checkable."}]}]}, {"title": "Pages with a job", "lessons": [{"title": "A hero that explains itself", "keywords": ["design", "website", "web", "ux", "hero", "headline", "homepage", "cta", "value", "proposition", "above", "fold"], "steps": [{"type": "concept", "heading": "Five seconds to answer three questions", "body": "A visitor landing on your homepage needs to know what this is, who it is for, and what to do next, fast. The hero (the first screen) answers with a specific headline, one supporting sentence, and one primary action. Clever slogans that need decoding lose people who are skimming."}, {"type": "mcq", "prompt": "Which headline works best for a recipe site?", "options": ["Welcome to Casa Verde", "Taste the difference", "Weeknight dinners that work the first time", "Innovative culinary solutions"], "answer": 2, "explain": "It says what you get and hints at who it is for. The others could belong to any site."}, {"type": "mcq", "prompt": "The hero has three equally loud buttons: Sign up, Learn more, Contact. What is the problem?", "options": ["Too few buttons", "No clear next step: when everything is primary, nothing is", "Buttons should be links", "Contact should come first"], "answer": 1, "explain": "One primary action, styled loudest. Secondary options can exist, quieter."}, {"type": "order", "prompt": "Order a hero's content from top to bottom.", "items": ["A specific headline", "One sentence that supports it", "The primary action", "A quieter secondary link or proof"], "explain": "Read order follows importance. The action comes after the reason to take it.", "codeItems": false}, {"type": "build", "prompt": "Build a hero. Add a section with class hero containing an h1 of 70 characters or fewer, a p that supports it, and exactly one link or button with class btn-primary. A secondary action is fine if it has class btn-secondary instead.", "example": "<section class=\"hero\">\n  <h1>Weeknight dinners that work the first time</h1>\n  <p>Tested recipes, 30 minutes or less, with a shopping list you can send to your phone.</p>\n  <a class=\"btn-primary\" href=\"#recipes\">Browse recipes</a>\n  <a class=\"btn-secondary\" href=\"#about\">How we test</a>\n</section>\n\n/* CSS */\n.hero { padding-block: var(--space-6, 48px); }\n.hero h1 { font-size: 2.5rem; line-height: 1.1; max-width: 20ch; }\n.btn-secondary { color: #1f5f3a; }", "explain": "A hero that answers what, who and what next. Everything else on the page now supports one clear action.", "checks": [{"sel": "section.hero", "exists": true, "label": "A section with class hero"}, {"sel": ".hero h1", "textMax": 70, "label": "A hero h1 of 70 characters or fewer", "hint": "Shorten the headline to one specific promise. Move details into the supporting sentence."}, {"sel": ".hero p", "exists": true, "label": "A supporting sentence"}, {"sel": ".hero .btn-primary", "max": 1, "min": 1, "label": "Exactly one .btn-primary in the hero", "hint": "Keep one primary action. Give any other button the class btn-secondary."}, {"sel": ".hero h1", "contrastMin": 4.5, "label": "The headline is readable against its background"}]}, {"type": "concept", "heading": "Test it on a stranger", "body": "Show the hero to someone for five seconds, hide it, and ask what the site offers and what they would click. If they cannot say, the headline is not done."}]}, {"title": "Navigation people understand", "keywords": ["design", "website", "web", "ux", "navigation", "nav", "menu", "information", "labels", "aria-current", "links"], "steps": [{"type": "concept", "heading": "Labels people would use", "body": "Navigation should use the words your visitors use, not your internal names. Keep the top menu short; a handful of clear choices is easier to scan than a dozen. Show where people are, with a visible style and aria-current=\"page\" on the current link so screen readers announce it too."}, {"type": "mcq", "prompt": "Which menu label is clearest for a bakery?", "options": ["Solutions", "Our Offerings", "Order a cake", "Explore"], "answer": 2, "explain": "It names the task people came to do. Vague labels make people click to find out what they mean."}, {"type": "mcq", "prompt": "What does aria-current=\"page\" do?", "options": ["Bolds the link", "Tells assistive technology which link is the page you are on", "Makes the link open in a new tab", "Hides the link"], "answer": 1, "explain": "It adds meaning, not looks. Style it with a selector like [aria-current=\"page\"] so sighted users see the same thing."}, {"type": "order", "prompt": "Order how to design a site's navigation.", "items": ["List the tasks visitors come to do", "Group them and name each group in visitors' words", "Keep the top level to a few items", "Mark the current page clearly"], "explain": "Tasks first, then labels. Menus designed from the org chart mirror the company, not the visitor.", "codeItems": false}, {"type": "build", "prompt": "Tidy your navigation. Your nav needs between 2 and 7 links, one of them marked aria-current=\"page\", and a CSS rule that styles [aria-current] so the current page is visible.", "example": "<nav aria-label=\"Main\">\n  <a href=\"index.html\" aria-current=\"page\">Recipes</a>\n  <a href=\"plans.html\">Meal plans</a>\n  <a href=\"about.html\">How we test</a>\n</nav>\n\n/* CSS */\nnav a[aria-current=\"page\"] {\n  font-weight: 700;\n  text-decoration: underline;\n  text-underline-offset: 4px;\n}", "explain": "A short, plainly labeled menu that says where you are. That alone fixes a large share of the \"I couldn't find it\" complaints sites get.", "checks": [{"sel": "nav", "exists": true, "label": "A nav element"}, {"sel": "nav a", "max": 7, "min": 2, "label": "Between 2 and 7 links in your nav", "hint": "Move rarer links into the footer. The top menu is for the main tasks."}, {"sel": "nav a[aria-current=\"page\"]", "exists": true, "label": "One nav link marked aria-current=\"page\""}, {"cssContains": "aria-current", "label": "A CSS rule styles the current link"}]}, {"type": "concept", "heading": "Footers are navigation too", "body": "People who reach the bottom are looking for something: contact, policies, the full list of pages. A tidy footer catches them. It is the right home for links that are important but not frequent."}]}, {"title": "Forms people finish", "keywords": ["design", "website", "web", "ux", "forms", "inputs", "labels", "autocomplete", "validation", "signup", "fields"], "steps": [{"type": "concept", "heading": "Every field costs you people", "body": "Each extra field is another reason to quit. Ask only for what you need now. Give every input a visible label (placeholders vanish as you type), the right type so phones show the right keyboard, and autocomplete so browsers can fill it in."}, {"type": "mcq", "prompt": "Why is placeholder text a poor replacement for a label?", "options": ["It is too small", "It disappears as soon as you type, so people forget what the field was for, and many screen readers treat it inconsistently", "It cannot be styled", "It is not valid HTML"], "answer": 1, "explain": "A real label stays visible and is announced reliably. Use the placeholder for an example at most."}, {"type": "mcq", "prompt": "Which input gives phone users the right keyboard for an email address?", "options": ["<input type=\"text\">", "<input type=\"email\">", "<input type=\"string\">", "<input inputmode=\"none\">"], "answer": 1, "explain": "type=\"email\" brings up a keyboard with @ and validates the basic shape for free."}, {"type": "order", "prompt": "Order a good error experience when a field is wrong.", "items": ["Let the person finish typing", "Check the value when they leave the field or submit", "Show a specific message next to the field", "Keep everything they already typed"], "explain": "Do not shout while people are still typing, and never wipe the form. Say what is wrong and how to fix it.", "codeItems": false}, {"type": "build", "prompt": "Build a short signup form. Add a form with class signup containing an email input with a label whose for matches the input id, type=\"email\", autocomplete=\"email\" and required, and a button with type=\"submit\". Keep it to 3 inputs or fewer.", "example": "<form class=\"signup\">\n  <label for=\"signup-email\">Email</label>\n  <input id=\"signup-email\" name=\"email\" type=\"email\" autocomplete=\"email\" required>\n  <button type=\"submit\" class=\"btn-primary\">Get the weekly recipes</button>\n</form>\n\n/* CSS */\n.signup { display: grid; gap: var(--space-1, 8px); max-width: 28rem; }\n.signup input { font-size: 1rem; padding: 10px 12px; }", "explain": "One field, one clear button, a label that stays, and a browser that can fill it in. That is about as short as a form gets.", "checks": [{"sel": "form.signup", "exists": true, "label": "A form with class signup"}, {"sel": "form.signup input[type=\"email\"][autocomplete=\"email\"][required]", "exists": true, "label": "An email input with type, autocomplete and required"}, {"sel": "form.signup label[for]", "exists": true, "label": "A label with a for attribute"}, {"htmlMatch": "for=\"([\\w-]+)\"[\\s\\S]*id=\"\\1\"|id=\"([\\w-]+)\"[\\s\\S]*for=\"\\2\"", "label": "The label's for matches an input's id", "hint": "Give the input an id, for example id=\"signup-email\", and put the same value in the label's for attribute."}, {"sel": "form.signup button[type=\"submit\"]", "exists": true, "label": "A submit button"}, {"sel": "form.signup input", "max": 3, "min": 1, "label": "Three inputs or fewer"}]}, {"type": "concept", "heading": "Say what happens next", "body": "The button text should finish the sentence \"I want to...\": \"Get the weekly recipes\" beats \"Submit\". After submitting, confirm what happened and when to expect the next step."}]}]}, {"title": "Trust and touch", "lessons": [{"title": "Proof people believe", "keywords": ["design", "website", "web", "ux", "trust", "testimonials", "social", "proof", "reviews", "credibility", "quotes"], "steps": [{"type": "concept", "heading": "Specific beats glowing", "body": "\"Great service!\" persuades nobody. A testimonial works when it is specific (what problem, what result), attributed (a real name and context), and placed next to the claim it supports. Logos, numbers and guarantees work the same way: concrete and checkable."}, {"type": "mcq", "prompt": "Which testimonial is most convincing?", "options": ["\"Amazing! Five stars!\" (Anonymous)", "\"Best site ever.\" (J.)", "\"I cook three of these a week now. The shopping list alone saves me a trip.\" (Priya N., nurse, Leeds)", "\"We are the leading recipe platform.\" (Casa Verde team)"], "answer": 2, "explain": "It is specific, sounds like a person, and has a name and context. The last one is a claim, not proof."}, {"type": "mcq", "prompt": "Where should a testimonial about speed go?", "options": ["In the footer", "On a separate testimonials page", "Next to the claim that the recipes take 30 minutes", "In a pop-up"], "answer": 2, "explain": "Proof works at the moment of doubt, right next to the claim it backs up."}, {"type": "order", "prompt": "Order how to collect a usable testimonial.", "items": ["Ask a real user after they got a result", "Ask what they were struggling with before", "Ask what changed", "Get permission to use their name and context"], "explain": "Asking about before and after produces specifics. Permission makes it honest and usable.", "codeItems": false}, {"type": "build", "prompt": "Add a testimonial. Use a figure with class testimonial containing a blockquote of at least 60 characters and a figcaption with the person's name.", "example": "<figure class=\"testimonial\">\n  <blockquote>I cook three of these a week now. The shopping list alone saves me a trip to the store.</blockquote>\n  <figcaption>Priya N., nurse, Leeds</figcaption>\n</figure>\n\n/* CSS */\n.testimonial { margin: 0; padding: var(--space-3, 24px); border-left: 4px solid #1f5f3a; }\n.testimonial blockquote { margin: 0 0 var(--space-1, 8px); font-size: 1.125rem; }", "explain": "The right elements (figure, blockquote, figcaption) tie the quote to its source for every reader, including screen readers.", "checks": [{"sel": "figure.testimonial blockquote", "exists": true, "label": "A figure.testimonial with a blockquote"}, {"sel": "figure.testimonial blockquote", "textMin": 60, "label": "The quote is specific (60 characters or more)"}, {"sel": "figure.testimonial figcaption", "exists": true, "label": "A figcaption naming the person"}, {"sel": "figure.testimonial blockquote", "contrastMin": 4.5, "label": "The quote is readable"}]}, {"type": "concept", "heading": "Never invent proof", "body": "Made-up reviews are dishonest and in many places illegal under consumer protection law. If you have no testimonials yet, use what is true: how you test, a guarantee, or a free sample."}]}, {"title": "Thumbs, not cursors", "keywords": ["design", "website", "web", "ux", "mobile", "touch", "tap", "targets", "responsive", "thumb", "phone"], "steps": [{"type": "concept", "heading": "Design for the thumb", "body": "On phones, people tap with a thumb, not a precise cursor. WCAG 2.2 asks for targets of at least 24 by 24 CSS pixels (level AA) and recommends 44 by 44 (level AAA), which matches long-standing platform guidance from Apple. Keep tappable things apart so a near miss does not hit the neighbor."}, {"type": "mcq", "prompt": "Two 30px icons sit 2px apart. What is the risk?", "options": ["None, 30px is big enough", "Misses hit the neighbor; size and spacing both matter", "Icons cannot be tapped", "They will overflow"], "answer": 1, "explain": "Even passable sizes fail if targets touch. Give them space or merge them into a bigger control."}, {"type": "numeric", "prompt": "A button's text is 20px tall and it has 12px padding top and bottom. How tall is the tap target in px?", "answer": 44, "tolerance": 0, "explain": "20 + 12 + 12 = 44px, right at the comfortable size. Padding is the easy way to grow a target without growing the text.", "gen": {"vars": {"t": [16, 24, 2], "p": [8, 16, 2]}, "answer": "t+2*p", "round": 0, "prompt": "A button's text is {t}px tall with {p}px padding top and bottom. How tall is the tap target in px?", "explain": "{t} + {p} + {p} = {A}px."}}, {"type": "order", "prompt": "Order a quick mobile check of a page.", "items": ["Open it at phone width", "Try every button and link with a thumb", "Look for text you must zoom to read", "Check nothing scrolls sideways"], "explain": "Real thumbs on a real phone find problems a desktop resize misses.", "codeItems": false}, {"type": "build", "prompt": "Make your primary buttons thumb sized. Give every .btn-primary display: inline-block (or block, flex or inline-flex) and a min-height of at least 44px, and add a @media rule for narrow screens.", "example": "/* CSS */\n.btn-primary {\n  display: inline-flex;\n  align-items: center;\n  min-height: 44px;\n  padding: 0 20px;\n}\n@media (max-width: 600px) {\n  .btn-primary { width: 100%; justify-content: center; }\n}", "explain": "Your main action is now easy to hit with a thumb, and it stretches full width on phones where that helps.", "checks": [{"sel": ".btn-primary", "exists": true, "label": "A .btn-primary on the page"}, {"sel": ".btn-primary", "style": "minHeight", "label": "Every .btn-primary is at least 44px tall (min-height)", "every": true, "minPx": 44, "hint": "Inline links ignore height. Add display: inline-flex or inline-block, then min-height: 44px."}, {"sel": ".btn-primary", "style": "display", "label": "No .btn-primary is display: inline", "every": true, "not": "inline", "hint": "A link is inline by default, so its height is ignored. Give .btn-primary display: inline-flex or inline-block."}, {"cssContains": "@media", "label": "A @media rule for narrow screens"}]}, {"type": "concept", "heading": "Reachability", "body": "The bottom of a phone screen is easier to reach than the top corners. Apps put key actions in bottom bars for this reason. On a long page, repeat the primary action near the bottom so nobody scrolls back up to act."}]}, {"title": "Capstone: a landing page that works", "keywords": ["design", "website", "web", "ux", "capstone", "landing", "page", "conversion", "redesign", "project"], "steps": [{"type": "concept", "heading": "The brief", "body": "Turn your site into a landing page that would survive a real launch. Everything here comes from this course: a hero with one action, benefits people can scan, proof, a short form, readable text, passing contrast and thumb sized targets."}, {"type": "mcq", "prompt": "You have room for one more element above the form. Which helps most?", "options": ["An animated background", "A specific testimonial that answers the main doubt", "A second headline", "Social media icons"], "answer": 1, "explain": "Proof at the point of decision removes the last reason to hesitate."}, {"type": "order", "prompt": "Order the sections of a classic landing page.", "items": ["Hero with the main promise and action", "Benefits that back the promise", "Proof from real people", "The form or final action"], "explain": "Promise, reasons, proof, action. Each section answers the doubt the previous one raised.", "codeItems": false}, {"type": "build", "prompt": "Assemble the landing page. It needs: a .hero with a short h1 and one .btn-primary; a section with class benefits holding at least three items with class benefit, each with an h3; a figure.testimonial; your form.signup; a .prose block; and contrast and size that pass.", "example": "<section class=\"benefits\">\n  <div class=\"benefit\"><h3>30 minutes or less</h3><p>Every recipe is timed by a tester.</p></div>\n  <div class=\"benefit\"><h3>One shopping list</h3><p>Send it to your phone in one tap.</p></div>\n  <div class=\"benefit\"><h3>Tested twice</h3><p>Two cooks, two kitchens, before it goes up.</p></div>\n</section>\n\n/* CSS */\n.benefits { display: grid; gap: var(--space-3, 24px); grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); }", "explain": "A complete, honest landing page: clear promise, scannable reasons, real proof, an easy action, and text everyone can read.", "checks": [{"sel": ".hero h1", "textMax": 70, "label": "Hero headline of 70 characters or fewer"}, {"sel": ".hero .btn-primary", "max": 1, "min": 1, "label": "One primary action in the hero"}, {"sel": ".benefits .benefit h3", "count": 3, "label": "Three or more benefits, each with an h3"}, {"sel": "figure.testimonial figcaption", "exists": true, "label": "A testimonial with a named source"}, {"sel": "form.signup input[type=\"email\"][required]", "exists": true, "label": "The signup form"}, {"sel": ".prose", "style": "maxWidth", "label": "Readable line length in .prose", "minPx": 240, "maxPx": 760}, {"sel": ".btn-primary", "contrastMin": 4.5, "label": "Primary buttons pass 4.5:1"}, {"sel": ".btn-primary", "style": "minHeight", "label": "Every primary button is at least 44px tall", "every": true, "minPx": 44}]}, {"type": "write", "prompt": "Write the one-sentence brief you would give a designer for this page: who it is for, what it promises, and the one action you want.", "checks": [{"words": [12, 45], "label": "Between 12 and 45 words"}, {"has": "\\bfor\\b", "flags": "i", "label": "Says who it is for (use the word for)"}, {"has": "\\b(sign ?up|join|buy|book|subscribe|order|download|start|get|browse|try)\\b", "flags": "i", "label": "Names the one action"}, {"confirm": true, "label": "A stranger could tell what this page is for from this sentence alone"}], "example": "A landing page for busy parents who cook on weeknights, promising tested 30-minute dinners, with one action: sign up for the weekly recipe email.", "explain": "A one-sentence brief keeps every later decision honest: anything that does not serve the audience, the promise or the action can go."}, {"type": "concept", "heading": "What you can do now", "body": "You can take a page from vague to working: hierarchy, readable type, measured contrast, clear navigation, a short form, believable proof and mobile-ready targets. That is the craft most sites skip."}]}]}]}, {"id": "design-advanced", "subject": "UX and conversion", "level": "Advanced", "title": "Design with evidence", "track": "web", "prereq": "design-intermediate", "rev": "2026-10-02", "unlock": {"after": "design-intermediate", "mastery": 85, "skill": "Web design in practice"}, "blurb": "Interviews, usability tests, funnels, A/B tests, information architecture, accessible design, component states.", "units": [{"title": "Learn from people", "lessons": [{"title": "Interviews that do not lead", "keywords": ["design", "website", "web", "ux", "research", "interviews", "users", "questions", "discovery", "bias"], "steps": [{"type": "concept", "heading": "Ask about the past, not the future", "body": "People are poor at predicting what they would do and good at describing what they did. Ask about the last time something happened (\"Tell me about the last time you planned dinner\"), not hypotheticals (\"Would you use an app that...?\"). Avoid questions that suggest the answer you want."}, {"type": "mcq", "prompt": "Which question is leading?", "options": ["Tell me about the last time you cooked on a weeknight.", "What was hard about it?", "Don't you think a shopping list feature would be useful?", "What did you do next?"], "answer": 2, "explain": "It suggests the answer and asks for an opinion about your idea. People are polite and will say yes."}, {"type": "mcq", "prompt": "A participant says \"I would definitely pay for that.\" How much weight should that get?", "options": ["A lot, they said definitely", "Little; stated future intent is a weak signal compared with what people already do and pay for", "None, never listen to users", "It proves the market"], "answer": 1, "explain": "Past behavior (what they already spend time or money on) is far stronger evidence than a polite prediction."}, {"type": "order", "prompt": "Order a good interview.", "items": ["Explain the purpose and that there are no wrong answers", "Ask about a recent real example", "Follow up with why and what happened next", "Ask what they tried before", "Thank them and note quotes right away"], "explain": "Warm up, go concrete, dig, then capture. Notes written an hour later lose the exact words that matter.", "codeItems": false}, {"type": "write", "prompt": "Rewrite these leading questions into neutral ones about past behavior. Keep one question per line.", "checks": [{"lines": 3, "label": "Three questions, one per line"}, {"changed": true, "label": "You rewrote the draft, not just the same text"}, {"not": "\\b(would you|don't you|wouldn't you|do you like|isn't it|love)\\b", "flags": "i", "label": "No hypothetical or leading phrases (would you, don't you, love...)"}, {"has": "\\b(last time|recently|tell me about|walk me through|what happened)\\b", "flags": "i", "label": "At least one question anchors on a real past event"}], "example": "Tell me about the last time you planned a weeknight dinner.\nWhat was the hardest part of that?\nWhat have you tried to make it easier?", "explain": "Neutral questions about real events get stories, and stories show the problems worth solving.", "starter": "Would you use an app that plans your dinners?\nDon't you hate grocery shopping?\nWould you love a feature that sends a shopping list to your phone?"}, {"type": "concept", "heading": "Synthesize, then decide", "body": "After five or six interviews, write each observation on its own note and group them. Patterns that show up across several people are findings; a single vivid story is an anecdote to check."}]}, {"title": "Usability tests on a budget", "keywords": ["design", "website", "web", "ux", "usability", "testing", "tasks", "success", "rate", "observation", "think", "aloud"], "steps": [{"type": "concept", "heading": "Watch, do not ask", "body": "In a usability test you give someone a realistic task, ask them to think aloud, and watch where they hesitate. A widely cited heuristic from Nielsen Norman Group is that about five participants per round reveals most of the big problems; several small rounds with fixes in between beat one large study."}, {"type": "mcq", "prompt": "Which task scenario is best?", "options": ["Click the Meal plans link", "Find the meal plans page", "You have 20 minutes and chicken in the fridge. Find something to cook tonight.", "Rate our navigation from 1 to 5"], "answer": 2, "explain": "It sets a real goal without naming the link. The first two give away the answer in the words they use."}, {"type": "numeric", "prompt": "7 of 10 participants completed the checkout task. What is the task success rate in percent?", "answer": 70, "tolerance": 0, "explain": "7 divided by 10 is 70%. With small samples, treat this as a direction, not a precise number.", "gen": {"vars": {"s": [2, 9, 1]}, "answer": "s*10", "round": 0, "prompt": "{s} of 10 participants completed the task. What is the success rate in percent?", "explain": "{s} divided by 10 is {A}%."}}, {"type": "mcq", "prompt": "A participant is stuck for a minute. What should the facilitator do?", "options": ["Point to the right button", "Ask \"What are you looking for?\" and let them keep trying", "End the test", "Explain how the site works"], "answer": 1, "explain": "Helping hides the problem you came to find. Prompt them to think aloud; step in only if they are truly stuck and note where."}, {"type": "order", "prompt": "Order a small usability round.", "items": ["Write 3 to 5 realistic tasks", "Recruit about five people who match your visitors", "Run sessions and note where people struggle", "Rank problems by how many hit them and how badly", "Fix the worst and test again"], "explain": "Test, fix, retest. The second round tells you whether the fix worked.", "codeItems": false}, {"type": "write", "prompt": "Write two task scenarios for testing your landing page. Each should give a goal and context but must not use the words on your buttons or links.", "checks": [{"lines": 2, "label": "Two scenarios, one per line"}, {"words": [20, 90], "label": "Between 20 and 90 words"}, {"not": "\\b(click|tap|press|button|link|menu)\\b", "flags": "i", "label": "No interface words (click, button, link, menu)"}, {"confirm": true, "label": "Neither scenario uses the exact label of the thing you want them to find"}], "example": "You want easy dinners this week and you are happy to get an email about them. Set that up.\nYou have chicken and rice at home and 25 minutes. Find something to cook tonight.", "explain": "Scenarios that describe goals let you see whether people can find the path, instead of whether they can match words."}]}, {"title": "Funnels and the numbers behind them", "keywords": ["design", "website", "web", "ux", "analytics", "funnel", "conversion", "rate", "drop-off", "events", "metrics"], "steps": [{"type": "concept", "heading": "A funnel shows where people leave", "body": "A funnel lists the steps to a goal (visit, view recipe, sign up) and how many people reach each. The biggest drop between two steps is usually the best place to look first. Rates are counts divided by the step before (step conversion) or by the first step (overall conversion)."}, {"type": "numeric", "prompt": "2,000 people visit, 500 open a recipe, 50 sign up. What is the overall conversion rate from visit to sign up, in percent?", "answer": 2.5, "tolerance": 0.01, "explain": "50 divided by 2,000 is 0.025, or 2.5%.", "gen": {"vars": {"v": [1000, 5000, 1000], "s": [20, 100, 10]}, "answer": "s/v*100", "round": 2, "prompt": "{v} people visit and {s} sign up. What is the overall conversion rate in percent?", "explain": "{s} divided by {v} is {A}%."}}, {"type": "numeric", "prompt": "Same funnel: of the 500 who opened a recipe, 50 signed up. What is that step's conversion rate in percent?", "answer": 10, "tolerance": 0, "explain": "50 divided by 500 is 10%. Step rates show which step leaks, overall rates show the total effect."}, {"type": "mcq", "prompt": "Visits doubled this month but sign ups stayed flat. What is the most useful first question?", "options": ["Is the site down?", "Where did the new visitors come from, and do they match the people who sign up?", "Should we redesign the form?", "Is analytics broken?"], "answer": 1, "explain": "New traffic from a different audience often converts worse. Segment by source before changing the design."}, {"type": "order", "prompt": "Order how to investigate a drop in sign ups.", "items": ["Confirm the drop is real and not a tracking change", "Find which funnel step changed", "Segment by device and traffic source", "Watch sessions or test that step", "Form a hypothesis and test a fix"], "explain": "Check the measurement first. Many \"drops\" are a broken tag or a changed definition.", "codeItems": false}, {"type": "build", "prompt": "Tag your key actions for analytics. Give your hero's .btn-primary and your signup form's submit button a data-event attribute naming the action, for example data-event=\"hero_cta\" and data-event=\"signup_submit\". Use lowercase words joined by underscores.", "example": "<a class=\"btn-primary\" href=\"#recipes\" data-event=\"hero_cta\">Browse recipes</a>\n...\n<button type=\"submit\" class=\"btn-primary\" data-event=\"signup_submit\">Get the weekly recipes</button>", "explain": "Named events let any analytics tool count the steps of your funnel. Consistent names now save a cleanup later.", "checks": [{"sel": ".hero .btn-primary", "attr": "data-event", "label": "The hero action has a data-event name", "match": "^[a-z]+(_[a-z]+)+$", "hint": "Use lowercase words joined by underscores, for example hero_cta."}, {"sel": "form.signup button[type=\"submit\"]", "attr": "data-event", "label": "The signup submit has a data-event name", "match": "^[a-z]+(_[a-z]+)+$"}]}]}]}, {"title": "Test and structure", "lessons": [{"title": "A/B tests without fooling yourself", "keywords": ["design", "website", "web", "ux", "ab", "testing", "experiment", "split", "lift", "significance", "sample"], "steps": [{"type": "concept", "heading": "An experiment, not a vote", "body": "An A/B test shows two versions to randomly split visitors and compares one metric chosen in advance. Small samples swing wildly by chance, so decide the sample size before starting, run until you reach it, and do not stop the moment the numbers look good. Stopping early on a lucky streak is called peeking, and it produces false wins."}, {"type": "numeric", "prompt": "Version A converts at 4%. Version B converts at 5%. What is B's relative lift over A, in percent?", "answer": 25, "tolerance": 0, "explain": "The difference is 1 percentage point. Relative to A's 4%, that is 1 divided by 4 = 25%. Always say which one you mean.", "gen": {"vars": {"a": [2, 8, 1], "d": [1, 2, 1]}, "answer": "d/a*100", "round": 1, "prompt": "Version A converts at {a}%. Version B converts at {b}%. What is B's relative lift over A, in percent?", "show": {"b": "a+d"}, "explain": "The gap is {d} point(s). Divided by A's {a}%, that is {A}%."}}, {"type": "mcq", "prompt": "After two days B is ahead 12 sign ups to 7. What should you do?", "options": ["Ship B, it is clearly better", "Keep running to the sample size you planned; numbers this small are easily chance", "Stop and restart", "Switch the metric"], "answer": 1, "explain": "With 19 events in total, a 12 to 7 split can easily happen by chance. Planned sample sizes protect you from yourself."}, {"type": "mcq", "prompt": "You test a new headline and check 15 different metrics. One improves. What is the risk?", "options": ["None, a win is a win", "With many metrics, some will move by chance alone; pick the primary metric before the test", "Headlines cannot be tested", "The test was too short"], "answer": 1, "explain": "Check enough numbers and one will look significant by luck. That is why the primary metric is chosen first."}, {"type": "order", "prompt": "Order a trustworthy A/B test.", "items": ["Write a hypothesis and pick one primary metric", "Estimate the sample size you need", "Split traffic randomly and run until you reach it", "Compare results once, at the end", "Ship the winner or learn from the loss"], "explain": "Every step before launch exists to stop you from reading meaning into noise later.", "codeItems": false}, {"type": "write", "prompt": "Write a hypothesis for one test on your landing page in the form: If we change X, then metric Y will improve, because Z.", "checks": [{"has": "\\bif\\b", "flags": "i", "label": "Starts from a change (If...)"}, {"has": "\\bthen\\b", "flags": "i", "label": "Predicts an outcome (then...)"}, {"has": "\\bbecause\\b", "flags": "i", "label": "Gives a reason (because...)"}, {"words": [15, 60], "label": "Between 15 and 60 words"}, {"has": "\\d|rate|sign ?ups?|clicks?|conversion", "flags": "i", "label": "Names a measurable metric"}], "example": "If we replace the generic \"Submit\" button with \"Get the weekly recipes\", then the signup conversion rate will rise, because people will know exactly what they are agreeing to.", "explain": "A reason turns a test into learning: even a loss tells you the reason was wrong."}]}, {"title": "Information architecture", "keywords": ["design", "website", "web", "ux", "information", "architecture", "ia", "card", "sorting", "sitemap", "breadcrumbs", "structure"], "steps": [{"type": "concept", "heading": "Structure people can predict", "body": "Information architecture is how content is grouped and labeled so people can find it. Card sorting asks users to group topics themselves, showing their mental model. Tree testing checks whether people can find items in a proposed structure before you build it. Breadcrumbs show where a page sits in that structure."}, {"type": "mcq", "prompt": "Users keep looking for \"returns\" under Help, but it lives under Orders. What does that tell you?", "options": ["Users are wrong", "Your structure does not match their mental model; move it or link it from both", "Delete the Help section", "Add a search box and stop there"], "answer": 1, "explain": "Put things where people look. Cross-links are fine when an item honestly belongs in two places."}, {"type": "mcq", "prompt": "What does a tree test measure?", "options": ["Visual design", "Whether people can find items using only the structure and labels, without visual design", "Page speed", "SEO rankings"], "answer": 1, "explain": "Stripping the visuals isolates the structure, so you know the labels and grouping are the problem, not the colors."}, {"type": "order", "prompt": "Order an IA project.", "items": ["Inventory the content you have", "Run a card sort with real users", "Draft a structure and labels", "Tree test the draft", "Build navigation and breadcrumbs from it"], "explain": "Know what you have, learn how people group it, then test before you build.", "codeItems": false}, {"type": "build", "prompt": "Add breadcrumbs to your page. Use a nav with aria-label=\"Breadcrumb\" containing an ol with at least two li items. Earlier items are links; the last item is the current page, marked aria-current=\"page\".", "example": "<nav aria-label=\"Breadcrumb\" class=\"crumbs\">\n  <ol>\n    <li><a href=\"index.html\">Home</a></li>\n    <li><a href=\"recipes.html\">Recipes</a></li>\n    <li aria-current=\"page\">Lemon chicken</li>\n  </ol>\n</nav>\n\n/* CSS */\n.crumbs ol { display: flex; gap: 8px; list-style: none; padding: 0; }\n.crumbs li + li::before { content: \"/\"; margin-right: 8px; color: #666; }", "explain": "Breadcrumbs make the structure visible and give people a one-tap way up a level.", "checks": [{"sel": "nav[aria-label=\"Breadcrumb\"] ol", "exists": true, "label": "A nav labeled Breadcrumb with an ordered list"}, {"sel": "nav[aria-label=\"Breadcrumb\"] li", "count": 2, "label": "At least two breadcrumb items"}, {"sel": "nav[aria-label=\"Breadcrumb\"] li a", "exists": true, "label": "Earlier items are links"}, {"sel": "nav[aria-label=\"Breadcrumb\"] [aria-current=\"page\"]", "exists": true, "label": "The current page is marked aria-current=\"page\""}, {"sel": "nav[aria-label=\"Breadcrumb\"] a[aria-current]", "none": true, "label": "The current page is not a link to itself", "hint": "Put aria-current=\"page\" on the last li and leave its text unlinked."}]}, {"type": "concept", "heading": "Labels are the interface", "body": "Most navigation problems are label problems. Test labels with the words your users said in interviews; jargon that is obvious inside the company is noise to everyone else."}]}, {"title": "Accessible by design", "keywords": ["design", "website", "web", "ux", "accessibility", "a11y", "focus", "keyboard", "motion", "reduced", "inclusive"], "steps": [{"type": "concept", "heading": "Design decisions that include people", "body": "Accessibility is mostly design, not code: visible keyboard focus, motion that can be turned off, links that look like links, and meaning not carried by color alone. WCAG requires a visible focus indicator (2.4.7), and operating systems let people ask for reduced motion, which CSS can read with prefers-reduced-motion."}, {"type": "mcq", "prompt": "A designer removes focus outlines because they look ugly. Who is hurt?", "options": ["Nobody", "Keyboard users, who can no longer see where they are on the page", "Only mouse users", "Search engines"], "answer": 1, "explain": "Restyle focus to match the brand with :focus-visible, but never remove it."}, {"type": "mcq", "prompt": "What does @media (prefers-reduced-motion: reduce) let you do?", "options": ["Speed up animations", "Tone down or remove motion for people who set that preference, for example people with vestibular disorders", "Block videos", "Detect slow phones"], "answer": 1, "explain": "Large moving effects can cause dizziness or nausea for some people. Respect the system setting."}, {"type": "order", "prompt": "Order a quick keyboard test of your page.", "items": ["Put the mouse away", "Press Tab from the top of the page", "Check each focused item is clearly visible", "Check you can reach and use every control", "Check focus never gets stuck"], "explain": "If you cannot do it with Tab, Enter and Space, some of your visitors cannot do it at all.", "codeItems": false}, {"type": "build", "prompt": "Make your design accessible by default. Add a :focus-visible style with an outline, a @media (prefers-reduced-motion: reduce) block, and make links inside .prose underlined.", "example": "/* CSS */\n:focus-visible {\n  outline: 3px solid #1f5f3a;\n  outline-offset: 2px;\n}\n@media (prefers-reduced-motion: reduce) {\n  * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }\n}\n.prose a { text-decoration: underline; }\n\n<!-- HTML: a link inside your prose block -->\n<p>Read <a href=\"about.html\">how we test recipes</a>.</p>", "explain": "Focus you can see, motion you can switch off, links that look like links. These help everyone, not just people with disabilities.", "checks": [{"cssContains": ":focus-visible", "label": "A :focus-visible rule"}, {"cssContains": "outline", "label": "Focus uses an outline"}, {"cssContains": "prefers-reduced-motion", "label": "A prefers-reduced-motion media query"}, {"sel": ".prose a", "exists": true, "label": "A link inside .prose"}, {"sel": ".prose a", "style": "textDecorationLine", "label": "Links in .prose are underlined", "equals": "underline"}]}, {"type": "concept", "heading": "Test with real assistive tech", "body": "Automated checkers catch only part of the problems. Spend ten minutes with the screen reader built into your device (VoiceOver on Apple, TalkBack on Android, Narrator on Windows) and you will find issues no tool reports."}]}]}, {"title": "Components and content", "lessons": [{"title": "Components with every state", "keywords": ["design", "website", "web", "ux", "components", "states", "buttons", "hover", "disabled", "loading", "focus", "ui"], "steps": [{"type": "concept", "heading": "A component is all its states", "body": "A button is not one picture. It is default, hover, focus, active, disabled and sometimes loading. Designing only the default leaves developers to guess the rest, and guesses are inconsistent. List the states for every component before calling it done."}, {"type": "mcq", "prompt": "Which state is most often forgotten, and hurts keyboard users most?", "options": ["Hover", "Focus", "Default", "Active"], "answer": 1, "explain": "Hover gets designed because designers use a mouse. Focus is what keyboard users rely on to see where they are."}, {"type": "mcq", "prompt": "A disabled button gives no reason. What is better?", "options": ["Hide the button", "Keep it enabled and explain what is missing when pressed, or show the reason next to it", "Make it red", "Remove the form"], "answer": 1, "explain": "Silent disabled buttons leave people stuck. Tell them what to fix."}, {"type": "order", "prompt": "Order the states a button moves through when someone submits a form.", "items": ["Default", "Hover or focus", "Active (pressed)", "Loading", "Success or error message"], "explain": "Each state answers a question: can I press this, did it register, is it working, did it work.", "codeItems": false}, {"type": "build", "prompt": "Design every state of a .btn class. Add a button with classes btn and btn-primary, plus one disabled button with class btn. In CSS, style .btn:hover, .btn:focus-visible and .btn:disabled (for example lower opacity and cursor: not-allowed).", "example": "<button class=\"btn btn-primary\" type=\"button\">Save recipe</button>\n<button class=\"btn\" type=\"button\" disabled>Saved</button>\n\n/* CSS */\n.btn { min-height: 44px; padding: 0 18px; border-radius: 6px; border: 2px solid #1f5f3a; background: #fff; color: #1f5f3a; }\n.btn:hover { background: #e8f3ec; }\n.btn:focus-visible { outline: 3px solid #1f5f3a; outline-offset: 2px; }\n.btn:disabled { opacity: 0.55; cursor: not-allowed; }", "explain": "Every state is designed, so the button behaves the same everywhere it appears.", "checks": [{"sel": "button.btn.btn-primary", "exists": true, "label": "A button with classes btn and btn-primary"}, {"sel": "button.btn[disabled]", "exists": true, "label": "A disabled .btn"}, {"cssContains": ".btn:hover", "label": "A .btn:hover style"}, {"cssContains": ".btn:focus-visible", "label": "A .btn:focus-visible style"}, {"cssContains": ".btn:disabled", "label": "A .btn:disabled style"}, {"sel": "button.btn[disabled]", "style": "cursor", "label": "Disabled buttons show cursor: not-allowed", "equals": "not-allowed"}]}, {"type": "concept", "heading": "Document as you go", "body": "Write the states down where developers will see them: a short page listing each component, its states and when to use it. That page is the start of a design system."}]}, {"title": "Empty, error and loading states", "keywords": ["design", "website", "web", "ux", "empty", "states", "errors", "messages", "microcopy", "loading", "content", "design"], "steps": [{"type": "concept", "heading": "The screens nobody designs", "body": "A new account has no data. A search finds nothing. A network call fails. These moments decide whether people stay. A good empty state explains what will appear and gives one action to start. A good error message says what happened, why if known, and what to do, in plain words."}, {"type": "mcq", "prompt": "Which error message is best?", "options": ["Error 422", "Something went wrong.", "That card was declined by your bank. Try another card or contact your bank.", "Invalid input!!!"], "answer": 2, "explain": "It says what happened, who can fix it and what to do next, without blame or codes."}, {"type": "mcq", "prompt": "A search returns no results. What should the page show?", "options": ["A blank page", "\"0 results\" only", "What was searched, a suggestion (check spelling, fewer words) and popular links", "An error icon"], "answer": 2, "explain": "Turn the dead end into a next step."}, {"type": "order", "prompt": "Order the parts of a good error message.", "items": ["What happened", "Why, if you know", "What the person can do now", "A way to get help if that fails"], "explain": "Plain facts, then the fix. Leave apologies short and blame out entirely.", "codeItems": false}, {"type": "build", "prompt": "Add an empty state. Create an element with class empty-state containing an h3, a p of explanation, and one link or button with class btn-primary. Mark a status region for messages with role=\"status\".", "example": "<div class=\"empty-state\">\n  <h3>No saved recipes yet</h3>\n  <p>Tap the heart on any recipe and it will wait for you here.</p>\n  <a class=\"btn-primary\" href=\"#recipes\">Find a recipe</a>\n</div>\n<p role=\"status\" class=\"status\"></p>", "explain": "An empty screen that teaches and invites, and a status region screen readers will announce when you put a message in it.", "checks": [{"sel": ".empty-state h3", "exists": true, "label": "An empty state with a heading"}, {"sel": ".empty-state p", "exists": true, "label": "An explanation"}, {"sel": ".empty-state .btn-primary", "max": 1, "min": 1, "label": "Exactly one primary action"}, {"sel": "[role=\"status\"]", "exists": true, "label": "A role=\"status\" region for messages"}]}, {"type": "write", "prompt": "Rewrite this error message so it says what happened and what to do. Keep it under 30 words.", "checks": [{"changed": true, "label": "You rewrote the draft, not just the same text"}, {"words": [6, 30], "label": "Between 6 and 30 words"}, {"not": "\\b(error|invalid|failed|oops)\\b", "flags": "i", "label": "No jargon like error, invalid or failed"}, {"has": "\\b(try|check|use|enter|contact|choose|add)\\b", "flags": "i", "label": "Tells the person what to do next"}], "example": "We could not find that email address. Check the spelling, or create a new account with it.", "explain": "Plain words and a next step turn a dead end into a path. Notice the rewrite never blames the reader.", "starter": "Error: invalid user. Authentication failed (code 401)."}]}, {"title": "Capstone: a pricing page", "keywords": ["design", "website", "web", "ux", "capstone", "pricing", "plans", "comparison", "faq", "conversion", "project"], "steps": [{"type": "concept", "heading": "The brief", "body": "Design a pricing section people can decide from in under a minute. Three plans at most, one recommended, prices and the main differences easy to compare, an action per plan, and answers to the questions that stop people from paying. The plans here are an example for practice, not real pricing advice."}, {"type": "mcq", "prompt": "Why highlight one plan as recommended?", "options": ["To hide the others", "It reduces choice overload by giving a sensible default for most people", "It is required by law", "It makes the page longer"], "answer": 1, "explain": "A clear default helps people decide. It must be honestly the best fit for most visitors."}, {"type": "mcq", "prompt": "Which detail most often stops people at a pricing page?", "options": ["The font", "Unclear terms: what happens after a trial, how to cancel, whether the price is per month or per year", "The number of plans", "The page color"], "answer": 1, "explain": "Uncertainty blocks payment. Answer the cancel and billing questions right there."}, {"type": "order", "prompt": "Order a pricing card's content.", "items": ["Plan name and who it is for", "Price with its period (per month or per year)", "The few features that differ", "The action button"], "explain": "People compare names and prices first, then differences. The button comes after the reason.", "codeItems": false}, {"type": "build", "prompt": "Build the pricing section. Add a section with class pricing holding 2 or 3 elements with class plan. Each plan needs a heading, an element with class price, and a .btn-primary or .btn. Mark exactly one plan with class featured and include a visible label inside it, for example a span with class badge. Add at least two details elements (with summary) answering common questions.", "example": "<section class=\"pricing\">\n  <div class=\"plan\"><h3>Free</h3><p class=\"price\">$0 <small>per month</small></p><a class=\"btn\" href=\"#signup\">Start free</a></div>\n  <div class=\"plan featured\"><span class=\"badge\">Most popular</span><h3>Home cook</h3><p class=\"price\">$4 <small>per month</small></p><a class=\"btn-primary\" href=\"#signup\">Choose Home cook</a></div>\n  <div class=\"plan\"><h3>Family</h3><p class=\"price\">$7 <small>per month</small></p><a class=\"btn\" href=\"#signup\">Choose Family</a></div>\n</section>\n<details><summary>Can I cancel anytime?</summary><p>Yes, in one click from your account page.</p></details>\n<details><summary>Is there a free trial?</summary><p>The Free plan never expires.</p></details>\n\n/* CSS */\n.pricing { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); }\n.plan { border: 1px solid #ccc; border-radius: 8px; padding: 20px; }\n.plan.featured { border: 2px solid #1f5f3a; }", "explain": "A pricing section with a clear default, comparable prices and the doubts answered in place. That is most of what makes people comfortable paying.", "checks": [{"sel": ".pricing .plan", "max": 3, "min": 2, "label": "Two or three plans"}, {"sel": ".pricing .plan.featured", "max": 1, "min": 1, "label": "Exactly one featured plan"}, {"sel": ".plan.featured .badge", "exists": true, "label": "A visible label in the featured plan"}, {"sel": ".pricing .plan .price", "count": 2, "label": "Each plan shows a price"}, {"sel": ".pricing .plan :is(h2, h3, h4)", "count": 2, "label": "Each plan has a heading"}, {"sel": ".pricing .plan :is(.btn-primary, .btn)", "count": 2, "label": "Each plan has an action"}, {"sel": "details summary", "count": 2, "label": "Two or more FAQ items with details and summary"}, {"sel": ".pricing .btn-primary", "contrastMin": 4.5, "label": "Primary actions pass 4.5:1"}]}, {"type": "write", "prompt": "Write the FAQ answer for \"What happens when my trial ends?\" Be specific and calm, in 40 words or fewer.", "checks": [{"words": [8, 40], "label": "Between 8 and 40 words"}, {"has": "\\b(charge|bill|pay|free|cancel|remind|email)", "flags": "i", "label": "Says what happens with billing"}, {"not": "\\b(simply|just|easy|obviously)\\b", "flags": "i", "label": "No minimizing words (simply, just, easy, obviously)"}], "example": "Nothing is charged without warning. We email you 3 days before the trial ends. If you do nothing, your plan renews at $4 per month; cancel in one click before then and you pay nothing.", "explain": "Specific, calm answers to billing questions build the trust that makes people comfortable paying."}, {"type": "concept", "heading": "What you can do now", "body": "You can find out what people need, test whether your design delivers it, measure the result honestly, and design the components and pages that convert. That is evidence-led design."}]}]}]}, {"id": "design-expert", "subject": "Product design", "level": "Expert", "title": "Design systems and strategy", "track": "web", "prereq": "design-advanced", "rev": "2026-10-02", "unlock": {"after": "design-advanced", "mastery": 85, "skill": "UX and conversion"}, "blurb": "Tiered tokens, fluid layout, performance budgets, positioning, metrics, internationalization, critique, ethics.", "units": [{"title": "Systems", "lessons": [{"title": "Tokens in tiers", "keywords": ["design", "website", "web", "ux", "design", "system", "tokens", "semantic", "theming", "dark", "mode", "variables"], "steps": [{"type": "concept", "heading": "Primitives, meanings, components", "body": "Mature design systems layer their tokens. Primitive tokens are raw values (--green-700: #1f5f3a). Semantic tokens give them a job (--color-action: var(--green-700)). Components use only semantic tokens. To add a dark theme or rebrand, you remap the semantic layer and no component changes."}, {"type": "mcq", "prompt": "A button uses var(--green-700) directly. What breaks when you add a dark theme?", "options": ["Nothing", "You must hunt down every component that used the primitive, because nothing says what the green was for", "The button disappears", "CSS variables do not work in dark mode"], "answer": 1, "explain": "Components bound to primitives cannot be re-themed by role. Bind them to semantic names instead."}, {"type": "mcq", "prompt": "Which token name is semantic?", "options": ["--blue-500", "--size-16", "--color-text-muted", "--hex-1f5f3a"], "answer": 2, "explain": "It names the job (muted text), so it can point at a different primitive per theme."}, {"type": "order", "prompt": "Order how to introduce theming to an existing site.", "items": ["Collect the raw colors in use as primitive tokens", "Define semantic tokens that point at primitives", "Replace raw values in components with semantic tokens", "Add a dark theme by remapping only the semantic tokens"], "explain": "Each layer depends on the one before. The payoff, a one-block dark theme, comes last.", "codeItems": false}, {"type": "build", "prompt": "Tier your tokens. In :root, declare at least two primitive color tokens and at least two semantic tokens named --color-something that use var() to point at primitives. Use a semantic token for body text or background. Then add @media (prefers-color-scheme: dark) that remaps the semantic tokens only.", "example": "/* CSS */\n:root {\n  --green-700: #1f5f3a;\n  --gray-950: #141414;\n  --gray-50: #fafaf7;\n  --color-text: var(--gray-950);\n  --color-surface: var(--gray-50);\n  --color-action: var(--green-700);\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --color-text: var(--gray-50);\n    --color-surface: var(--gray-950);\n  }\n}\nbody { color: var(--color-text); background: var(--color-surface); }", "explain": "One remap block themes the whole site. Components never learn which theme they are in.", "checks": [{"cssContains": "prefers-color-scheme: dark", "label": "A prefers-color-scheme: dark block"}, {"cssContains": "--color-", "label": "Semantic tokens named --color-..."}, {"cssContains": ": var(--", "label": "Tokens that point at other tokens with var()", "hint": "Semantic tokens should reference primitives, for example --color-text: var(--gray-950);"}, {"cssContains": "var(--color-", "label": "Your styles use the semantic tokens"}]}, {"type": "concept", "heading": "Name for intent, version for change", "body": "When a design system is shared across teams, treat token names as an API: add new ones freely, rename rarely, and announce removals ahead of time with a deprecation period."}]}, {"title": "Fluid type and container queries", "keywords": ["design", "website", "web", "ux", "fluid", "typography", "clamp", "container", "queries", "responsive", "components"], "steps": [{"type": "concept", "heading": "Respond to the space, not just the screen", "body": "clamp(min, preferred, max) lets a size grow smoothly with the viewport within limits, so headings scale without a pile of breakpoints. Container queries let a component respond to the width of its own container, so the same card works in a sidebar and in a wide grid."}, {"type": "mcq", "prompt": "What does font-size: clamp(1.75rem, 1rem + 3vw, 3rem) do?", "options": ["Always 3rem", "Grows with the viewport but never below 1.75rem or above 3rem", "Shrinks as the screen grows", "Only works on phones"], "answer": 1, "explain": "The middle value tracks the viewport; the outer values are floor and ceiling."}, {"type": "mcq", "prompt": "Why use a container query instead of a media query for a card?", "options": ["Media queries are deprecated", "The card's layout should depend on how wide its slot is, which differs by page, not on the window", "Container queries are faster", "Cards cannot use media queries"], "answer": 1, "explain": "The same card can sit in a narrow column on a wide screen. Only the container knows the real space."}, {"type": "numeric", "prompt": "A heading uses clamp(24px, 4vw, 48px). How many px is it on a 900px wide viewport?", "answer": 36, "tolerance": 0, "explain": "4vw of 900px is 36px, which is between 24 and 48, so 36px applies.", "gen": {"vars": {"w": [400, 1400, 100]}, "answer": "min(48, max(24, w*0.04))", "round": 1, "prompt": "A heading uses clamp(24px, 4vw, 48px). How many px is it on a {w}px wide viewport?", "explain": "4vw of {w}px, kept between 24 and 48, gives {A}px."}}, {"type": "build", "prompt": "Make your hero headline fluid and your benefits respond to their container. Use clamp() for .hero h1 font-size, set container-type: inline-size on .benefits, and add an @container rule that changes the .benefit layout.", "example": "/* CSS */\n.hero h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); }\n.benefits { container-type: inline-size; }\n@container (min-width: 40rem) {\n  .benefit { display: grid; grid-template-columns: auto 1fr; gap: 12px; }\n}", "explain": "Type scales without breakpoints and components adapt to wherever they are placed.", "checks": [{"cssContains": "clamp(", "label": "A clamp() size"}, {"sel": ".hero h1", "style": "fontSize", "label": "The hero headline renders at 24px or more", "minPx": 24}, {"cssContains": "container-type", "label": "A container-type declaration"}, {"cssContains": "@container", "label": "An @container rule"}, {"sel": ".benefits .benefit", "exists": true, "label": "Your .benefits section from the Intermediate capstone", "hint": "Add a section with class benefits holding items with class benefit (see Capstone: a landing page that works)."}]}, {"type": "order", "prompt": "Order how to make a component responsive the modern way.", "items": ["Give its wrapper container-type: inline-size", "Design the narrow layout as the default", "Add @container rules for wider slots", "Use clamp() for sizes that should scale smoothly"], "explain": "Narrow first, then enhance as space allows.", "codeItems": false, "groups": [[2, 3]], "orderNote": "Container rules and clamp() sizes are independent, so either can come third."}]}, {"title": "Performance as a design constraint", "keywords": ["design", "website", "web", "ux", "performance", "core", "web", "vitals", "lcp", "cls", "inp", "speed", "images"], "steps": [{"type": "concept", "heading": "Three numbers Google publishes", "body": "Core Web Vitals measure loading, responsiveness and visual stability. Google's published thresholds for a good experience are Largest Contentful Paint at or under 2.5 seconds, Interaction to Next Paint at or under 200 milliseconds, and Cumulative Layout Shift at or under 0.1, measured at the 75th percentile of real visits. Design choices (huge hero images, web fonts, late-loading banners) move these numbers more than code tweaks."}, {"type": "mcq", "prompt": "A cookie banner slides in after load and pushes the page down. Which metric suffers?", "options": ["LCP", "INP", "CLS", "None"], "answer": 2, "explain": "Content moving after it appears is layout shift. Reserve the space or overlay the banner instead."}, {"type": "mcq", "prompt": "Which design change most reliably improves LCP on a page with a big hero photo?", "options": ["Adding more fonts", "Serving a properly sized, compressed hero image and not lazy-loading it", "Lazy-loading the hero image", "Adding a carousel"], "answer": 1, "explain": "The hero is usually the largest element. Make it small in bytes and load it first; lazy-loading it delays it."}, {"type": "mcq", "prompt": "Of 100 sampled page loads, 80 have LCP at or under 2.5 s. Does the page meet the good LCP threshold at the 75th percentile?", "options": ["Yes, at least 75% of loads are at or under 2.5 s", "No, every load must be under 2.5 s", "No, the average must be under 1 s", "It cannot be known from this"], "answer": 0, "explain": "The 75th percentile is good when at least 75% of loads are good. 80% are, so it passes."}, {"type": "build", "prompt": "Stop your images from shifting the layout. Make sure there is at least one image below your hero (an https image URL works). Every img on your page needs width and height attributes, and every image outside the hero needs loading=\"lazy\".", "example": "<img src=\"https://picsum.photos/id/292/800/450\" width=\"800\" height=\"450\" alt=\"Ingredients on a table\">\n<img src=\"https://picsum.photos/id/429/600/400\" width=\"600\" height=\"400\" loading=\"lazy\" alt=\"A finished dish\">", "explain": "With dimensions the browser reserves space before the image arrives, so nothing jumps. Lazy loading keeps offscreen images from competing with the hero.", "checks": [{"sel": "img", "exists": true, "label": "At least one image on the page"}, {"sel": "img", "attr": "width", "label": "Every image has a width", "match": "^\\d+$", "every": true}, {"sel": "img", "attr": "height", "label": "Every image has a height", "match": "^\\d+$", "every": true}, {"sel": ".hero img[loading=\"lazy\"]", "none": true, "label": "The hero image is not lazy-loaded", "hint": "Lazy-loading the largest image delays LCP. Keep loading=\"lazy\" for images further down."}, {"sel": "img:not(.hero img)", "attr": "loading", "label": "Images outside the hero use loading=\"lazy\"", "match": "^lazy$", "every": true}]}, {"type": "order", "prompt": "Order a performance budget for a new page.", "items": ["Agree target numbers (for example LCP at or under 2.5 s)", "Set a byte budget for images, fonts and scripts", "Design within it and check as you go", "Measure real visits after launch"], "explain": "A budget agreed before design is far cheaper than shaving bytes after launch.", "codeItems": false}]}]}, {"title": "Strategy", "lessons": [{"title": "Jobs to be done and positioning", "keywords": ["design", "website", "web", "ux", "strategy", "jobs", "positioning", "value", "proposition", "competitors", "product"], "steps": [{"type": "concept", "heading": "People hire products for a job", "body": "Jobs to be done frames demand as progress people want in a situation: \"When I get home tired on a weeknight, I want dinner sorted fast, so I can rest.\" The real competition is whatever people do today for that job, often not a direct rival. Positioning states who you are for, the job, and why you beat the alternative they use now."}, {"type": "mcq", "prompt": "For a weeknight recipe site, what is often the strongest competitor?", "options": ["Other recipe sites only", "Takeout, frozen meals and cooking the same three dishes", "Cookbooks from the 1990s", "Social networks"], "answer": 1, "explain": "People compare you with what they already do for the job. Design and messaging must beat that habit."}, {"type": "mcq", "prompt": "Which is a job statement rather than a feature?", "options": ["Has a shopping list button", "When I'm planning the week, I want to buy everything in one trip, so I don't waste evenings", "Uses a modern design", "Loads in 2 seconds"], "answer": 1, "explain": "It names the situation, the motivation and the outcome. Features are only means to that end."}, {"type": "order", "prompt": "Order the parts of a positioning statement.", "items": ["For (the specific audience)", "Who (the job or problem)", "Our product is (the category)", "That (the key benefit)", "Unlike (the main alternative)"], "explain": "This classic template forces you to name both the audience and the real alternative.", "codeItems": false}, {"type": "write", "prompt": "Write a positioning statement for your site using the template: For [audience] who [job], [product] is a [category] that [benefit]. Unlike [alternative], it [difference].", "checks": [{"has": "^\\s*for\\b", "flags": "i", "label": "Starts with For"}, {"has": "\\bwho\\b", "flags": "i", "label": "Names the job with who"}, {"has": "\\bthat\\b", "flags": "i", "label": "States the benefit with that"}, {"has": "\\bunlike\\b", "flags": "i", "label": "Names the alternative with unlike"}, {"words": [25, 80], "label": "Between 25 and 80 words"}, {"confirm": true, "label": "The alternative is what people really do today, not just a direct competitor"}], "example": "For working parents who need dinner sorted on weeknights, Casa Verde is a recipe site that gets a tested meal on the table in 30 minutes. Unlike takeout, it costs less and you know what is in it.", "explain": "A precise positioning statement settles arguments about headlines, features and visuals: does this help this audience get this job done better than their alternative?"}, {"type": "concept", "heading": "Let positioning drive the page", "body": "Your hero headline is the benefit. Your benefits section is the difference from the alternative. Your proof shows people like the audience getting the job done. A page that follows its positioning rarely needs a redesign; it needs better evidence."}]}, {"title": "Metrics that matter", "keywords": ["design", "website", "web", "ux", "metrics", "north", "star", "guardrails", "goodhart", "retention", "cohorts", "measurement"], "steps": [{"type": "concept", "heading": "One goal, a few guardrails", "body": "A north star metric captures the value users get (for a recipe site, perhaps recipes cooked per week, not page views). Guardrail metrics stop you from winning the wrong way: unsubscribes, complaints, page speed. Goodhart's law warns that when a measure becomes a target, people find ways to move it that stop it meaning anything."}, {"type": "mcq", "prompt": "A team is rewarded for time on site. Which design change games it?", "options": ["Faster recipe search", "Hiding the ingredient list behind extra clicks", "A clearer shopping list", "Bigger buttons"], "answer": 1, "explain": "Making people work harder increases time on site while making the product worse. That is Goodhart's law in action."}, {"type": "numeric", "prompt": "Of 400 people who signed up in March, 120 cooked a recipe in their fourth week. What is week-4 retention for the March cohort, in percent?", "answer": 30, "tolerance": 0, "explain": "120 divided by 400 is 30%. Cohorts compare like with like: people who started at the same time.", "gen": {"vars": {"n": [200, 1000, 100], "r": [10, 50, 5]}, "answer": "r", "round": 0, "show": {"k": "n*r/100"}, "prompt": "Of {n} people who signed up in March, {k} were active in week 4. What is week-4 retention, in percent?", "explain": "{k} divided by {n} is {A}%."}}, {"type": "mcq", "prompt": "Why measure retention by cohort instead of total active users?", "options": ["It is simpler", "Totals can grow from new sign ups even while each group of users drifts away faster", "Cohorts are required by analytics tools", "Totals are always wrong"], "answer": 1, "explain": "A growing total can hide a leaking bucket. Cohorts show whether people keep getting value."}, {"type": "write", "prompt": "Define a north star metric for your site and two guardrail metrics. Put each on its own line, starting with North star:, Guardrail:, Guardrail:.", "checks": [{"has": "north star\\s*:", "flags": "i", "label": "A line starting North star:"}, {"has": "guardrail\\s*:[\\s\\S]*guardrail\\s*:", "flags": "i", "label": "Two Guardrail: lines"}, {"lines": 3, "label": "Three lines"}, {"not": "north star\\s*:[^\\n]*(page ?views|visits|time on site|sessions)", "flags": "i", "label": "The north star is not a raw traffic number"}, {"confirm": true, "label": "The north star measures value a user got, not attention you captured"}], "example": "North star: recipes marked as cooked per active user per week\nGuardrail: email unsubscribe rate\nGuardrail: median page load time on phones", "explain": "A value-based north star with guardrails keeps the team honest: you can only win by helping people."}, {"type": "order", "prompt": "Order how to choose a product metric.", "items": ["Describe the value users get in words", "Find a behavior that shows they got it", "Make it a countable metric", "Add guardrails for the ways it could be gamed", "Review it after a few months"], "explain": "Words first. Teams that start from what is easy to count end up optimizing what is easy, not what matters.", "codeItems": false}]}, {"title": "Design for every language", "keywords": ["design", "website", "web", "ux", "internationalization", "i18n", "localization", "language", "rtl", "logical", "properties", "inclusive"], "steps": [{"type": "concept", "heading": "Text grows, direction flips", "body": "Translated text is often longer than English (German and Finnish labels can be much longer), and Arabic and Hebrew read right to left. Designs that fit English exactly will break. Leave room for text to grow, avoid text baked into images, and use CSS logical properties (margin-inline-start instead of margin-left) so layouts flip correctly with dir=\"rtl\"."}, {"type": "mcq", "prompt": "Why use padding-inline-start instead of padding-left?", "options": ["It is shorter", "It follows the text direction, so in right-to-left languages it becomes the right side automatically", "padding-left is deprecated", "It is faster"], "answer": 1, "explain": "Logical properties map to start and end of the text flow, not to fixed physical sides."}, {"type": "mcq", "prompt": "A quote in Spanish appears on an English page. What markup helps screen readers pronounce it correctly?", "options": ["<i>", "lang=\"es\" on the element containing the quote", "translate=\"no\"", "A Spanish font"], "answer": 1, "explain": "WCAG 3.1.2 asks you to mark changes of language so assistive technology switches pronunciation."}, {"type": "order", "prompt": "Order the steps to make a page ready for translation.", "items": ["Move all text out of images", "Leave room for text to grow in buttons and labels", "Switch physical CSS sides to logical properties", "Mark the page and any passages with lang", "Test with a long language and a right-to-left one"], "explain": "Each step removes one way translation breaks the layout. The final test proves it.", "codeItems": false, "groups": [[0, 1, 2, 3]], "orderNote": "The first four fixes are independent; do them in any order, then test last."}, {"type": "build", "prompt": "Make your page translation ready. Add a short passage in another language marked with a lang attribute (for example a quote with lang=\"es\"), and use at least one CSS logical property such as margin-inline, padding-inline-start or inset-inline-start.", "example": "<blockquote lang=\"es\">Cocinar en casa es más fácil de lo que parece.</blockquote>\n\n/* CSS */\n.benefit { padding-inline-start: var(--space-2, 16px); border-inline-start: 4px solid var(--color-action, #1f5f3a); }", "explain": "Marked language changes and direction-aware spacing. The page is ready for a right-to-left version without a rewrite.", "checks": [{"sel": "[lang]:not(html)", "exists": true, "label": "An element with a lang attribute"}, {"sel": "[lang]:not(html)", "attr": "lang", "label": "The lang value is a language code", "match": "^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$"}, {"cssContains": "-inline", "label": "A CSS logical property (for example padding-inline-start)"}]}, {"type": "concept", "heading": "Localization is more than words", "body": "Dates, numbers, currencies, names and addresses vary by region. Let the platform format them (Intl in JavaScript) and design forms that accept names and addresses that do not look like yours."}]}]}, {"title": "Leading design", "lessons": [{"title": "Critique and handoff", "keywords": ["design", "website", "web", "ux", "critique", "feedback", "handoff", "review", "collaboration", "specs", "developers"], "steps": [{"type": "concept", "heading": "Critique the work against the goal", "body": "Useful critique starts from the goal and the audience, describes what you observe, and asks questions before prescribing fixes. \"I like it\" and \"make it pop\" help nobody. Handoff is the same discipline aimed at developers: every state, spacing and token named, edge cases listed, and decisions explained so they are not re-litigated in code."}, {"type": "mcq", "prompt": "Which piece of feedback is most useful?", "options": ["I don't love the green.", "Make it pop more.", "The goal is sign ups, but my eye lands on the logo first; could the headline or button be the strongest element?", "Looks great!"], "answer": 2, "explain": "It ties an observation to the goal and invites a solution instead of dictating one."}, {"type": "mcq", "prompt": "What most often goes missing in a design handoff?", "options": ["The logo", "Empty, error, loading and long-content states", "The brand color", "The page title"], "answer": 1, "explain": "The happy path is always designed. Edge states are where developers have to guess."}, {"type": "order", "prompt": "Order a design critique session.", "items": ["The designer states the goal and the audience", "Reviewers look silently for a few minutes", "Reviewers share observations tied to the goal", "The designer asks clarifying questions", "Agree next steps and owners"], "explain": "Starting from the goal keeps the session about outcomes, not taste.", "codeItems": false}, {"type": "write", "prompt": "Write critique for this hero, aimed at its goal of email sign ups. Headline: \"Innovation in every bite\". Three equal buttons: Sign up, Learn more, Our story. Use three lines: one observation, one question, one suggestion.", "checks": [{"lines": 3, "label": "Three lines"}, {"has": "\\?", "flags": "i", "label": "At least one question"}, {"not": "\\b(i (don't )?like|ugly|pretty|pop)\\b", "flags": "i", "label": "No taste words (I like, ugly, pretty, pop)"}, {"has": "\\b(goal|sign ?ups?|signup|email)\\b", "flags": "i", "label": "Ties the feedback to the sign up goal"}], "example": "Observation: the headline does not say what the site offers, and three equal buttons compete for attention.\nQuestion: which single action matters most for the sign up goal?\nSuggestion: try a specific headline about weeknight dinners and make Sign up the only primary button.", "explain": "Observation, question, suggestion, tied to the goal: critique the designer can act on without feeling judged."}, {"type": "concept", "heading": "Write decisions down", "body": "A short decision log (what we chose, why, what we rejected) saves weeks. When someone asks in six months why the button is green, the answer is a link, not a meeting."}]}, {"title": "Dark patterns and design ethics", "keywords": ["design", "website", "web", "ux", "ethics", "dark", "patterns", "deceptive", "consent", "manipulation", "trust"], "steps": [{"type": "concept", "heading": "Persuasion versus manipulation", "body": "Dark patterns are designs that trick people into choices they would not make knowingly: hiding the cancel path, pre-ticked add-ons, shaming decline buttons (\"No thanks, I hate saving money\"), fake countdown timers. They can lift a metric briefly while destroying trust, and regulators in several regions treat many of them as unlawful. Good design makes the honest choice the easy one."}, {"type": "mcq", "prompt": "Signing up takes one click but cancelling needs a phone call during office hours. What is this pattern often called?", "options": ["A funnel", "A roach motel: easy to get in, hard to get out", "Progressive disclosure", "A guardrail"], "answer": 1, "explain": "Cancellation should be about as easy as sign up. Many regulators now say so explicitly."}, {"type": "mcq", "prompt": "Which is honest persuasion rather than a dark pattern?", "options": ["A timer that resets on every visit", "A pre-ticked box adding insurance to the cart", "A clear comparison table with the recommended plan highlighted", "A decline link styled as tiny gray text"], "answer": 2, "explain": "Highlighting a genuinely good default with full information helps people decide. The others hide or pressure."}, {"type": "order", "prompt": "Order an ethics check for a new flow.", "items": ["Write down what the user is agreeing to", "Check the honest choice is as easy as the business choice", "Remove pressure that is not true (fake scarcity, false urgency)", "Ask: would we be comfortable if users saw how this works?"], "explain": "If explaining the design to users would embarrass you, it is a dark pattern.", "codeItems": false}, {"type": "write", "prompt": "Rewrite this confirmshaming pop-up so both choices are respectful and clear.", "checks": [{"changed": true, "label": "You rewrote the draft, not just the same text"}, {"not": "\\b(hate|stupid|lose out|miss out|regret|i don't want to)\\b", "flags": "i", "label": "No shaming or guilt words"}, {"has": "\\bno thanks\\b|\\bnot now\\b|\\bmaybe later\\b|\\bno,? thank you\\b", "flags": "i", "label": "A plain, neutral decline option"}, {"words": [8, 40], "label": "Between 8 and 40 words"}], "example": "Get one tested weeknight recipe by email every Friday.\n[Subscribe]   [No thanks]", "explain": "Respectful choices keep the people who say yes for the right reasons, and the people who say no will come back.", "starter": "Get our weekly recipes!\n[Yes, I want to eat better]   [No, I hate delicious food]"}, {"type": "concept", "heading": "Ethics is a design skill", "body": "Every metric you are asked to move can be moved honestly or dishonestly. Naming the dark pattern in a review, with a better alternative ready, is one of the most valuable things a senior designer does."}]}, {"title": "Capstone: ship a design system page", "keywords": ["design", "website", "web", "ux", "capstone", "design", "system", "audit", "project", "launch", "tokens"], "steps": [{"type": "concept", "heading": "The brief", "body": "Bring the whole ladder together into a page you could hand to a team: tiered tokens with a dark theme, fluid type, responsive components, accessibility defaults, stable images, marked language changes, and evidence from real people. Prexis checks the page; you confirm the research you ran outside it."}, {"type": "mcq", "prompt": "A stakeholder asks for a fake \"Only 2 left!\" badge to lift sign ups. Your best response?", "options": ["Add it, metrics matter", "Decline and offer an honest alternative, such as a real testimonial or a clearer benefit, and test that", "Add it only on mobile", "Add it and remove it later"], "answer": 1, "explain": "Offer a better, honest lever and evidence. That is the senior move."}, {"type": "order", "prompt": "Order a design release.", "items": ["Audit the current page against the goal", "Run a small usability round", "Fix the worst problems with system components", "Check accessibility and performance budgets", "Ship and watch the north star and guardrails"], "explain": "Evidence, then fixes, then quality gates, then measurement.", "codeItems": false}, {"type": "build", "prompt": "Ship the system page. Your site needs: semantic --color tokens with a prefers-color-scheme: dark remap; a clamp() hero headline; a container query; a :focus-visible style and a prefers-reduced-motion block; every img with width and height; a passage marked with lang; a .hero with one .btn-primary that passes contrast; and confirm the research you ran.", "example": "Use your work from this course and the Intermediate and Advanced courses.", "explain": "Tokens, fluid layout, accessibility, performance and evidence in one page. You can now lead design, not just do it.", "checks": [{"cssContains": "var(--color-", "label": "Components use semantic tokens"}, {"cssContains": "prefers-color-scheme: dark", "label": "A dark theme remap"}, {"cssContains": "clamp(", "label": "Fluid type with clamp()"}, {"cssContains": "@container", "label": "A container query"}, {"cssContains": ":focus-visible", "label": "Visible focus"}, {"cssContains": "prefers-reduced-motion", "label": "Reduced motion respected"}, {"sel": "img", "attr": "width", "label": "Every image has width", "match": "^\\d+$", "every": true}, {"sel": "img", "attr": "height", "label": "Every image has height", "match": "^\\d+$", "every": true}, {"sel": "[lang]:not(html)", "exists": true, "label": "A language change marked with lang"}, {"sel": ".hero .btn-primary", "max": 1, "min": 1, "label": "One primary action in the hero"}, {"sel": ".hero .btn-primary", "contrastMin": 4.5, "label": "The hero action passes 4.5:1"}, {"confirm": true, "label": "I ran a usability round with at least three people and fixed the worst problem"}, {"confirm": true, "label": "I checked contrast in both light and dark themes"}]}, {"type": "write", "prompt": "Write a short release note for your team: what changed, the evidence behind it, and the metric you will watch. Under 80 words.", "checks": [{"words": [25, 80], "label": "Between 25 and 80 words"}, {"has": "\\b(tested|interview|usability|participants?|users?|people)\\b", "flags": "i", "label": "Mentions the evidence"}, {"has": "\\b(metric|rate|retention|conversion|north star|guardrail|watch|measure)\\b", "flags": "i", "label": "Names what you will measure"}], "example": "We rebuilt the landing page on the new tokens with a dark theme. In a usability round, 4 of 5 people missed the old signup button, so the hero now has one primary action. We will watch the signup conversion rate and the unsubscribe guardrail for four weeks.", "explain": "Linking the change to evidence and to a metric is how design earns trust in a team."}, {"type": "concept", "heading": "What you can do now", "body": "You can build and run a design system, ground decisions in research and metrics, design for every language and ability, and argue for the honest choice with evidence. That is design leadership."}]}]}]}], "quickPicks": [], "overlay": {"core-js": {"track": "code", "blurb": "Bindings, lists, errors, async, objects, closures, reduce, copies."}, "web-pages": {"track": "web", "blurb": "HTML, CSS, box model, flex, grid, accessibility."}, "site-design": {"track": "web", "prereq": "web-pages", "blurb": "Hierarchy, type, copy, hosting."}, "seo": {"track": "web", "prereq": "site-design", "blurb": "Crawlers, titles, intent."}, "math": {"track": "quant", "blurb": "Percents, rates, probability."}, "thinking": {"track": "thinking", "blurb": "Arguments, correlation, estimation, bias."}, "money": {"track": "money", "blurb": "Pay yourself first, debt, investing."}, "sheets": {"track": "quant", "blurb": "Cells, references, functions, pivots."}, "writing": {"track": "writing", "blurb": "Fog, paragraphs, emails, revision."}}};

(function () {
  const extra = window.PREXIS_EXTRA;
  const root = window.PREXIS_CONTENT;
  if (!root || !extra) return;
  const overlay = extra.overlay || {};
  (root.courses || []).forEach((c) => {
    const o = overlay[c.id];
    if (!o) return;
    if (o.track) c.track = o.track;
    if (o.prereq) c.prereq = o.prereq;
    if (o.blurb) c.blurb = o.blurb;
  });
  root.courses = (root.courses || []).concat(extra.courses || []);
  root.quickPicks = (root.quickPicks || []).concat(extra.quickPicks || []);
})();
